using BecquerelMonitor.EfficiencyMaker;
using Microsoft.Data.Sqlite;
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;

namespace BecquerelMonitor.FullSpectrumAnalysis
{
    /// <summary>
    /// Одна цепочка в составе пробы: корень ряда и, при надобности, ограничение
    /// на его членов.
    ///
    /// <see cref="Only"/> нужен ровно для одного случая, и случай этот в корпусе
    /// есть: урановое стекло (`U-238u`). Ряд в нём ОБОРВАН на радии — уран в
    /// стекло попал химически очищенным, и равновесия ниже Ra-226 нет. Взять
    /// такому образцу весь ряд значит предъявить ему Bi-214 и Pb-214, которых в
    /// нём нет, и отдать им структуру. Список членов повторяет
    /// `build_corpus.sample_lines`, где то же самое сделано для калибровки.
    /// Пусто — брать весь ряд.
    /// </summary>
    public sealed class FsaSampleChain
    {
        public FsaSampleChain(string root)
        {
            this.Root = root;
        }

        public FsaSampleChain(string root, params string[] only)
        {
            this.Root = root;
            if (only != null)
            {
                foreach (string member in only)
                {
                    this.Only.Add(member);
                }
            }
        }

        /// <summary>`nucid` корня ряда: «232TH», «238U».</summary>
        public string Root;

        /// <summary>`nucid` членов, которыми ряд ограничен; пусто — весь ряд.</summary>
        public readonly HashSet<string> Only =
            new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        /// <summary>
        /// (`AMBER119`, П168 28.09.2026) Корень ОБЪЯВЛЕН человеком — меткой ряда
        /// набора (`NuclideDefinition.Chain`), манифестом или ключом: тогда доли
        /// членов несут множитель переходного равновесия (`AMBER55`), потому что
        /// «корень» здесь — отделённый источник, распадающийся со своим периодом.
        /// <c>false</c> — корень ВЫВЕДЕН разбором из подписи без ряда (линия
        /// Pb-214 без «(Ra-226)»): это лишь верхний видимый член, кто его питает —
        /// неизвестно, и в пробе из природы он запитан долгоживущим предком, так
        /// что множитель — единица (вековое равновесие). Асимптота незапитанного
        /// корня (Bi-214 ×3.68 от Pb-214) давала строке Pb-214 −73 %, Bi-214
        /// +10 % на `G1S24_Ra226_Petri`.
        /// </summary>
        public bool Transient = true;

        /// <summary>
        /// Метки рядов, которые понимает <see cref="FromLabel"/>, — словарь
        /// колонки `chains` корпусного `manifest.csv` и ключей `--chain=` проб.
        /// Для сообщения об отказе, чтобы человек видел, из чего выбирать.
        /// Последняя строка — не метка, а ПРАВИЛО (`T259`): любой распадающийся
        /// нуклид `nucdb` в записи «Xx-NNN» — корень подряда от этого члена.
        /// </summary>
        public static readonly string[] KnownLabels =
            { "Th-232", "Th-228", "Ra-226", "U-238", "U-235", "U-238u",
              "и любой распадающийся нуклид nucdb как «Xx-NNN» — подряд от этого члена (Rn-222, Rn-220, Pb-214…; T259)" };

        /// <summary>
        /// Метка ряда в `manifest.csv` (и в ключе `--chain=` проб) → ряд `nucdb`.
        /// Неизвестная метка — <c>null</c>: читатель манифеста на ней ОТКАЗЫВАЕТ,
        /// а не подбирает ближайшее — состав спектра есть истина, и опечатка в
        /// ней должна останавливать прогон, а не менять его молча.
        ///
        /// ПРАВИЛО ОДНО (`T259`, решение Amber 14.09.2026 «Обе одной полосой
        /// ночью», П72): метка «Xx-NNN» — это `nucid` члена ряда, и ряд идёт ОТ
        /// ЭТОГО ЧЛЕНА ВНИЗ по `decay_chain` (<see cref="FsaSampleLibrary.ChainBranches"/>),
        /// пока равновесие с корнем возможно — член с периодом ДЛИННЕЕ корня
        /// обрывает подряд вместе со всем, что под ним
        /// (<see cref="FsaSampleLibrary.EquilibriumMembers"/>). Так «Ra-226» —
        /// весь радиевый ряд (Pb-210 22 г короче 1600 л и растёт с ним), а
        /// «Rn-222» (радон в угле, на фильтре) — Po-218, Pb-214, Bi-214, Po-214
        /// БЕЗ Pb-210: 22 года против 3.8 суток корня, его в пробе нет, и связка
        /// равновесия (`S70`) ему амплитуду навязывать не должна. Головы рядов
        /// (Th-232, Ra-226, U-238, U-235) и Th-228 — тот же случай правила:
        /// у них нет члена длиннее корня, и состав от правила не меняется
        /// (проверено побитово, `--chain=Ra-226` на П72). ⛔ Имён нуклидов
        /// здесь нет: метка → `nucid` разбором (<see cref="FsaSampleLibrary.NucidOf"/>),
        /// «распадается ли» — по `nuclides.half_life_sec` базы
        /// (<see cref="FsaSampleLibrary.IsDecaying"/>); неизвестный базе или
        /// стабильный «корень» — отказ, а не пустой ряд.
        ///
        /// `U-238u` стоит особняком нарочно: это урановое СТЕКЛО, где ряд
        /// оборван на радии — уран попал в стекло химически очищенным, и
        /// равновесия ниже Ra-226 нет; правилом периода это не выразить (U-234
        /// 2.5·10⁵ л короче U-238 и в равновесии с ним, а Th-230 и всё ниже
        /// вымыто химией, не временем). Список членов повторяет
        /// `build_corpus.sample_lines`, где то же самое сделано для калибровки;
        /// два разных ответа на вопрос «что излучает урановое стекло» в проекте
        /// держать нельзя.
        ///
        /// ⛔ ЭТО ЕДИНСТВЕННОЕ МЕСТО СЛОВАРЯ (`T257`). До 12.09.2026 таблица жила в
        /// `CorpusFsaProbe.ChainOf`, а пробы каналов (`FsaChannelSplitProbe`,
        /// `FsaDoubleCountProbe`) переводили метку в nucid своим `NucidOf` —
        /// «Th-232» → «232TH» без всякого списка, то есть `U-238u` у них дал бы
        /// корень «238uU» и ряд без единой линии, молча. Читатели на питоне
        /// (`tools/pie/score.py`, `tools/CORPUS/scripts/chain_labels.py`) несут
        /// ТО ЖЕ правило теми же тремя шагами — разбор, `half_life_sec`, обрыв
        /// по периоду; менять его здесь без них нельзя.
        /// </summary>
        public static FsaSampleChain FromLabel(string label)
        {
            if (label == "U-238u")
            {
                return new FsaSampleChain("238U", "238U", "234TH", "234PAm1", "234PA", "234U");
            }

            string nucid = FsaSampleLibrary.NucidOf(label);
            if (nucid.Length == 0 || !FsaSampleLibrary.IsDecaying(nucid))
            {
                return null;
            }

            return new FsaSampleChain(nucid);
        }
    }

    /// <summary>
    /// Что снято этим спектром и чем оно снято — вход
    /// <see cref="FsaSampleLibrary"/>.
    ///
    /// Заполняется тем, кто про спектр это знает: для корпуса — `manifest.csv`
    /// и `materials.csv` (проба `CorpusFsaProbe`), в приложении — объявленный
    /// состав документа. Сам сборщик ничего не угадывает.
    /// </summary>
    public sealed class FsaSampleSpec
    {
        /// <summary>Ряды в пробе.</summary>
        public readonly List<FsaSampleChain> Chains = new List<FsaSampleChain>();

        /// <summary>Одиночные нуклиды поверх рядов: `nucid`, «40K», «176LU».</summary>
        public readonly List<string> Nuclides = new List<string>();

        /// <summary>Z элементов ПРОБЫ — вольфрам электрода WT-20, лютеций Lu₂O₃.</summary>
        public readonly List<int> SampleElements = new List<int>();

        /// <summary>Z элементов КРИСТАЛЛА — иод и цезий у CsI, иод у NaI.</summary>
        public readonly List<int> CrystalElements = new List<int>();

        /// <summary>
        /// МАССОВЫЕ доли элементов кристалла, Z → доля (`S84`, 19.08.2026).
        /// Пусто — доли неизвестны, и тогда образ вылета считает их равными.
        ///
        /// Заведены потому, что вылет у кристалла ОДИН на все его элементы, а
        /// соотношение членов внутри него задаётся не данными, а веществом:
        /// вероятность того, что первое взаимодействие оказалось K-поглощением
        /// именно в элементе i, равна w_i·τ_i,K / Σ_j w_j·μ_j. Доли лежат прямо
        /// в геометрии (<c>GeometryMaterial.Fractions</c>), и до 19.08.2026
        /// <see cref="HeavyElementsOf"/> их просто выбрасывала, оставляя одни
        /// номера.
        /// </summary>
        public readonly Dictionary<int, double> CrystalFractions =
            new Dictionary<int, double>();

        /// <summary>
        /// Короткое имя вещества кристалла — «CsI», «NaI», «LaBr3». Им зовётся
        /// образ вылета (`Esc-CsI`), чтобы читатель видел, из чего прибор
        /// считает вылет, а не только то, что вылет есть. Пусто — имя
        /// собирается из символов элементов по убыванию доли.
        /// </summary>
        public string CrystalName = "";

        /// <summary>
        /// ИМЯ ВЕЩЕСТВА КРИСТАЛЛА В БИБЛИОТЕКЕ — ссылка, а не подпись
        /// (`A276`, решение Amber 06.09.2026). Ставится общим входом
        /// <see cref="OfSpectrum"/> из конфигурации прибора спектра
        /// (<c>DeviceConfigInfo.CrystalMaterialName</c>); у корпусных приборов
        /// поле не названо (пусто) — там кристалл приходит геометрией.
        ///
        /// ⛔ Это НЕ <see cref="CrystalName"/>. То — короткая подпись образа
        /// («CsI»), собираемая в том числе из символов элементов; это — имя
        /// строки библиотеки веществ («Cesium iodide»), по которому берётся
        /// состав. Свести их в одно поле нельзя: подпись бывает выдумана
        /// самим сборщиком, а по выдуманному имени состава не найти.
        ///
        /// ⛔ ГЕОМЕТРИЯ ПЕРВИЧНА: пока <see cref="CrystalFractions"/> непусты,
        /// это поле не читается вовсе (<see cref="FsaSampleLibrary.CrystalFractionsOf"/>).
        /// </summary>
        public string CrystalMaterialName = "";

        /// <summary>Z элементов ЗАЩИТЫ И ОБВЯЗКИ — свинец домика, железо корпуса.</summary>
        public readonly List<int> ShieldElements = new List<int>();

        /// <summary>
        /// (`AMBER306`) Образы подписей, которых в базах нет: линии вбиты руками
        /// (<see cref="FsaLibrary.BuildFromLabels"/>). Ложатся в состав наравне с
        /// образами распада: вылет и аннигиляция считаются и от них.
        /// </summary>
        public readonly List<FsaComponent> TypedComponents = new List<FsaComponent>();

        /// <summary>
        /// Нижняя граница рабочего диапазона, кэВ. Ставится вызывающим из
        /// `Min_Range` прибора — то есть из настройки ПОИСКА ПИКОВ.
        ///
        /// ⚠ С 25.08.2026 линии режет НЕ она, а <see cref="LineFloorKev"/>:
        /// диапазон поиска пиков и полоса, в которой модель имеет право
        /// говорить, — разные вещи (`S98`).
        /// </summary>
        public double MinEnergyKev = 10.0;

        /// <summary>Верхняя граница рабочего диапазона, кэВ.</summary>
        public double MaxEnergyKev = 3200.0;

        /// <summary>
        /// Как сводятся полоса фита и полоса библиотеки (`S98`).
        ///
        /// ⛔ ЧИТАЕТСЯ, А НЕ ХРАНИТСЯ (`S101`, измерено 26.08.2026). Здесь
        /// стояло ПОЛЕ с копией <see cref="FsaBand.DefaultMode"/>, снятой в
        /// момент создания спецификации, и такая же копия — у
        /// <see cref="FsaAnalyzer"/>. Двигали обычно вторую (полоса объявлена
        /// свойством анализатора), первая оставалась поставочной, и корпусный
        /// A/B по полосе молча мерил ОДНО И ТО ЖЕ: плечо `--band=whole` дало
        /// состав и пределы побитово те же, что поставочный прогон, — 32 файла
        /// из 32. Теперь оба конца читают статику при обращении, присваивания
        /// нет ни у одного, и развести их нечем.
        /// Разбор веток и цена каждой — в шапке <see cref="FsaBand"/>.
        /// </summary>
        public FsaBandMode Band
        {
            get { return FsaBand.DefaultMode; }
        }

        /// <summary>
        /// Пол полосы библиотеки, кэВ, при <see cref="FsaBandMode.LibraryToFit"/>.
        /// Ноль или отрицательное — пола нет, режет <see cref="MinEnergyKev"/>.
        /// ⛔ Как и <see cref="Band"/>, читается у <see cref="FsaBand.DefaultFloor"/>
        /// при обращении и своей копии не имеет (`S101`).
        /// </summary>
        public double LibraryFloorKev
        {
            get { return FsaBand.DefaultFloor; }
        }

        /// <summary>
        /// ⛔ КРИВАЯ ЭФФЕКТИВНОСТИ СПЕКТРА — нужна ТОЛЬКО чтобы назначить пол
        /// полосы при <see cref="FsaBandMode.LibraryToFitByCurve"/>. Ставится
        /// ОДНИМ присваиванием у каждого, кто строит спецификацию; сам расчёт
        /// живёт в <see cref="FsaEfficiency.FloorAtFraction"/> и больше нигде —
        /// иначе у решения «где пол» завелась бы третья копия, а две у полосы
        /// уже стоили дня разбора (`S101`).
        ///
        /// `null` — законное значение: у 38 спектров корпуса из 121 кривой нет,
        /// и пол по кривой им назначить нечем.
        /// </summary>
        public FsaEfficiency Efficiency;

        /// <summary>
        /// ⛔ ПОРОГ АЦП САМОГО СПЕКТРА, кэВ (`A73`, 04.09.2026) — величина,
        /// которая есть У КАЖДОГО спектра, в том числе у 39 корпусных без
        /// геометрии. Ставится ОДНИМ присваиванием у каждого, кто строит
        /// спецификацию, как и <see cref="Efficiency"/>; сам расчёт живёт в
        /// <see cref="FsaBand.AdcFloorOf"/> и больше нигде.
        ///
        /// 0 — не задан, и это законно: тогда запасная ветвь
        /// <see cref="FsaNoCurveFloor.Adc"/> назначить пол не может и молчит,
        /// как молчит кривая, которой нет.
        /// </summary>
        public double AdcFloorKev;

        // ⛔ СОБСТВЕННОЙ ДОЛИ У СПЕЦИФИКАЦИИ НЕТ (`S101`). Здесь стояло поле
        // `FloorFraction` с признаком «ноль или отрицательное — брать
        // умолчание», и не ставил его никто. Убрано не за неиспользуемость, а
        // за то, что это ТРЕТИЙ рычаг у одного решения: заверение анализатора
        // (`FsaAnalyzer.BandNote`) называет пол по `FsaBand.DefaultFloorFraction`,
        // и спецификация со своей долей заставила бы два конца печатать разные
        // числа об одном и том же поле. Долю двигает `FsaBand.DefaultFloorFraction`,
        // её видят оба; ключ пробы — `--floor-frac=`.

        /// <summary>
        /// ⛔ ГРАНИЦА, КОТОРАЯ РЕАЛЬНО РЕЖЕТ ЛИНИИ. Одна на все образы —
        /// распадные, рентген пробы и кристалла, пики вылета: разойдясь в ней,
        /// они разошлись бы в том, что вообще существует ниже `Min_Range`.
        ///
        /// При <see cref="FsaBandMode.LibraryToFit"/> — пол
        /// <see cref="LibraryFloorKev"/>, но НЕ выше `Min_Range` (поднимать
        /// границу этот режим не должен); иначе — `Min_Range`, как было.
        ///
        /// Измерено 25.08.2026 (понятная часть корпуса, 81 спектр): при поле
        /// 10 кэВ линии распада возвращаются у 15 спектров, а иодная Kα
        /// кристалла (28.32/28.61 кэВ, 81.3 % веса K-серии) — у ВСЕХ 81.
        /// </summary>
        public double LineFloorKev
        {
            get
            {
                // ⛔ Пол ПО КРИВОЙ (решение Amber 27.08.2026, `S98`): его знает
                // сама кривая спектра, а не число в коде. Кривой нет — падаем
                // на `Min_Range`, и это запасная ветвь, а не отказ.
                // ⛔ ОПОРА ПО СТОЛБЦУ (`S103`) на этом конце НИЧЕГО не режет
                // сверх пола по кривой, и это не упущение: доля континуума
                // существует только внутри фита (нужны активный набор колонок,
                // Gram на подобранном узле дрейфа и веса решателя), а здесь
                // библиотека собирается ДО всякого фита. Первый проход поэтому
                // впускает ровно то же, что поставка, а выброс делает
                // `FsaAnalyzer` вторым проходом.
                if (this.Band == FsaBandMode.LibraryToFitByCurve
                    || this.Band == FsaBandMode.LibraryToFitByShare)
                {
                    // ⛔ ПОРЯДОК ИСТОЧНИКОВ — СУЩЕСТВО ПРАВКИ `A73`, и он
                    // именно такой: КРИВАЯ ПЕРВОЙ. Там, где кривая есть, пол
                    // назначает она и только она, до последнего знака как
                    // прежде, — иначе правка сдвинула бы все существующие
                    // числа. Запасная ветвь работает РОВНО ТАМ, где кривой нет,
                    // и до 04.09.2026 ею был `Min_Range` — настройка ПОИСКА
                    // ПИКОВ, к полосе разбора отношения не имеющая.
                    double floor = this.CurveFloorKev;
                    if (!(floor > 0.0))
                    {
                        floor = this.NoCurveFloorKev;
                    }

                    return floor > 0.0 ? Math.Min(this.MinEnergyKev, floor) : this.MinEnergyKev;
                }

                if (this.Band != FsaBandMode.LibraryToFit || !(this.LibraryFloorKev > 0.0))
                {
                    return this.MinEnergyKev;
                }

                return Math.Min(this.MinEnergyKev, this.LibraryFloorKev);
            }
        }

        /// <summary>
        /// Пол, который назначает САМА кривая, кэВ; 0 — назначить нечем (кривой
        /// нет либо доля недостижима). Отдельным свойством, чтобы его можно было
        /// НАПЕЧАТАТЬ: заверение обязано называть то, что случилось, а не то,
        /// что заказывали.
        /// </summary>
        public double CurveFloorKev
        {
            get
            {
                if (this.Efficiency == null)
                {
                    return 0.0;
                }

                // Доля — ОДНА на разбор и берётся у статики при обращении
                // (`S101`): её же читает заверение анализатора, и второй копии
                // здесь быть не должно.
                return this.Efficiency.FloorAtFraction(FsaBand.DefaultFloorFraction);
            }
        }

        /// <summary>
        /// Пол, который назначает ЗАПАСНАЯ ВЕТВЬ, кэВ; 0 — назначить нечем
        /// (`A73`). Отдельным свойством по той же причине, что и
        /// <see cref="CurveFloorKev"/>: заверение обязано называть то, что
        /// случилось, а не то, что заказывали.
        ///
        /// ⛔ Своего правила здесь НЕТ — всё решение живёт в
        /// <see cref="FsaBand.NoCurveFloor"/>, и второй копии у него быть не
        /// должно (`S101`).
        /// </summary>
        public double NoCurveFloorKev
        {
            get { return FsaBand.NoCurveFloor(this.AdcFloorKev); }
        }

        // ⛔ ПОЛЕ `Room` СНЯТО 01.09.2026 (решение Amber по описи `S110`).
        // Оно дописывало в состав ЛЮБОГО спектра ряды тория и радия плюс
        // калий — «вездесущие», NORM по правилу 18.08.2026. Правило снято
        // дословно: «нельзя так делать, это нарушает физику и логику всего,
        // это неудачная подгонка. В режиме FSA фон вычитается — то есть его
        // быть не должно. Ничего автоматически докладывать не надо».
        //
        // ⚠ Цена известна и была измерена ДО снятия: без NORM Σχ² по корпусу
        // хуже на 8…9 %. Это и есть подгонка, о которой сказано: фит
        // становился лучше, а состав — неправдой. Спектр с большой невязкой
        // разбирается вторым заходом по остатку (`S111`), а не подкладкой.

        /// <summary>
        /// Добавлять атомный рентген — пробы, кристалла, защиты — и пики вылета
        /// кристалла (решение Amber 18.08.2026, `S56`). A/B-сторона замера.
        /// </summary>
        public bool AtomicXray = true;

        /// <summary>
        /// ЗАСЛОН СВЕДЕНИЯ РЕНТГЕНА КРИСТАЛЛА — прежнее поведение, снятое
        /// решением Amber 12.09.2026 (`A30`, дословно: «Снять заслон: сводить
        /// кристалл ВСЕГДА»).
        ///
        /// Выключен — вещество кристалла сводится в ОДИН образ (`Xray-CsI`,
        /// `A29`) всегда, и образ пробы или защиты на тот же элемент НЕ
        /// строится: иод пробы I-131 на NaI, цезий защиты на CsI уходят в образ
        /// кристалла, второй колонки на те же отсчёты нет. Пропущенный элемент
        /// называется в <see cref="FsaSampleLibrary.Report.Notes"/>.
        ///
        /// Включён — как до 12.09.2026: сперва проба и защита, и если элемент
        /// кристалла уже занят их образом, вещество не сводится, а строится
        /// поэлементно — та самая вырожденная пара, которую заслон и порождал.
        /// Цена измерена полосой П2 10.09.2026 (`FsaCrystalMixFallbackProbe`,
        /// журнал `handover-2026-09-10-p2-branches-without-corpus.md` §2): при
        /// рентгене кристалла в 0.2 % спектра сведённый образ доживает до
        /// разбора 12 раз из 12, пара — 0 из 12, то есть человек видит спектр
        /// БЕЗ рентгена кристалла; при живой матрице половина вещества
        /// (`Xray-Cs`, 51.5 % веса K-серии) остаётся свободной колонкой мимо
        /// гейта `AMBER4`, потому что флага <see cref="FsaComponent.FromCrystal"/>
        /// у колонки из пробы нет по построению.
        ///
        /// Ключ оставлен ради положительного контроля лестницы плеч
        /// (`CorpusFsaProbe --crystal-shield=1`) и той же пробы; в приложении
        /// не поднимается.
        /// </summary>
        public bool CrystalShield;

        /// <summary>
        /// Наименьшая накопленная доля ветвления, при которой член ряда идёт в
        /// состав отдельным образом.
        ///
        /// ⛔ Порог здесь ОБЯЗАТЕЛЕН, и вот почему. Члены ряда входят в разбор
        /// РАЗНЫМИ образами со свободными амплитудами (так принято: «разрез
        /// цепочки получается сам», <see cref="FsaLibrary"/>). Свободная
        /// амплитуда снимает множитель ветвления начисто: у Tl-210 в радиевом
        /// ряду доля 2·10⁻⁴, а линий двадцать четыре, и предъявленный фиту
        /// такой образ ведёт себя ровно как фантом Pu-238 из `N18` — двадцать
        /// четыре свободные линии там, где физически нет ничего. Порог 10⁻³
        /// оставляет ряд целым (у Th-232 и Ra-226 все настоящие члены стоят на
        /// 1.0000 либо 0.3594) и снимает хвосты редких ветвей.
        /// </summary>
        public double MinChainBranch = 1.0e-3;

        /// <summary>
        /// Доля ветвления, ниже которой ИЗОМЕР членом ряда не считается
        /// (решение Amber 01.09.2026 по описи `S110`: судит доля, а не имя
        /// ряда — прежде изомеры держались только в `238U`, названном прямо в
        /// коде).
        ///
        /// ⚠ ЧИСЛО НАЗНАЧЕНО, А НЕ ВЫВЕДЕНО. Смысл половины: изомер остаётся,
        /// когда ряд ИДЁТ ЧЕРЕЗ НЕГО, а не сворачивает в него боковой ветвью.
        ///
        /// До 14.10.2026 порог был неразличим: во всей `decay_chain` изомер-член
        /// был ровно ОДИН — `234PAm1`, доля 1.000. С записью рёбер «родитель →
        /// изомер дочки» (П294, `database/scheme.md` §2) изомеров-дочерей 51, и
        /// порог РАЗЛИЧАЕТ: ниже 0.5 стоят Xe-135m у I-135 (0.1656), Ge-81m
        /// (0.4649), Gd-141m (0.4457), Lu-166m2 (0.3751), Cd-119m, Te-125m,
        /// Zn-71m, Cd-117m, Te-127m, Sn-121m1, Cd-121m1, Ge-69m, Cd-115m1,
        /// Se-81m, Tc-95m, Xe-133m, Xe-131m1, Pu-237m — их линии в образ ряда не
        /// идут (526.6 кэВ у ряда I-135 нет; Xe-135m человек объявляет сам).
        /// Порог оставлен решением Amber 14.10.2026 вопросником, дословно:
        /// «Оставить 0.5».
        ///
        /// (П299, 14.10.2026) Записано ещё 18 рёбер — изомеров-дочерей 69. Выше
        /// порога из них один — Sm-139m у Eu-139 (0.5762, линии 155.3/190.1/267.3
        /// кэВ входят в образ Eu-139); прочие 17 ниже (Tb-151m 0.3832, Nb-99m
        /// 0.367, W-179m 0.291, Sn-130m 0.2526 … Hg-195m 0.0036).
        ///
        /// (П308, 14.10.2026) Второй проход — ещё 3 ребра, изомеров-дочерей 71: новые
        /// Nb-91m у Mo-91m (0.5 — порог проходит, сравнение строгое «&lt;») и Sb-129m1 у
        /// Sn-129m1 (0.05269); Sb-130m у Sn-130m (0.1335) дочерью был и прежде (у Sn-130).
        /// Все три изомера живут дольше своих родителей и отрезаются равновесием
        /// (`T259`) — библиотека разбора от них не меняется.
        /// </summary>
        public double MinIsomerBranch = 0.5;

        /// <summary>
        /// РАВНОВЕСИЕ: ряд идёт в разбор ОДНОЙ колонкой с одной свободной
        /// амплитудой, а относительные веса его членов закреплены накопленной
        /// долей ветвления (решение Amber 18.08.2026, `S70`; умолчание —
        /// ВКЛЮЧЕНО).
        ///
        /// ⛔ Выключено — прежнее поведение: у каждого члена ряда СВОЯ свободная
        /// амплитуда, «разрез цепочки получается сам», и именно так видно
        /// НЕРАВНОВЕСИЕ — оборванный ряд уранового стекла (`S65`), ушедшая
        /// эманация радона. Ради этого случая свободные амплитуды и оставлены,
        /// и убирать их насовсем нельзя.
        ///
        /// Цена свободных амплитуд измерена и она не мала. На
        /// `Th232_29.07.2022.xml` — чистый ториевый источник, ряд заведомо
        /// равновесный — Ra-224 получил 8.22 % против положенных ему по
        /// равновесию ≈0.9 %: у него единственная гамма 240.986 кэВ с выходом
        /// 4.1 %, в 2.4 кэВ от 238.632 кэВ Pb-212 с выходом 43.6 %, и при ПШПВ
        /// прибора в 52 канала обе линии — один бугор. Свободная амплитуда
        /// раздаёт этот бугор как угодно, связка одной амплитудой снимает
        /// вопрос по построению.
        ///
        /// ⚠ Отбором списка это НЕ является: у Th-232 равновесны ВСЕ члены, и
        /// никакой отсев на том спектре не изменил бы ничего.
        /// </summary>
        public bool Equilibrium = true;

        /// <summary>
        /// Верхняя энергия родительской линии, которой ещё строится пик вылета,
        /// кэВ. Выше неё фотоэффект в кристалле пренебрежимо мал против
        /// комптона, и вылет тонет; счёт от этого не портится (вес выйдет почти
        /// нулевым), но образ разбухает линиями ни о чём.
        /// </summary>
        public double EscapeParentMaxKev = 600.0;

        /// <summary>
        /// Наименьший вес линии вылета в долях сильнейшей линии ТОГО ЖЕ образа.
        ///
        /// ⛔ Порог здесь не украшение, и цена его отсутствия измерена
        /// 18.08.2026 на `ASN16_Lu176`: без порога образ вылета иода вышел
        /// гребёнкой в 66 линий по всей шкале — по линии на каждую линию
        /// состава, включая тысячные доли процента вездесущих рядов. Гребёнка
        /// делает сразу две скверные вещи: в NNLS она свободный образ, готовый
        /// забрать любую необъяснённую структуру (механизм фантома `N18`), а в
        /// поиске пиков она забирает ПОДПИСИ — на том прогоне «Esc-I» и «Esc-Cs»
        /// подписали четыре пика из девяти, включая 304.32, который есть линия
        /// 306.78 самого лютеция.
        /// </summary>
        public double EscapeMinRelativeWeight = 0.02;

        // ------------------------------------------------------------------
        // ОБЩИЙ ВХОД сборки спецификации (`T257`, хвост (2), 12.09.2026)
        // ------------------------------------------------------------------

        /// <summary>
        /// ОБСТАНОВКА СПЕКТРА — всё, что спецификация берёт из самого спектра,
        /// без единого нуклида: кривая (ради пола полосы, `S98`), порог АЦП
        /// (второй источник пола, `A73`), окно — рабочий диапазон ПОИСКА ПИКОВ
        /// прибора, вещество кристалла, названное у прибора (`A276`), и — при
        /// геометрии — кристалл с долями и именем (`S84`) и тяжёлые элементы
        /// пробы.
        ///
        /// ⛔ ЭТО ЕДИНСТВЕННАЯ КОПИЯ ЭТОЙ СБОРКИ. До 12.09.2026 её держали пять
        /// мест — `CorpusFsaProbe.SpecOf`, <see cref="FsaCompositionInference.Infer"/>,
        /// `FsaStackShot.DeclaredSpec`, `FsaChannelSplitProbe.SpecOf`,
        /// `FsaDoubleCountProbe.SpecOf` — и уже разошлись: две последние не
        /// добирали элементы пробы из геометрии, первая не ставила вещество
        /// кристалла. Второй источник этих порогов двигал бы энергию пика
        /// вылета (она есть разность с Kα кристалла) — ровно то, от чего
        /// предостерегал сам `Infer`.
        ///
        /// ⚠ У КРИСТАЛЛА окно по Kα не ставится, и это не оплошность. Элемент
        /// кристалла делает ДВЕ разные вещи: светит сам (тогда его Kα обязана
        /// попасть в окно — это проверяется построчно при сборке образа) и
        /// уносит энергию ВЫЛЕТОМ, а пик вылета стоит на E − Kα, то есть
        /// глубоко внутри окна даже когда сама Kα ниже его низа. Поймано
        /// измерением 18.08.2026: у ASN16 нижняя граница выше 28.6 кэВ, и иод
        /// CsI отсеивался целиком — вместе со своими пиками вылета. У ПРОБЫ окно
        /// ставится: она вне кристалла, вылета не даёт, и элемент, чья K-серия
        /// ниже рабочего низа, не даёт ничего. Порог по массовой доле 1 %: ниже
        /// него элемент — примесь, а образ примеси со свободной амплитудой ведёт
        /// себя как фантом.
        ///
        /// Флаги <see cref="AtomicXray"/> и <see cref="Equilibrium"/> здесь не
        /// трогаются (умолчания класса); кто знает настройки — ставит их сам
        /// (<see cref="FsaCalculationOptions.ApplyTo(FsaSampleSpec)"/> или
        /// ключи пробы). <c>null</c> вместо спектра — пустая спецификация.
        /// </summary>
        public static FsaSampleSpec OfSpectrum(ResultData rd)
        {
            var spec = new FsaSampleSpec();
            if (rd == null)
            {
                return spec;
            }

            // ⛔ Кривая — только ради пола полосы по ней самой (`S98`, решение
            // Amber 27.08.2026). Расчёт живёт в `FsaEfficiency.FloorAtFraction`,
            // здесь одно присваивание.
            spec.Efficiency = FsaEfficiency.FromConfig(rd.Efficiency);

            // ⛔ `A73`: порог АЦП спектра — второй источник пола полосы, тот
            // самый, что работает у корпусных спектров без геометрии. Расчёт —
            // `FsaBand.AdcFloorOf`, здесь одно присваивание.
            spec.AdcFloorKev = FsaBand.AdcFloorOf(rd.EnergySpectrum);

            // Окно — рабочий диапазон САМОГО поиска пиков: у ASN16 низ стоит на
            // 28.6 кэВ, и весь L-рентген ниже него в «ожидаемое» попадать не
            // вправе.
            var peakConfig = rd.PeakDetectionMethodConfig as FWHMPeakDetectionMethodConfig;
            if (peakConfig != null && peakConfig.Max_Range > peakConfig.Min_Range)
            {
                spec.MinEnergyKev = peakConfig.Min_Range;
                spec.MaxEnergyKev = peakConfig.Max_Range;
            }

            // ⛔ `A276`: вещество кристалла, названное человеком у ПРИБОРА, —
            // запасной источник массовых долей там, где геометрии нет. Здесь
            // ТОЛЬКО присваивание ссылки: старшинство источников держит
            // `FsaSampleLibrary.CrystalFractionsOf` и больше никто, поэтому
            // условия «а есть ли геометрия» тут нет и быть не должно.
            if (rd.DeviceConfig != null)
            {
                spec.CrystalMaterialName = rd.DeviceConfig.CrystalMaterialName;
            }

            GeometryModel geometry = rd.Efficiency != null && rd.Efficiency.HasGeometry
                ? rd.Efficiency.Geometry : null;
            if (geometry != null)
            {
                FsaSampleLibrary.DescribeCrystal(spec, geometry.Crystal, 0.01,
                    EfficiencySimulator.ScintillatorNameOf(geometry));
                spec.SampleElements.AddRange(FsaSampleLibrary.HeavyElementsOf(
                    geometry.Source, 0.01, spec.MinEnergyKev, spec.MaxEnergyKev));
            }

            return spec;
        }

        /// <summary>
        /// ОБЪЯВЛЕННЫЙ СОСТАВ поверх обстановки спектра: ряды (уже разобранные
        /// в <see cref="FsaSampleChain"/>) и одиночные нуклиды `nucid`, флаги
        /// равновесия и атомного рентгена. Вход проб, которые получают состав
        /// ключами (`--sample=`, `--chain=`), и снимка `FsaStackShot --sample=`.
        /// <c>null</c> в любом списке — «нет».
        /// </summary>
        public static FsaSampleSpec Declared(ResultData rd,
                                             IEnumerable<FsaSampleChain> chains,
                                             IEnumerable<string> nuclides,
                                             bool equilibrium, bool atomic)
        {
            FsaSampleSpec spec = OfSpectrum(rd);
            spec.AtomicXray = atomic;
            spec.Equilibrium = equilibrium;
            if (chains != null)
            {
                foreach (FsaSampleChain chain in chains)
                {
                    if (chain != null)
                    {
                        spec.Chains.Add(chain);
                    }
                }
            }

            if (nuclides != null)
            {
                foreach (string nucid in nuclides)
                {
                    if (!string.IsNullOrEmpty(nucid))
                    {
                        spec.Nuclides.Add(nucid);
                    }
                }
            }

            return spec;
        }

        /// <summary>
        /// То же — СЛОВАМИ МАНИФЕСТА: метки рядов как в колонке `chains`
        /// корпусного `manifest.csv` («Th-232», «U-238u»), нуклиды как в
        /// колонке `nuclides` (`nucid`). Метка, которой
        /// <see cref="FsaSampleChain.FromLabel"/> не знает, — ОТКАЗ
        /// (<see cref="ArgumentException"/> с именем метки), а не пропуск:
        /// пропущенный ряд выглядел бы как результат «ряда в спектре нет».
        /// Читатель манифеста в `CorpusFsaProbe` проверяет метки ДО прогона тем
        /// же <c>FromLabel</c>, так что там сюда доходят только известные.
        ///
        /// Что сверх этого знает про спектр корпус (`materials.csv`: кристалл,
        /// проба и защита у спектров без геометрии) — добирает сам вызывающий
        /// в <see cref="CrystalElements"/>/<see cref="SampleElements"/>/
        /// <see cref="ShieldElements"/>: это данные корпуса, а не приложения.
        /// </summary>
        public static FsaSampleSpec FromManifest(ResultData rd,
                                                 IEnumerable<string> chainLabels,
                                                 IEnumerable<string> nuclides,
                                                 bool equilibrium, bool atomic)
        {
            var chains = new List<FsaSampleChain>();
            if (chainLabels != null)
            {
                foreach (string label in chainLabels)
                {
                    FsaSampleChain chain = FsaSampleChain.FromLabel(label);
                    if (chain == null)
                    {
                        throw new ArgumentException(
                            "неизвестный ряд '" + label + "'; известные: "
                            + string.Join(", ", FsaSampleChain.KnownLabels), "chainLabels");
                    }

                    chains.Add(chain);
                }
            }

            return Declared(rd, chains, nuclides, equilibrium, atomic);
        }
    }

    /// <summary>
    /// Сборка библиотеки образов ПО ОБЪЯВЛЕННОМУ СОСТАВУ ПРОБЫ — исполнение
    /// первого постулата (`S56`, формулировка Amber 17.08.2026): «у каждого
    /// спектра — СВОЯ база пиков, привязанная к снятому нуклиду».
    ///
    /// ЧЕМ ЭТО ОТЛИЧАЕТСЯ ОТ ПОДБОРА ПО МЕТКАМ. У поиска пиков состав задают подписи
    /// из ОБЩЕГО списка, предъявленного прибору. Здесь наоборот: состав известен
    /// заранее (корпус знает, что снято), и общая библиотека приложения перестаёт
    /// быть тем, что предъявляется спектру. Цена прежнего порядка измерена в тот же
    /// день (`N18`): на `ASN16_Lu176` завёлся Pu-238 долей 1.7 % при z = 31.77 —
    /// единственной линией 152 кэВ в интенсивности 0.0009 %, попавшей в полосу
    /// обратного рассеяния линии 306.78 самого лютеция. Своим списком такой кандидат
    /// не появился бы вовсе. ⛔ (`AMBER306`) Образы по меткам собирает этот же метод
    /// (<see cref="FsaLibrary.BuildFromLabels"/>): метка выбирает нуклид, не линии.
    ///
    /// ⛔ ИСТОЧНИК — БАЗЫ, А НЕ КОНФИГ (указание Amber 18.08.2026). Ни
    /// `NuclideDefinition.xml`, ни `NuclideSet` здесь не читаются и читаться не
    /// должны: линии берутся из `nucdb.decay_radiations`, ряды — из
    /// `nucdb.decay_chain`, атомный рентген — из `matdb.xray_fluorescence`.
    /// Конфиг — дело человека и графика; состав образа — дело базы.
    ///
    /// ЛИНИИ БЕРУТСЯ ИЗ ВСЕХ ИЗЛУЧЕНИЙ РАСПАДА, А НЕ ИЗ ГАММ. Измерено
    /// 17.08.2026: у Lu-176 единственная гамма ниже 200 кэВ — 88.34, а реальный
    /// спектр внизу держится на K-рентгене гафния 54…65 кэВ (тип `X`); база из
    /// одних гамм дала невязку 405σ на 60.8 кэВ, с рентгеном — 251σ,
    /// χ²/ndf 5.342 → 4.696. Поэтому сюда идут типы `G` и `X`, K- и L-серия.
    ///
    /// ЧТО ЗДЕСЬ ЕСТЬ СВЕРХ РАСПАДА — и почему это не противоречит правилу
    /// «перенос живёт в матрице». Правило остаётся верным для СЧЁТА: матрица
    /// считает флуоресценцию пробы и вылет рентгена кристалла честно, из
    /// геометрии (`F27`, физика 12). Но матрицы нет у сорока спектров корпуса
    /// вовсе, а там, где она есть, её никто не проверяет — `E31` и `B14`
    /// прожили именно на этом. Решение Amber 18.08.2026: атомные образы
    /// кладутся ВСЕМ спектрам, свободной амплитудой, как опора будущей
    /// кросс-проверки (`S60`). ⚠ Отсюда следствие, которое надо помнить при
    /// чтении чисел: на понятной части эти образы конкурируют с матрицей за
    /// одни и те же отсчёты, и разница прогонов «было/стало» принадлежит не
    /// только сужению библиотеки. Разводится ключом `AtomicXray`.
    /// </summary>
    public static class FsaSampleLibrary
    {
        /// <summary>
        /// Что собралось и что не собралось — для проб и журнала. Пусто, если
        /// сказать нечего. Заводится на КАЖДЫЙ вызов <see cref="Build"/>:
        /// «нуклида нет в базе» и «нуклид есть, но линий в окне нет» с виду
        /// одно и то же, а чинятся по-разному.
        /// </summary>
        public sealed class Report
        {
            public readonly List<string> Notes = new List<string>();

            /// <summary>Членов рядов, отброшенных порогом ветвления.</summary>
            public int ChainMembersDropped;

            /// <summary>Образов распада (ряды и одиночные нуклиды).</summary>
            public int DecayComponents;

            /// <summary>Образов атомного рентгена и вылета.</summary>
            public int AtomicComponents;

            /// <summary>Линий во всех образах вместе.</summary>
            public int Lines;

            /// <summary>
            /// Полоса, в которой собиралась библиотека, готовой строкой
            /// (`S98`). Печатается всегда: умолчание, которого не видно в
            /// выводе прогона, ничем не отличается от случайного, а это
            /// умолчание меняет базу корпуса.
            /// </summary>
            public string Band = "";

            /// <summary>
            /// Сколько линий легло в образы НИЖЕ `Min_Range` — то есть ровно
            /// то, что добавил пол полосы (`S98`). Ноль при
            /// <see cref="FsaBandMode.Whole"/> и <see cref="FsaBandMode.FitToLibrary"/>
            /// по построению: там пол и есть `Min_Range`.
            /// </summary>
            public int LinesBelowMinRange;

            public override string ToString()
            {
                var text = new StringBuilder();
                text.AppendFormat(CultureInfo.InvariantCulture,
                                  "распад {0}, атомных {1}, линий {2}",
                                  this.DecayComponents, this.AtomicComponents, this.Lines);
                if (!string.IsNullOrEmpty(this.Band))
                {
                    text.Append("; ").Append(this.Band);
                }

                if (this.LinesBelowMinRange > 0)
                {
                    text.AppendFormat(CultureInfo.InvariantCulture,
                                      ", из них ниже Min_Range {0}", this.LinesBelowMinRange);
                }
                if (this.ChainMembersDropped > 0)
                {
                    text.AppendFormat(CultureInfo.InvariantCulture,
                                      "; членов ряда ниже порога ветвления {0}",
                                      this.ChainMembersDropped);
                }

                foreach (string note in this.Notes)
                {
                    text.Append("; ").Append(note);
                }

                return text.ToString();
            }
        }

        static readonly object Gate = new object();

        /// <summary>Кэш линий распада по `nucid`: база одна, спектров сто.</summary>
        static readonly Dictionary<string, List<double[]>> LineCache =
            new Dictionary<string, List<double[]>>(StringComparer.OrdinalIgnoreCase);

        /// <summary>Кэш обходов ряда по корню.</summary>
        static readonly Dictionary<string, Dictionary<string, double>> ChainCache =
            new Dictionary<string, Dictionary<string, double>>(StringComparer.OrdinalIgnoreCase);

        /// <summary>Кэш глубин членов ряда по корню (`S65`).</summary>
        static readonly Dictionary<string, Dictionary<string, int>> DepthCache =
            new Dictionary<string, Dictionary<string, int>>(StringComparer.OrdinalIgnoreCase);

        /// <summary>Кэш подрядов равновесия по корню (`T259`).</summary>
        static readonly Dictionary<string, HashSet<string>> EquilibriumCache =
            new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);

        /// <summary>(`AMBER236`) Кэш разбиений ряда на отрезки по корню.</summary>
        static readonly Dictionary<string, ChainSegmentation> SegmentCache =
            new Dictionary<string, ChainSegmentation>(StringComparer.OrdinalIgnoreCase);

        /// <summary>(`AMBER55`) {корень → {член → множитель переходного равновесия}}.</summary>
        static readonly Dictionary<string, Dictionary<string, double>> FactorCache =
            new Dictionary<string, Dictionary<string, double>>(StringComparer.OrdinalIgnoreCase);

        /// <summary>
        /// Библиотека образов по объявленному составу. Никогда не null; пустой
        /// список означает «состав не дал ни одной линии в рабочем диапазоне» —
        /// это результат, а не отказ.
        /// </summary>
        public static List<FsaComponent> Build(FsaSampleSpec spec)
        {
            Report report;
            return Build(spec, out report);
        }

        /// <summary>То же, с отчётом о сборке.</summary>
        public static List<FsaComponent> Build(FsaSampleSpec spec, out Report report)
        {
            report = new Report();
            var result = new List<FsaComponent>();
            if (spec == null)
            {
                return result;
            }

            // Порядок сохраняется по первому появлению: сначала объявленный
            // состав, потом вездесущие, потом атомные образы. Так состав
            // читается в том же порядке, в каком о нём думают.
            var byName = new Dictionary<string, FsaComponent>(StringComparer.OrdinalIgnoreCase);
            var order = new List<string>();

            // Накопленная доля ветвления на нуклид. Один и тот же нуклид может
            // прийти из двух рядов сразу (Ra-226 объявлен сам по себе и лежит
            // внутри U-238; Th-228 — сам по себе и внутри Th-232), и доли у него
            // тогда разные. Берём БОЛЬШУЮ: она отвечает тому ряду, в котором
            // нуклида больше, а свободная амплитуда всё равно перекроет разницу.
            var branch = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);

            // Хозяин члена — корень ряда, от которого посчитана его доля. При
            // равновесии (`S70`) по нему члены и связываются в одну колонку;
            // без равновесия он не используется вовсе.
            var owner = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

            foreach (FsaSampleChain chain in spec.Chains)
            {
                if (chain == null || string.IsNullOrEmpty(chain.Root))
                {
                    continue;
                }

                CollectChain(chain, spec.MinChainBranch, spec.MinIsomerBranch,
                             branch, owner, report);
            }

            foreach (string nucid in spec.Nuclides)
            {
                if (string.IsNullOrEmpty(nucid))
                {
                    continue;
                }

                if (IsIsomer(nucid))
                {
                    // Объявить изомер напрямую можно — это осознанный выбор
                    // того, кто заполняет состав, — но сказать об этом надо:
                    // общее правило (Amber 18.08.2026) изомеров не берёт.
                    report.Notes.Add("объявлен изомер " + nucid + " — взят по объявлению");
                }

                // Одиночный нуклид объявлен САМ, значит его выход дан на его
                // собственный распад — доля ветвления единица, и хозяин он сам.
                Remember(branch, owner, nucid, 1.0, nucid);
            }

            // Кто пришёл из ОБЪЯВЛЕННОГО состава, а кто добавлен комнатой.
            // Разница нужна пикам вылета: их образ строится по линиям пробы, и
            // подмешивать туда вездесущие ряды нельзя — в спектре лютеция
            // комната стоит на три порядка ниже, а в образе её линии оказались
            // бы вровень с лютециевыми. Измерено 18.08.2026: без этого деления
            // гребёнка вылета иода выходила в 66 линий на весь спектр.
            var declared = new HashSet<string>(branch.Keys, StringComparer.OrdinalIgnoreCase);

            // Сколько членов у каждого хозяина: колонкой ряда компонент
            // становится, только если членов больше одного. Одинокий корень
            // остаётся обычным одиночным нуклидом, и звать его «рядом» было бы
            // неправдой.
            var groupSize = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

            // ⛔ ЗДЕСЬ СТОЯЛА «КОМНАТА» — ряды тория и радия плюс калий,
            // дописываемые ЛЮБОМУ спектру. СНЯТА 01.09.2026 решением Amber по
            // описи `S110`, дословно: «нельзя так делать, это нарушает физику и
            // логику всего, это неудачная подгонка. В режиме FSA фон вычитается
            // — то есть его быть не должно. Ничего автоматически докладывать не
            // надо».
            //
            // Что это значит для состава: в библиотеку идёт РОВНО объявленное —
            // и ничего сверх. Спектр, у которого невязка велика, разбирается не
            // подкладкой вездесущих рядов, а вторым заходом по остатку (`S111`).

            // ⚠ Считаются ТОЛЬКО излучающие члены. Обход `decay_chain` доводит
            // ряд до стабильного конца, и у калия в «ряду» лежат ещё аргон с
            // кальцием — они не излучают, образа не дают и членами ряда для
            // связки не являются. Без этой оговорки K-40 становился колонкой
            // РЯДА из одного нуклида: имя то же, а вид `Chain`, и подпись пиков
            // уходила по ветке ряда. `DecayLines` кэширован, второй проход
            // ничего не стоит.
            //
            // (`A169`) Считается ПРИ ЛЮБОМ положении равновесия, а не только при
            // связке: тот же счёт говорит, кто из членов пришёл РЯДОМ, и это
            // происхождение (`DecayChainRoot`) нужно свободным членам не
            // меньше, чем связанным, — по нему строки собираются в родителя
            // без пересчёта. На связку (`grouped` ниже) счёт без равновесия не
            // влияет: она по-прежнему требует `spec.Equilibrium`.
            foreach (string nucid in branch.Keys)
            {
                if (DecayLines(nucid, report).Count == 0)
                {
                    continue;
                }

                string root = OwnerOf(owner, nucid);
                int have;
                groupSize[root] = groupSize.TryGetValue(root, out have) ? have + 1 : 1;
            }

            // Имя компонента, доставшееся нуклиду: по нему потом собираются
            // родительские линии пиков вылета. При равновесии член ряда лежит в
            // колонке корня, и искать его под собственным именем уже нельзя.
            var componentOf = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            var lineless = new List<KeyValuePair<string, double>>();

            foreach (KeyValuePair<string, double> member in branch)
            {
                List<double[]> lines = DecayLines(member.Key, report);
                if (lines.Count == 0)
                {
                    // (`AMBER274`, Э1; `Р3`) Член ряда без линий, но с бетой (Bi-210, Sr-90
                    // в ряду) — после обхода: колонка хозяина могла ещё не родиться, и
                    // порядок обхода решал бы, ляжет ли бета вовсе.
                    lineless.Add(member);
                    continue;
                }

                // ⛔ Суммарный выход считается по ВСЕМ линиям распада, до
                // отсева по рабочему окну прибора: это априорное свойство
                // нуклида (`S69`), а не образа. У Ra-228 обе линии — 13.52 и
                // 16.2 кэВ — ниже порога сцинтиллятора, и «выход мал» с «линии
                // вне шкалы» смешивать нельзя.
                double yield = 0.0;
                foreach (double[] line in lines)
                {
                    yield += line[1];
                }

                // Своя линия каждого члена подписана ЕГО именем и при
                // равновесии тоже: каскадное суммирование и совпадения работают
                // по нуклиду линии, а не по имени колонки.
                string self = PrettyName(member.Key);
                string root = spec.Equilibrium ? OwnerOf(owner, member.Key) : member.Key;
                bool grouped = spec.Equilibrium && GroupCount(groupSize, root) > 1;
                string name = grouped ? PrettyName(root) : self;
                componentOf[member.Key] = name;

                FsaComponent component = Take(byName, order, name,
                                              grouped ? FsaComponentKind.Chain
                                                      : FsaComponentKind.Single);

                // (`A169`) Происхождение в ряду — у КАЖДОГО излучающего члена
                // ряда из двух и более таких членов, и при связке, и без неё.
                // Одинокий корень (K-40, объявленный сам по себе Cs-137) рядом
                // не является и происхождения не получает — ровно по тому же
                // счёту, по которому он не становится колонкой ряда.
                string decayRoot = OwnerOf(owner, member.Key);
                if (GroupCount(groupSize, decayRoot) > 1)
                {
                    component.DecayChainRoot = PrettyName(decayRoot);
                }

                // В колонку ряда попадают несколько нуклидов; априорным выходом
                // колонки берётся НАИБОЛЬШИЙ из них — вопрос, на который этот
                // выход отвечает, звучит «может ли эта строка вообще что-то
                // показать», и одного видимого члена для «да» довольно.
                if (double.IsNaN(component.TotalYieldPercent)
                    || yield > component.TotalYieldPercent)
                {
                    component.TotalYieldPercent = yield;
                }

                // S98: снизу режет ПОЛ БИБЛИОТЕКИ, а не диапазон поиска пиков.
                // У Cd-109 разница видна целиком: ниже `Min_Range` = 30 кэВ
                // лежит K-серия серебра 21.99/22.163/25.03/25.454 с суммарным
                // выходом 102.3 % на распад, а в полосе остаётся одна гамма
                // 88.03 с выходом 3.64 % — то есть 97 % излучения нуклида
                // отбрасывалось до того, как фит его увидит.
                double floor = spec.LineFloorKev;
                foreach (double[] line in lines)
                {
                    if (line[0] < floor || line[0] > spec.MaxEnergyKev)
                    {
                        continue;
                    }

                    // `member.Value` — равновесное отношение активностей члена и
                    // корня: ветвление × множитель переходного равновесия
                    // (`AMBER55`, <see cref="CollectChain"/>); у одиночного
                    // нуклида — единица.
                    // (`AMBER54`, П127) Третье число строки — аннигиляционная
                    // часть выхода — едет в линию тем же весом.
                    AddLine(component, self, line[0], line[1] * member.Value,
                            line.Length > 2 ? line[2] * member.Value : 0.0);
                }

                // (`AMBER274`, Э1) Бета-ветви члена — тем же весом (равновесное
                // отношение к корню), что его линии, и под его именем.
                AddBetas(component, self, member.Key, member.Value);
            }

            // (`AMBER274`, `Р3`) Бета члена без линий — в колонку его ряда при связке
            // равновесием: колонка корня (ряд из двух и более излучающих членов) или
            // единственного излучающего члена. Ряд без излучающих членов (чистые
            // бета-излучатели: Sr-90 сам по себе, Bi-210 без Pb-210) хозяина не находит —
            // такой член уходит в строку по сплошному спектру ниже (`Ф14`).
            var hostOf = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            var orphans = new List<KeyValuePair<string, double>>();
            foreach (KeyValuePair<string, double> member in lineless)
            {
                if (FsaBetaLibrary.Branches(member.Key).Count == 0)
                {
                    continue;
                }

                FsaComponent host = null;
                if (spec.Equilibrium)
                {
                    string betaRoot = OwnerOf(owner, member.Key);
                    if (GroupCount(groupSize, betaRoot) > 1)
                    {
                        byName.TryGetValue(PrettyName(betaRoot), out host);
                    }
                    else
                    {
                        foreach (KeyValuePair<string, string> placed in componentOf)
                        {
                            if (string.Equals(OwnerOf(owner, placed.Key), betaRoot, StringComparison.OrdinalIgnoreCase)
                                && byName.TryGetValue(placed.Value, out host))
                            {
                                break;
                            }
                        }
                    }
                }

                if (host != null)
                {
                    AddBetas(host, PrettyName(member.Key), member.Key, member.Value);
                    hostOf[member.Key] = host.Name;
                }
                else
                {
                    orphans.Add(member);
                }
            }

            // (`AMBER274`, Ф14) СТРОКИ ПО СПЛОШНОМУ СПЕКТРУ — колонки чистых бета-излучателей.
            BetaOnlyColumns(spec, branch, owner, componentOf, hostOf, orphans, byName, order, report);

            // Образы без единой линии в окне выбрасываются здесь, а не при
            // сборке: у члена ряда линии могут быть все выше потолка прибора, и
            // пустой образ в NNLS — вырожденный столбец. (`AMBER274`, Ф14) Строка по
            // сплошному спектру линий не имеет нарочно: её образ — бета.
            foreach (string name in order)
            {
                FsaComponent component = byName[name];
                if (component.Lines.Count > 0 || component.BetaOnly)
                {
                    result.Add(component);
                    report.DecayComponents++;
                    report.Lines += component.Lines.Count;
                }
            }

            // (`AMBER306`) Подписи, которых в базах нет: их образ вбит руками, база о нём молчит.
            var typedNames = new List<string>();
            foreach (FsaComponent typed in spec.TypedComponents)
            {
                result.Add(typed);
                report.Lines += typed.Lines.Count;
                if (typed.Kind != FsaComponentKind.Nuisance)
                {
                    report.DecayComponents++;
                    typedNames.Add(typed.Name);
                }
            }

            if (spec.AtomicXray)
            {
                int before = result.Count;

                // ⚠ Имя берётся то, под которым нуклид РЕАЛЬНО лёг в состав, а
                // не `PrettyName` его самого: при равновесии член ряда лежит в
                // колонке корня, и поиск по собственному имени не нашёл бы его
                // вовсе — гребёнка вылета осталась бы без родительских линий.
                var declaredNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (string nucid in declared)
                {
                    string name;
                    declaredNames.Add(componentOf.TryGetValue(nucid, out name)
                                      ? name : PrettyName(nucid));
                }

                declaredNames.UnionWith(typedNames);
                AddAtomic(spec, result, declaredNames, report);
                report.AtomicComponents = result.Count - before;
            }

            AddEscapeImages(spec, result, report);
            AddAnnihilation(result, report);

            // S98: полоса библиотеки — в отчёт, и он её печатает. Считается
            // ЗДЕСЬ, по готовым образам, а не по трём местам отсева: так число
            // «линий ниже Min_Range» не зависит от того, сколько мест эту
            // границу читают, и не разъедется, если появится четвёртое.
            // ⛔ Печатается ФАКТИЧЕСКИЙ пол, а не заказанный: при поле по кривой
            // у спектра без кривой его назначить нечем, и молчать об этом нельзя.
            report.Band = FsaBand.Describe(spec.Band,
                                           spec.Band == FsaBandMode.LibraryToFitByCurve
                                           || spec.Band == FsaBandMode.LibraryToFitByShare
                                               ? spec.CurveFloorKev
                                               : spec.LibraryFloorKev,
                                           spec.MinEnergyKev, spec.MaxEnergyKev,
                                           spec.NoCurveFloorKev);
            foreach (FsaComponent component in result)
            {
                foreach (FsaLine line in component.Lines)
                {
                    if (line.Energy < spec.MinEnergyKev)
                    {
                        report.LinesBelowMinRange++;
                    }
                }
            }

            return result;
        }

        // ------------------------------------------------------------------
        // Распад
        // ------------------------------------------------------------------

        // ⛔ Список `RoomChains` (`232TH`, `226RA`) снят 01.09.2026 вместе с
        // полем `Room`: см. надгробие выше и строку `S110`.

        /// <summary>
        /// Члены ряда, прошедшие оба правила отбора, — в накопитель долей.
        ///
        /// Вынесено отдельным методом, потому что читателей у правила стало
        /// ДВА: сборка библиотеки по объявленному составу
        /// (<see cref="Build"/>) и вывод состава из поиска пиков
        /// (<see cref="FsaCompositionInference"/>, `S57`). Второй обязан
        /// считать «ожидаемые линии родителя» ровно по тому составу, который
        /// потом и будет собран, — иначе критерий значимости мерит один список,
        /// а фиту предъявляется другой.
        ///
        /// ⛔ Изомеры в состав НЕ идут — кроме ряда урана-238 (указание
        /// Amber 18.08.2026). Исключение здесь не поблажка, а физика:
        /// Pa-234m1 несёт линию 1001.03 кэВ, классический «урановый монопик»,
        /// по которому уран и опознают; выбросив изомер, ряд U-238 остался бы
        /// вовсе без сильной линии. В остальных рядах изомер — отдельное
        /// состояние с собственным временем жизни, и отдельным свободным
        /// образом он делает то же, что делают хвосты редких ветвей: даёт фиту
        /// свободные линии там, где равновесия нет.
        ///
        /// Основание у правила не только формальное. Слова Amber в тот же день:
        /// на приборах AtomSpectra (ASN16, AS80x80 и прочие «на A») изомеры в
        /// спектрах встречаются ТОЛЬКО в урановом стекле; у америция там линии
        /// стабильные, при активности порядка 65 кБк и ниже (оценка для
        /// понимания порядка). То есть исключение ровно одно и оно названо, а
        /// не выведено.
        /// </summary>
        internal static void CollectChain(FsaSampleChain chain, double minBranch,
                                          double minIsomerBranch,
                                          Dictionary<string, double> branch, Report report)
        {
            CollectChain(chain, minBranch, minIsomerBranch, branch, null, report);
        }

        /// <summary>
        /// То же, с записью хозяина каждого члена (корня ряда) — нужна связке
        /// равновесия (`S70`). Читателю, которому хозяин не нужен, годится
        /// перегрузка выше.
        /// </summary>
        internal static void CollectChain(FsaSampleChain chain, double minBranch,
                                          double minIsomerBranch,
                                          Dictionary<string, double> branch,
                                          Dictionary<string, string> owner, Report report)
        {
            if (chain == null || string.IsNullOrEmpty(chain.Root))
            {
                return;
            }

            // ⛔ ИМЕНИ РЯДА ЗДЕСЬ БОЛЬШЕ НЕТ. Стояло `keepIsomers = (chain.Root
            // == "238U")` — изомеры держались в одном ряду, названном по имени.
            // Снято 01.09.2026 решением Amber по описи `S110`: судит ДОЛЯ
            // ВЕТВЛЕНИЯ, а не имя. Изомер остаётся, если ряд ИДЁТ ЧЕРЕЗ НЕГО
            // (доля не ниже `MinIsomerBranch`), и выбрасывается, если он боковая
            // ветвь.
            //
            // ⚠ Измерено перед правкой, чтобы знать цену: во ВСЕЙ `decay_chain`
            // (тогда 4101 строка, 2241 разная дочерняя) изомер был ровно ОДИН —
            // `234PAm1`, и через него идёт весь урановый ряд (`234TH → 234PAm1`
            // 100 %, дальше `→ 234U` 99.84 %). Ни у `232TH`, ни у `226RA`, ни у
            // `235U`, ни у `227AC`, ни у `237NP` изомеров нет вовсе. Значит
            // замена имени на порог дала ПОБИТОВО тот же состав — и это
            // проверено прогоном, а не обещано.
            //
            // (П294, 14.10.2026) Изомер-членов теперь 51: записаны рёбра
            // «родитель → изомер дочки» (4218 строк, 2287 дочерних; Mo-99 →
            // Tc-99m 0.8766, Sr-91 → Y-91m 0.5887, Sn-126 → Sb-126m1 1.0, I-135 →
            // Xe-135m 0.1656 …), и порог `MinIsomerBranch` впервые РАЗЛИЧАЕТ —
            // см. его описание. Ряды Th-232, Ra-226, U-238, U-235, Th-228, Rn-222
            // прежние: ни один новый изомер в них не входит.
            // (П299, 14.10.2026) Изомер-членов 69 (4414 строк, 2351 дочерняя):
            // +18 рёбер и 146 потерянных мод (`database/scheme.md` §2); ряды
            // тех же шести голов прежние, корпус побайтно rev46.
            // (П308, 14.10.2026) Изомер-членов 71 (4488 строк, 2361 дочерняя): +3
            // ребра второго прохода и снят двойной счёт задержанных частиц семьи β⁻
            // (`database/scheme.md` §2); ряды шести голов прежние, корпус побайтно rev47.
            Dictionary<string, double> members = ChainBranches(chain.Root, report);
            // (`T259`) Ряд — ОТ КОРНЯ ВНИЗ, ПОКА РАВНОВЕСИЕ ВОЗМОЖНО: член с
            // периодом длиннее корня (и всё под ним) в подряд не входит. У голов
            // рядов такого члена нет, и множество равно всему обходу; у «Rn-222»
            // оно обрывается на Pb-210. Что выброшено — в отчёт, не молча.
            HashSet<string> reachable = EquilibriumMembers(chain.Root, report);
            // (`AMBER55`) Доля члена в образе корня — РАВНОВЕСНОЕ отношение
            // активностей, а оно есть ветвление × множитель переходного
            // равновесия по Бейтману, а не одно ветвление; см.
            // <see cref="EquilibriumFactors"/>. Пороги ниже судят ВЕТВЛЕНИЕ,
            // как и прежде: множитель не меньше единицы и в состав никого не
            // добавляет и не выбрасывает.
            Dictionary<string, double> factors = EquilibriumFactors(chain.Root, report);
            // (`AMBER119`) У выведенного корня множителя нет — см.
            // <see cref="FsaSampleChain.Transient"/>; каким он был бы, говорится.
            var secular = new List<string>();
            var cut = new List<string>();
            var transient = new List<string>();
            foreach (KeyValuePair<string, double> member in members)
            {
                if (chain.Only.Count > 0 && !chain.Only.Contains(member.Key))
                {
                    continue;
                }

                if (!reachable.Contains(member.Key))
                {
                    cut.Add(member.Key);
                    continue;
                }

                if (IsIsomer(member.Key) && member.Value < minIsomerBranch)
                {
                    report.ChainMembersDropped++;
                    continue;
                }

                if (member.Value < minBranch)
                {
                    report.ChainMembersDropped++;
                    continue;
                }

                double factor;
                if (!factors.TryGetValue(member.Key, out factor) || !(factor > 0.0))
                {
                    factor = 1.0;
                }

                if (!chain.Transient)
                {
                    if (factor - 1.0 >= TransientNoteFloor)
                    {
                        secular.Add(member.Key + " ×" + factor.ToString("F4", CultureInfo.InvariantCulture));
                    }

                    factor = 1.0;
                }

                if (factor - 1.0 >= TransientNoteFloor)
                {
                    transient.Add(member.Key + " ×" + factor.ToString("F4", CultureInfo.InvariantCulture));
                }

                Remember(branch, owner, member.Key, member.Value * factor, chain.Root);
            }

            if (cut.Count > 0)
            {
                cut.Sort(StringComparer.OrdinalIgnoreCase);
                report.Notes.Add("ряд от " + chain.Root + ": вне равновесия с корнем (период длиннее его) — "
                                 + string.Join(", ", cut) + "; в подряд не взяты (T259)");
            }

            if (transient.Count > 0)
            {
                // Не молча: у природных рядов множитель виден только у Pb-210 и
                // Po-210 радия (1.4 %), у подряда с коротким корнем он в разы.
                transient.Sort(StringComparer.OrdinalIgnoreCase);
                report.Notes.Add("ряд от " + chain.Root + ": переходное равновесие λ_д/(λ_д − λ_к) — "
                                 + string.Join(", ", transient) + " (AMBER55)");
            }

            if (secular.Count > 0)
            {
                secular.Sort(StringComparer.OrdinalIgnoreCase);
                report.Notes.Add("ряд от " + chain.Root + ": корень выведен разбором, не объявлен — равновесие вековое,"
                                 + " асимптота незапитанного корня не применена (" + string.Join(", ", secular)
                                 + "; AMBER119)");
            }
        }

        /// <summary>
        /// Ниже этого множителя минус единица переходное равновесие в отчёт не
        /// пишется: у Th-232 оно 5·10⁻¹⁰, у U-238 7·10⁻⁵ — шум записи, а не
        /// сведение для человека. Порог сходимости долей ряда на три порядка
        /// ниже (<see cref="ChainConverged"/>), и на само число он не влияет.
        /// </summary>
        const double TransientNoteFloor = 1.0e-3;

        /// <summary>
        /// Множитель переходного равновесия каждого члена подряда от корня
        /// (`AMBER55`, П124 22.09.2026): в равновесии с корнем активность члена
        /// `k` относится к активности корня как `BR_k · Π λ_j/(λ_j − λ_к)` по
        /// пути от корня к члену (Бейтман при `t ≫ 1/λ_j`; Gilmore 2008 гл. 1,
        /// Knoll гл. 1), и множитель — это произведение без ветвления. При
        /// `λ_j ≫ λ_к` он единица («вековое» равновесие) — этим и жила
        /// связка до П124; у Ra-226 → Pb-210 (22.2 г против 1600 л) он 1.0141,
        /// у подряда от Pb-214 (`T259`) для Bi-214 — 3.68, у Th-228 для всех
        /// членов — 1.005…1.006.
        ///
        /// Считается тем же способом, что доли ветвления в
        /// <see cref="ChainBranches"/> (`S62`): релаксацией до неподвижной
        /// точки по тем же рёбрам `decay_chain` с тем же зажимом уровня, но
        /// только по членам, С КОТОРЫМИ РАВНОВЕСИЕ ВОЗМОЖНО
        /// (<see cref="EquilibriumMembers"/>): x_к = 1, x_k = f_k · Σ_p x_p ·
        /// BR(p→k), f_k = λ_k/(λ_k − λ_к); рядом та же сумма без f — и
        /// множитель есть их отношение (у ряда без ветвлений — просто
        /// произведение f по пути; у ветвящегося — взвешенное ветвлением
        /// среднее по путям). Член длиннее корня в равновесии не бывает и в
        /// словарь не входит — его уже отрезал <see cref="EquilibriumMembers"/>;
        /// стабильный конец не излучает и множителя не получает. Корень без
        /// периода, отказ базы — пустой словарь: связка идёт одним ветвлением,
        /// как до П124, и <see cref="EquilibriumMembers"/> об этом уже сказал.
        ///
        /// ⚠ Множитель — АСИМПТОТА: он верен для пробы, прожившей много
        /// периодов дочернего после разделения (природные ряды, старые
        /// источники). У свежего фильтра с ДПР радона отношения Pb-214/Bi-214
        /// меняются по часам, и никакая ОДНА связка их не опишет — там
        /// равновесие выключают (`AMBER29`, П64: без связки отношение
        /// Bi-214/Pb-214 радоновой части 0.997 ± 0.022 при f_Bi/f_Pb = 1.0036).
        /// </summary>
        internal static Dictionary<string, double> EquilibriumFactors(string root, Report report)
        {
            lock (Gate)
            {
                Dictionary<string, double> cached;
                if (FactorCache.TryGetValue(root, out cached))
                {
                    return cached;
                }
            }

            var factors = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
            int failuresBefore = FsaDatabaseFailures.ThreadCount;
            try
            {
                double rootSeconds;
                if (TryHalfLifeSeconds(root, out rootSeconds) && rootSeconds > 0.0)
                {
                    double lambdaRoot = Math.Log(2.0) / rootSeconds;
                    HashSet<string> reachable = EquilibriumMembers(root, report);

                    // Шаг 1: рёбра между членами равновесия и множитель каждого
                    // члена по его периоду. Тот же запрос и тот же зажим уровня,
                    // что у `ChainBranches` (`A218`).
                    var edges = new Dictionary<string, List<KeyValuePair<string, double>>>(
                        StringComparer.OrdinalIgnoreCase);
                    var factorOf = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                    var order = new List<string> { root };
                    var known = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { root };
                    using (SqliteConnection connection = OpenRead(NuclideDatabasePath()))
                    using (SqliteCommand command = connection.CreateCommand())
                    using (SqliteCommand life = connection.CreateCommand())
                    {
                        command.CommandText =
                            "select daughter_nucid," + DecayParentRule.ChainPercColumn + " from" + DecayParentRule.ChainTable + " d"
                            + " where nucid = $n and perc not null"
                            + DecayParentRule.ChainLevelClause;
                        command.Parameters.AddWithValue("$n", root);
                        life.CommandText =
                            "select half_life_sec from nuclides where nucid = $n"
                            + " and half_life_sec is not null order by l_seqno limit 1";
                        life.Parameters.AddWithValue("$n", root);
                        for (int i = 0; i < order.Count && order.Count <= MaxChainNodes; i++)
                        {
                            string current = order[i];
                            command.Parameters["$n"].Value = current;
                            var step = new List<KeyValuePair<string, double>>();
                            using (SqliteDataReader reader = command.ExecuteReader())
                            {
                                while (reader.Read())
                                {
                                    string daughter = reader.IsDBNull(0) ? null : reader.GetString(0);
                                    double percent;
                                    if (string.IsNullOrEmpty(daughter)
                                        || string.Equals(daughter, current, StringComparison.OrdinalIgnoreCase)
                                        || !reachable.Contains(daughter)
                                        || !TryNumber(reader, 1, out percent) || !(percent > 0.0))
                                    {
                                        continue;
                                    }

                                    step.Add(new KeyValuePair<string, double>(daughter, percent));
                                    if (known.Add(daughter))
                                    {
                                        order.Add(daughter);
                                    }
                                }
                            }

                            edges[current] = step;
                        }

                        foreach (string member in order)
                        {
                            if (string.Equals(member, root, StringComparison.OrdinalIgnoreCase))
                            {
                                factorOf[member] = 1.0;
                                continue;
                            }

                            life.Parameters["$n"].Value = member;
                            double seconds = 0.0;
                            bool decays;
                            using (SqliteDataReader reader = life.ExecuteReader())
                            {
                                decays = reader.Read() && TryNumber(reader, 0, out seconds);
                            }

                            // Стабильный конец — множителя нет (и линий нет): в
                            // `factorOf` не входит, в релаксации идёт с единицей и в
                            // ответ не попадает. Период не короче корня сюда не
                            // доходит (`reachable`).
                            if (decays && seconds > 0.0 && seconds < rootSeconds)
                            {
                                double lambda = Math.Log(2.0) / seconds;
                                factorOf[member] = lambda / (lambda - lambdaRoot);
                            }
                        }
                    }

                    // Шаг 2: релаксация, как у `ChainBranches` — с множителем и
                    // без; отношение и есть множитель члена.
                    var with = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                    var without = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                    for (int pass = 0; pass < MaxChainPasses; pass++)
                    {
                        var nextWith = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                        var nextWithout = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                        nextWith[root] = 1.0;
                        nextWithout[root] = 1.0;
                        foreach (string parent in order)
                        {
                            double haveWith, haveWithout;
                            List<KeyValuePair<string, double>> outgoing;
                            if (!with.TryGetValue(parent, out haveWith) || !(haveWith > 0.0)
                                || !without.TryGetValue(parent, out haveWithout)
                                || !edges.TryGetValue(parent, out outgoing))
                            {
                                continue;
                            }

                            foreach (KeyValuePair<string, double> edge in outgoing)
                            {
                                double f;
                                if (!factorOf.TryGetValue(edge.Key, out f))
                                {
                                    f = 1.0;
                                }

                                double already;
                                nextWith[edge.Key] = (nextWith.TryGetValue(edge.Key, out already) ? already : 0.0)
                                                     + haveWith * edge.Value / 100.0 * f;
                                nextWithout[edge.Key] = (nextWithout.TryGetValue(edge.Key, out already) ? already : 0.0)
                                                        + haveWithout * edge.Value / 100.0;
                            }
                        }

                        double drift = 0.0;
                        foreach (KeyValuePair<string, double> row in nextWith)
                        {
                            double was;
                            double gap = Math.Abs(row.Value - (with.TryGetValue(row.Key, out was) ? was : 0.0));
                            if (gap > drift)
                            {
                                drift = gap;
                            }
                        }

                        with = nextWith;
                        without = nextWithout;
                        if (drift <= ChainConverged)
                        {
                            break;
                        }
                    }

                    foreach (KeyValuePair<string, double> row in with)
                    {
                        double plain;
                        if (factorOf.ContainsKey(row.Key)
                            && without.TryGetValue(row.Key, out plain) && plain > 0.0)
                        {
                            factors[row.Key] = row.Value / plain;
                        }
                    }
                }
            }
            catch (Exception error)
            {
                report.Notes.Add("ряд от " + root + ": отказ базы при счёте переходного равновесия — "
                                 + error.Message + "; связка одним ветвлением");
                FsaDatabaseFailures.Note("nucdb.sqlite", root, error);
                factors.Clear();
            }

            // ⛔ (`AMBER199`) Отказ — свой или вложенного читателя — в кэш не
            // кладётся: следующий разбор спросит базу снова.
            if (FsaDatabaseFailures.ThreadCount == failuresBefore)
            {
                lock (Gate)
                {
                    FactorCache[root] = factors;
                }
            }

            return factors;
        }

        /// <summary>
        /// Распадается ли нуклид по базе: есть строка `nuclides` с числовым
        /// `half_life_sec`. Стабильный (`STABLE`, период пуст) и неизвестный базе
        /// — <c>false</c>. Нужен <see cref="FsaSampleChain.FromLabel"/>: корень
        /// подряда обязан распадаться, иначе «ряд» — пустое множество линий.
        /// </summary>
        public static bool IsDecaying(string nucid)
        {
            if (string.IsNullOrEmpty(nucid))
            {
                return false;
            }

            double seconds;
            return TryHalfLifeSeconds(nucid, out seconds) && seconds > 0.0;
        }

        // ------------------------------------------------------------------
        // (`AMBER118`, П168 28.09.2026) Природные спутники состава
        // ------------------------------------------------------------------

        /// <summary>
        /// Период, начиная с которого нуклид считается первичным (природным
        /// корнем ряда): 10⁸ лет. U-238, U-235, Th-232, K-40 — выше; U-234 и
        /// Th-230 (у них в `nuclides.abundance` тоже стоят числа) — ниже: они не
        /// корни, а члены ряда U-238, и отношения «природного состава» к ним нет.
        /// </summary>
        const double PrimordialSeconds = 1.0e8 * 365.25 * 86400.0;

        /// <summary>Во сколько раз строка должна быть завышена спутником, чтобы о ней сказать.</summary>
        public const double InterferenceWarnFactor = 1.05;

        /// <summary>Сколько шагов вверх по `decay_chain` ищется первичный предок.</summary>
        const int MaxAncestorDepth = 24;

        /// <summary>
        /// (`AMBER118`; решение Amber 28.09.2026, дословно: «Строка AMBER:
        /// предупреждение об интерференции 186 кэВ») ЛИНИИ СОСТАВА, КОТОРЫЕ ДЕЛИТ
        /// ПРИРОДНЫЙ СПУТНИК, ОТСУТСТВУЮЩИЙ В СОСТАВЕ.
        ///
        /// В природном уране U-235 (0.72 % атомов, активность 0.046 от U-238)
        /// даёт 185.7 кэВ с выходом 57 % — то есть 2.63 фотона на 100 распадов
        /// U-238, а Ra-226 на 186.2 кэВ — 3.64. Прибор их не разделяет, и строка
        /// Ra-226, держащаяся на 186 кэВ (связка ряда выключена, или путь по
        /// подписям), завышена ×1.72; при связке колонку держат Pb/Bi-214, и
        /// множитель мал. Решение ~~`S110`~~ «ничего автоматически не
        /// докладывать» в силе: спутник в состав НЕ добавляется — о нём говорится.
        ///
        /// ⛔ ИМЁН ЗДЕСЬ НЕТ. Пара находится по базе: у компонента ищется
        /// первичный предок того же ряда (период ≥ 10⁸ лет, есть природная
        /// распространённость, компонент — член его подряда, `T259`), у предка —
        /// другие первичные изотопы ТОГО ЖЕ элемента, не входящие в его ряд и
        /// отсутствующие в составе; отношение активностей — из распространённостей
        /// и периодов (`nuclides.abundance`, `half_life_sec`). Линии ряда спутника
        /// с этим отношением ложатся на линии компонента, если стоят не дальше
        /// ПШПВ; множитель = (своё + спутник) / своё по линиям компонента в
        /// полосе, взвешенным эффективностью. Сказать — если он не меньше
        /// <see cref="InterferenceWarnFactor"/>.
        /// </summary>
        /// <param name="library">Библиотека, ушедшая в фит.</param>
        /// <param name="detected">Имена компонентов, вошедших в состав (строки отчёта).</param>
        /// <param name="fwhmKev">ПШПВ на энергии, кэВ; null или не число — окно 0.</param>
        /// <param name="efficiency">Эффективность на энергии; null — единица.</param>
        public static List<FsaLineInterference> NaturalCompanionInterference(
            IList<FsaComponent> library, ICollection<string> detected,
            Func<double, double> fwhmKev, Func<double, double> efficiency,
            double loKev, double hiKev)
        {
            var found = new List<FsaLineInterference>();
            if (library == null || library.Count == 0)
            {
                return found;
            }

            try
            {
                var present = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (FsaComponent component in library)
                {
                    foreach (FsaLine line in component.Lines)
                    {
                        string nucid = NucidOf(line.Nuclide ?? string.Empty);
                        if (nucid.Length > 0)
                        {
                            present.Add(nucid);
                        }
                    }
                }

                var report = new Report();
                foreach (FsaComponent component in library)
                {
                    if ((component.Kind != FsaComponentKind.Single && component.Kind != FsaComponentKind.Chain)
                        || component.Lines.Count == 0
                        || (detected != null && !detected.Contains(component.Name)))
                    {
                        continue;
                    }

                    string unit = NucidOf(component.Name);
                    if (unit.Length == 0)
                    {
                        continue;
                    }

                    foreach (Companion companion in CompanionsOf(unit, present, report))
                    {
                        FsaLineInterference hit = Interfere(component, companion.Isotope, companion.PerUnit,
                                                            fwhmKev, efficiency, loKev, hiKev, report);
                        if (hit != null)
                        {
                            hit.Reference = companion.Reference;
                            hit.ActivityRatio = companion.ActivityRatio;
                            found.Add(hit);
                        }
                    }
                }
            }
            catch (Exception error)
            {
                // Отказ базы — предупреждений нет; разбор от них не зависит.
                // (`AMBER199`) Но молча — нельзя: строка окна отчёта.
                FsaDatabaseFailures.Note("nucdb.sqlite", "companions", error);
            }

            return found;
        }

        /// <summary>(`AMBER118`/`S199`) Природный спутник компонента и его отношение.</summary>
        sealed class Companion
        {
            /// <summary>Сам спутник — первичный изотоп того же элемента, что предок.</summary>
            public Primordial Isotope;

            /// <summary>Предок компонента, к которому взято природное отношение («U-238»).</summary>
            public string Reference;

            /// <summary>Отношение активностей спутника и предка при природном составе.</summary>
            public double ActivityRatio;

            /// <summary>Распадов спутника на один распад компонента (с долей ветвления предка к нему).</summary>
            public double PerUnit;
        }

        /// <summary>
        /// (`AMBER118`; вынесено `S199`, П174 28.09.2026) Природные спутники
        /// нуклида <paramref name="unit"/> — ОДНО правило на оба пути (строка FSA и
        /// зона ROI): первичный предок того же ряда (период ≥ 10⁸ лет, есть
        /// распространённость, <paramref name="unit"/> — член его подряда), у
        /// предка — первичные изотопы ТОГО ЖЕ элемента вне его ряда и вне
        /// <paramref name="present"/>; отношение активностей — из
        /// распространённостей и периодов. Имён в коде нет.
        /// </summary>
        static List<Companion> CompanionsOf(string unit, ICollection<string> present, Report report)
        {
            var list = new List<Companion>();
            foreach (Primordial ancestor in PrimordialAncestors(unit, report))
            {
                double toUnit = 1.0;
                if (!string.Equals(ancestor.Nucid, unit, StringComparison.OrdinalIgnoreCase))
                {
                    double branch;
                    if (!ChainBranches(ancestor.Nucid, report).TryGetValue(unit, out branch)
                        || !(branch > 0.0))
                    {
                        continue;
                    }

                    toUnit = branch;
                }

                HashSet<string> ancestorChain = EquilibriumMembers(ancestor.Nucid, report);
                foreach (Primordial companion in PrimordialIsotopes(ancestor.Z))
                {
                    if (string.Equals(companion.Nucid, ancestor.Nucid, StringComparison.OrdinalIgnoreCase)
                        || ancestorChain.Contains(companion.Nucid)
                        || (present != null && present.Contains(companion.Nucid)))
                    {
                        continue;
                    }

                    double ratio = (companion.Abundance / companion.Seconds)
                                   / (ancestor.Abundance / ancestor.Seconds);
                    list.Add(new Companion
                    {
                        Isotope = companion,
                        Reference = PrettyName(ancestor.Nucid),
                        ActivityRatio = ratio,
                        PerUnit = ratio / toUnit
                    });
                }
            }

            return list;
        }

        /// <summary>
        /// (`AMBER118`; вынесено `S199`) Линии ряда спутника в полосе: {энергия,
        /// фотонов на распад КОМПОНЕНТА, %} — выход × доля ветвления в подряде
        /// спутника × <paramref name="perUnit"/>; эффективности здесь нет.
        /// </summary>
        static List<double[]> CompanionLines(Primordial companion, double perUnit, double loKev, double hiKev,
                                             Report report)
        {
            var lines = new List<double[]>();

            // Ряд спутника — его подряд равновесия (`T259`) с долями ветвления.
            Dictionary<string, double> branches = ChainBranches(companion.Nucid, report);
            // ⚠ Копия: множество подряда кэшировано и общее для всех читателей.
            var members = new HashSet<string>(EquilibriumMembers(companion.Nucid, report),
                                              StringComparer.OrdinalIgnoreCase);
            members.Add(companion.Nucid);
            foreach (string member in members)
            {
                double branch;
                if (!branches.TryGetValue(member, out branch))
                {
                    branch = string.Equals(member, companion.Nucid, StringComparison.OrdinalIgnoreCase) ? 1.0 : 0.0;
                }

                if (!(branch > 0.0))
                {
                    continue;
                }

                foreach (double[] line in DecayLines(member, report))
                {
                    if (line[0] < loKev || line[0] > hiKev)
                    {
                        continue;
                    }

                    double yield = line[1] * branch * perUnit;
                    if (yield > 0.0)
                    {
                        lines.Add(new[] { line[0], yield });
                    }
                }
            }

            return lines;
        }

        /// <summary>
        /// ⛔ (`S199`, П174 28.09.2026; решение Amber 28.09.2026, дословно: «Строка
        /// AMBER: предупреждение об интерференции 186 кэВ» — на обоих путях)
        /// ПОМЕХА ПРИРОДНОГО СПУТНИКА У ЗОНЫ ROI. Правило то же, что у строки FSA
        /// (<see cref="NaturalCompanionInterference"/>: спутник по базе через
        /// <see cref="CompanionsOf"/>, линии его ряда — <see cref="CompanionLines"/>),
        /// отличие одно — ОКНО: у FSA окна нет, и строку держит главная группа
        /// линий ±ПШПВ; зона же собирает в своё окно ВСЁ, что туда легло. Поэтому
        /// и свои линии нуклида зоны, и линии ряда спутника взвешиваются долей
        /// пика в окне (<paramref name="windowShare"/>) и эффективностью;
        /// множитель = (своё + спутник) / своё. Сказать — от
        /// <see cref="InterferenceWarnFactor"/>.
        ///
        /// ⚠ «Спутник объявлен» здесь зону НЕ освобождает, в отличие от FSA: там
        /// фит делит пик между колонками, а зона U-235 рядом из зоны Ra-226
        /// ничего не вычитает. Спутник по-прежнему в состав не добавляется
        /// (~~`S110`~~): о нём говорится.
        /// </summary>
        /// <param name="nucid">Нуклид зоны (`nucid` базы).</param>
        /// <param name="windowShare">Доля пика линии энергии E в окне зоны (0…1).</param>
        /// <param name="efficiency">Эффективность на энергии; null — единица.</param>
        /// <returns>Помеха с наибольшим множителем; null — помехи нет или база не читается.</returns>
        public static FsaLineInterference ZoneCompanionInterference(string nucid, double loKev, double hiKev,
                                                                    Func<double, double> windowShare,
                                                                    Func<double, double> efficiency)
        {
            if (string.IsNullOrEmpty(nucid) || windowShare == null || !(hiKev > loKev))
            {
                return null;
            }

            try
            {
                var report = new Report();
                double own = 0.0, strongest = 0.0, lineKev = double.NaN;
                foreach (double[] line in DecayLines(nucid, report))
                {
                    double weight = line[1] * Eff(efficiency, line[0]) * Share(windowShare, line[0]);
                    if (weight > 0.0)
                    {
                        own += weight;
                        if (weight > strongest)
                        {
                            strongest = weight;
                            lineKev = line[0];
                        }
                    }
                }

                if (!(own > 0.0))
                {
                    return null;
                }

                // Линии спутника, лежащие вне окна, в него не попадают и так;
                // полоса расширена на шесть ширин окна — хвост гаусса широкой зоны.
                double pad = 3.0 * (hiKev - loKev);
                FsaLineInterference best = null;
                foreach (Companion companion in CompanionsOf(nucid, null, report))
                {
                    double foreign = 0.0;
                    foreach (double[] line in CompanionLines(companion.Isotope, companion.PerUnit,
                                                             loKev - pad, hiKev + pad, report))
                    {
                        foreign += line[1] * Eff(efficiency, line[0]) * Share(windowShare, line[0]);
                    }

                    double factor = (own + foreign) / own;
                    if (factor >= InterferenceWarnFactor && (best == null || factor > best.Factor))
                    {
                        best = new FsaLineInterference
                        {
                            LineKev = lineKev,
                            Component = PrettyName(nucid),
                            Companion = PrettyName(companion.Isotope.Nucid),
                            Reference = companion.Reference,
                            ActivityRatio = companion.ActivityRatio,
                            Factor = factor
                        };
                    }
                }

                return best;
            }
            catch (Exception error)
            {
                // Отказ базы — предупреждения нет; число зоны от него не зависит.
                FsaDatabaseFailures.Note("nucdb.sqlite", nucid, error);
                return null;
            }
        }

        static double Share(Func<double, double> windowShare, double energy)
        {
            double value = windowShare(energy);
            return value > 0.0 && !double.IsNaN(value) && !double.IsInfinity(value) ? Math.Min(value, 1.0) : 0.0;
        }

        /// <summary>
        /// (`AMBER118`) Один компонент против ряда одного спутника; null — помехи нет.
        ///
        /// Строку держит её ГЛАВНАЯ группа линий — линии компонента, стоящие
        /// ближе ПШПВ, сложены (прибор их не разделяет), и главная — с наибольшим
        /// «выход × эффективность». Множитель судится по ней одной: свободная
        /// строка Ra-226 держится на 186 кэВ, а слабый рентген Rn рядом с
        /// обильным рентгеном ряда U-235 (Ra-223, Th-227: 80–100 кэВ) строку не
        /// двигает — суммой по всем линиям он давал ×3.96 вместо ×1.72. В колонке
        /// ряда главная группа — Pb/Bi-214, и 186 кэВ о ней не говорит.
        /// </summary>
        static FsaLineInterference Interfere(FsaComponent component, Primordial companion, double perUnit,
                                             Func<double, double> fwhmKev, Func<double, double> efficiency,
                                             double loKev, double hiKev, Report report)
        {
            // Группы: {энергия сильнейшей, её вес, Σ своё, Σ чужое}; линия — {энергия, номер группы}.
            var ownLines = new List<double[]>();
            foreach (FsaLine line in component.Lines)
            {
                if (line.Energy < loKev || line.Energy > hiKev)
                {
                    continue;
                }

                double weight = line.Intensity * Eff(efficiency, line.Energy);
                if (weight > 0.0)
                {
                    ownLines.Add(new[] { line.Energy, weight });
                }
            }

            if (ownLines.Count == 0 || fwhmKev == null)
            {
                return null;
            }

            ownLines.Sort((a, b) => a[0].CompareTo(b[0]));
            var groups = new List<double[]>();
            var groupOf = new int[ownLines.Count];
            double anchor = double.NaN;
            for (int i = 0; i < ownLines.Count; i++)
            {
                double[] line = ownLines[i];
                double width = fwhmKev(line[0]);
                if (groups.Count == 0 || !(line[0] - anchor <= width))
                {
                    groups.Add(new[] { line[0], line[1], 0.0, 0.0 });
                    anchor = line[0];
                }

                double[] group = groups[groups.Count - 1];
                group[2] += line[1];
                if (line[1] > group[1])
                {
                    group[0] = line[0];
                    group[1] = line[1];
                }

                groupOf[i] = groups.Count - 1;
            }

            // Ряд спутника — его подряд равновесия (`T259`) с долями ветвления
            // (`CompanionLines`, одно место с зоной ROI, `S199`).
            foreach (double[] line in CompanionLines(companion, perUnit, loKev, hiKev, report))
            {
                double window = fwhmKev(line[0]);
                if (!(window > 0.0))
                {
                    continue;
                }

                // Ложится на группу ближайшей линии компонента в пределах ПШПВ.
                int target = -1;
                double best = double.MaxValue;
                for (int i = 0; i < ownLines.Count; i++)
                {
                    double away = Math.Abs(ownLines[i][0] - line[0]);
                    if (away <= window && away < best)
                    {
                        best = away;
                        target = groupOf[i];
                    }
                }

                double weight = line[1] * Eff(efficiency, line[0]);
                if (target >= 0 && weight > 0.0)
                {
                    groups[target][3] += weight;
                }
            }

            double[] main = groups[0];
            foreach (double[] group in groups)
            {
                if (group[2] > main[2])
                {
                    main = group;
                }
            }

            double factor = (main[2] + main[3]) / main[2];
            if (!(factor >= InterferenceWarnFactor))
            {
                return null;
            }

            return new FsaLineInterference
            {
                LineKev = main[0],
                Component = component.Name,
                Companion = PrettyName(companion.Nucid),
                Factor = factor
            };
        }

        static double Eff(Func<double, double> efficiency, double energy)
        {
            if (efficiency == null)
            {
                return 1.0;
            }

            double value = efficiency(energy);
            return value > 0.0 && !double.IsNaN(value) && !double.IsInfinity(value) ? value : 0.0;
        }

        /// <summary>(`AMBER118`) Первичный нуклид: nucid, Z, распространённость %, период, с.</summary>
        /// <summary>
        /// (`AMBER236`; Amber 19.10.2026, консоль, дословно: «Возможно ли указывать в
        /// отчёте FSA отдельной строкой в таком случае, что U-235 обеднён и указывать
        /// %?»; вопросником: «Всегда, со словом-вердиктом», «Массовая доля, %», «σ
        /// разбора + разброс членов») ИЗОТОПНЫЙ СОСТАВ ЭЛЕМЕНТА ПО РАЗБОРУ.
        ///
        /// ⛔ ИМЁН ЗДЕСЬ НЕТ. Для каждого обнаруженного компонента ищется его
        /// первичный предок (<see cref="PrimordialAncestors"/>), и активность предка
        /// оценивает только компонент из ЕГО ЖЕ отрезка ряда
        /// (<see cref="ChainSegments"/>): Th-234 и Pa-234m — оценки U-238, а Ra-226 —
        /// нет, его отрезок может стоять оборванным. Колонка связанного ряда — одна
        /// оценка (амплитуда в распадах корня); свободные члены — по оценке на член.
        /// У элемента, у которого обнаружено два и больше первичных изотопов, —
        /// строка на каждый, кроме самого распространённого в природе.
        ///
        /// Счёт: оценки изотопа сводятся средним с весом 1/σ² (σ = скорость / z);
        /// N ∝ A·T½, масса ∝ N·(массовое число); доля — среди обнаруженных
        /// первичных изотопов элемента, природная — среди них же по
        /// `nuclides.abundance`. σ — переносом σ средних (только статистика);
        /// разброс членов — доля при средних, сдвинутых на взвешенный разброс оценок
        /// своих членов в противоположные стороны (у одной оценки разброса нет).
        /// Приговор: |доля − природная| против k·√(σ² + (разброс/2)²), k — квантиль
        /// порога решения разбора (<paramref name="k"/>).
        ///
        /// Отношение двух колонок не требует абсолютной шкалы — масштаб кривой
        /// сокращается, — но требует её формы: без учтённой кривой или матрицы
        /// строки нет.
        /// </summary>
        public static List<FsaIsotopeRatio> IsotopeRatiosOf(FsaResult result, double k)
        {
            var found = new List<FsaIsotopeRatio>();
            if (result == null || result.Components == null
                || !(result.ResponseMatrixUsed || result.EfficiencyUsed))
            {
                return found;
            }

            try
            {
                var report = new Report();
                var estimates = new Dictionary<string, List<double[]>>(StringComparer.OrdinalIgnoreCase);
                var isotopes = new Dictionary<string, Primordial>(StringComparer.OrdinalIgnoreCase);
                var linked = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (FsaComponentResult component in result.Components)
                {
                    if (component == null
                        || (component.Kind != FsaComponentKind.Single && component.Kind != FsaComponentKind.Chain)
                        || string.IsNullOrEmpty(component.Name)
                        || !(component.CountRate > 0.0) || !(component.Z > 0.0))
                    {
                        continue;
                    }

                    bool chain = !string.IsNullOrEmpty(component.ChainRoot);
                    if (chain && !linked.Add(component.ChainRoot))
                    {
                        continue;
                    }

                    string unit = NucidOf(chain ? component.ChainRoot : component.Name);
                    if (unit.Length == 0)
                    {
                        continue;
                    }

                    foreach (Primordial ancestor in PrimordialAncestors(unit, report))
                    {
                        if (!string.Equals(ancestor.Nucid, unit, StringComparison.OrdinalIgnoreCase))
                        {
                            string segment;
                            if (!ChainSegments(ancestor.Nucid, report).SegmentOf.TryGetValue(unit, out segment)
                                || !string.Equals(segment, ancestor.Nucid, StringComparison.OrdinalIgnoreCase))
                            {
                                continue;
                            }
                        }

                        List<double[]> list;
                        if (!estimates.TryGetValue(ancestor.Nucid, out list))
                        {
                            estimates[ancestor.Nucid] = list = new List<double[]>();
                            isotopes[ancestor.Nucid] = ancestor;
                        }

                        list.Add(new[] { component.CountRate, component.CountRate / component.Z });
                    }
                }

                var byZ = new Dictionary<int, List<Primordial>>();
                foreach (Primordial isotope in isotopes.Values)
                {
                    List<Primordial> list;
                    if (!byZ.TryGetValue(isotope.Z, out list))
                    {
                        byZ[isotope.Z] = list = new List<Primordial>();
                    }

                    list.Add(isotope);
                }

                foreach (List<Primordial> element in byZ.Values)
                {
                    if (element.Count < 2)
                    {
                        continue;
                    }

                    element.Sort((a, b) => string.CompareOrdinal(a.Nucid, b.Nucid));
                    int n = element.Count;
                    var mean = new double[n];
                    var sigma = new double[n];
                    var spread = new double[n];
                    var mass = new double[n];
                    bool several = false;
                    for (int i = 0; i < n; i++)
                    {
                        List<double[]> list = estimates[element[i].Nucid];
                        double weights = 0.0, sum = 0.0;
                        foreach (double[] e in list)
                        {
                            double w = 1.0 / (e[1] * e[1]);
                            weights += w;
                            sum += w * e[0];
                        }

                        mean[i] = sum / weights;
                        sigma[i] = 1.0 / Math.Sqrt(weights);
                        double scatter = 0.0;
                        foreach (double[] e in list)
                        {
                            scatter += (e[0] - mean[i]) * (e[0] - mean[i]) / (e[1] * e[1]);
                        }

                        spread[i] = Math.Sqrt(scatter / weights);
                        several |= list.Count > 1;
                        mass[i] = MassNumberOf(element[i].Nucid);
                    }

                    int top = 0;
                    for (int i = 1; i < n; i++)
                    {
                        if (element[i].Abundance > element[top].Abundance)
                        {
                            top = i;
                        }
                    }

                    for (int i = 0; i < n; i++)
                    {
                        if (i == top || !(mass[i] > 0.0))
                        {
                            continue;
                        }

                        double share = MassShare(i, mean, element, mass, 0, null);
                        // σ: перенос относительных σ средних всех изотопов элемента
                        double total = 0.0;
                        var x = new double[n];
                        for (int j = 0; j < n; j++)
                        {
                            x[j] = mean[j] * element[j].Seconds * mass[j];
                            total += x[j];
                        }

                        double variance = 0.0;
                        for (int j = 0; j < n; j++)
                        {
                            double derivative = j == i ? (total - x[i]) / (total * total) : -x[i] / (total * total);
                            double sx = x[j] * sigma[j] / mean[j];
                            variance += derivative * derivative * sx * sx;
                        }

                        double natural = 0.0, naturalTotal = 0.0;
                        for (int j = 0; j < n; j++)
                        {
                            naturalTotal += element[j].Abundance * mass[j];
                        }

                        natural = 100.0 * element[i].Abundance * mass[i] / naturalTotal;
                        var others = new List<string>();
                        for (int j = 0; j < n; j++)
                        {
                            if (j != i)
                            {
                                others.Add(PrettyName(element[j].Nucid));
                            }
                        }

                        var ratio = new FsaIsotopeRatio
                        {
                            Isotope = PrettyName(element[i].Nucid),
                            Others = string.Join("+", others.ToArray()),
                            MassPercent = 100.0 * share,
                            SigmaPercent = 100.0 * Math.Sqrt(variance),
                            NaturalPercent = natural
                        };

                        double half = 0.0;
                        if (several)
                        {
                            ratio.LowPercent = 100.0 * MassShare(i, mean, element, mass, -1, spread);
                            ratio.HighPercent = 100.0 * MassShare(i, mean, element, mass, +1, spread);
                            half = 0.5 * Math.Abs(ratio.HighPercent - ratio.LowPercent);
                        }

                        double band = k * Math.Sqrt(ratio.SigmaPercent * ratio.SigmaPercent + half * half);
                        double difference = ratio.MassPercent - ratio.NaturalPercent;
                        ratio.Verdict = Math.Abs(difference) <= band ? FsaIsotopeVerdict.Natural
                                        : difference < 0.0 ? FsaIsotopeVerdict.Depleted
                                        : FsaIsotopeVerdict.Enriched;
                        found.Add(ratio);
                    }
                }
            }
            catch (Exception error)
            {
                // Отказ базы — строки нет; разбор от неё не зависит. Молча — нельзя (`AMBER199`).
                FsaDatabaseFailures.Note("nucdb.sqlite", "isotope ratios", error);
            }

            return found;
        }

        /// <summary>
        /// (`AMBER236`) Массовая доля изотопа <paramref name="i"/> при активностях
        /// <paramref name="mean"/>; <paramref name="side"/> ≠ 0 — свой изотоп
        /// сдвинут на <paramref name="side"/>·разброс, прочие — в обратную сторону.
        /// </summary>
        static double MassShare(int i, double[] mean, List<Primordial> element, double[] mass,
                                int side, double[] spread)
        {
            double own = 0.0, total = 0.0;
            for (int j = 0; j < mean.Length; j++)
            {
                double activity = mean[j];
                if (side != 0)
                {
                    activity += (j == i ? side : -side) * spread[j];
                }

                double x = Math.Max(0.0, activity) * element[j].Seconds * mass[j];
                total += x;
                if (j == i)
                {
                    own = x;
                }
            }

            return total > 0.0 ? own / total : double.NaN;
        }

        /// <summary>(`AMBER236`) Массовое число из `nucid` («235U» → 235); 0 — не разобрать.</summary>
        static int MassNumberOf(string nucid)
        {
            int i = 0, mass = 0;
            while (i < nucid.Length && nucid[i] >= '0' && nucid[i] <= '9')
            {
                mass = mass * 10 + (nucid[i] - '0');
                i++;
            }

            return mass;
        }

        sealed class Primordial
        {
            public string Nucid;
            public int Z;
            public double Abundance;
            public double Seconds;
        }

        /// <summary>
        /// (`AMBER118`) Первичные предки нуклида — вверх по `decay_chain`, у
        /// которых сам нуклид — член подряда равновесия (или он сам первичен).
        /// От каждого элемента берётся предок с НАИБОЛЬШЕЙ распространённостью
        /// (U-238, а не U-234 — тот и не первичен).
        /// </summary>
        static List<Primordial> PrimordialAncestors(string nucid, Report report)
        {
            lock (Gate)
            {
                List<Primordial> cached;
                if (AncestorCache.TryGetValue(nucid, out cached))
                {
                    return cached;
                }
            }

            int failuresBefore = FsaDatabaseFailures.ThreadCount;
            var byZ = new Dictionary<int, Primordial>();
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { nucid };
            var level = new List<string> { nucid };
            using (SqliteConnection connection = OpenRead(NuclideDatabasePath()))
            using (SqliteCommand parents = connection.CreateCommand())
            {
                parents.CommandText = "select distinct nucid from decay_chain d where daughter_nucid = $n"
                                      + " and nucid <> daughter_nucid" + DecayParentRule.ChainLevelClause;
                parents.Parameters.AddWithValue("$n", nucid);
                for (int depth = 0; depth <= MaxAncestorDepth && level.Count > 0; depth++)
                {
                    var next = new List<string>();
                    foreach (string current in level)
                    {
                        Primordial self = PrimordialOf(connection, current);
                        if (self != null
                            && (string.Equals(current, nucid, StringComparison.OrdinalIgnoreCase)
                                || EquilibriumMembers(current, report).Contains(nucid)))
                        {
                            Primordial had;
                            if (!byZ.TryGetValue(self.Z, out had) || self.Abundance > had.Abundance)
                            {
                                byZ[self.Z] = self;
                            }
                        }

                        parents.Parameters["$n"].Value = current;
                        using (SqliteDataReader reader = parents.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                string parent = reader.IsDBNull(0) ? null : reader.GetString(0);
                                if (!string.IsNullOrEmpty(parent) && seen.Add(parent))
                                {
                                    next.Add(parent);
                                }
                            }
                        }
                    }

                    level = next.Count <= MaxAncestorNodes ? next : next.GetRange(0, MaxAncestorNodes);
                }
            }

            var result = new List<Primordial>(byZ.Values);
            // (`AMBER199`) отказ вложенного читателя (подряд равновесия) — не в кэш
            if (FsaDatabaseFailures.ThreadCount == failuresBefore)
            {
                lock (Gate)
                {
                    AncestorCache[nucid] = result;
                }
            }

            return result;
        }

        /// <summary>(`AMBER118`) Потолок ширины слоя обхода вверх: искусственные родители (Pu, Cm, …) ветвятся.</summary>
        const int MaxAncestorNodes = 200;

        /// <summary>(`AMBER118`) {нуклид → первичные предки}.</summary>
        static readonly Dictionary<string, List<Primordial>> AncestorCache =
            new Dictionary<string, List<Primordial>>(StringComparer.OrdinalIgnoreCase);

        /// <summary>(`AMBER118`) Первичные изотопы элемента.</summary>
        static List<Primordial> PrimordialIsotopes(int z)
        {
            var list = new List<Primordial>();
            using (SqliteConnection connection = OpenRead(NuclideDatabasePath()))
            using (SqliteCommand command = connection.CreateCommand())
            {
                command.CommandText = "select distinct nucid from nuclides where z = $z"
                                      + " and abundance is not null and abundance <> ''";
                command.Parameters.AddWithValue("$z", z);
                var names = new List<string>();
                using (SqliteDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        if (!reader.IsDBNull(0))
                        {
                            names.Add(reader.GetString(0));
                        }
                    }
                }

                foreach (string name in names)
                {
                    Primordial item = PrimordialOf(connection, name);
                    if (item != null)
                    {
                        list.Add(item);
                    }
                }
            }

            return list;
        }

        /// <summary>(`AMBER118`) Нуклид первичен — период ≥ 10⁸ лет и распространённость > 0; иначе null.</summary>
        static Primordial PrimordialOf(SqliteConnection connection, string nucid)
        {
            using (SqliteCommand command = connection.CreateCommand())
            {
                command.CommandText = "select z, abundance, half_life_sec from nuclides where nucid = $n"
                                      + " and half_life_sec is not null order by l_seqno limit 1";
                command.Parameters.AddWithValue("$n", nucid);
                using (SqliteDataReader reader = command.ExecuteReader())
                {
                    double abundance, seconds;
                    if (!reader.Read() || reader.IsDBNull(0)
                        || !TryNumber(reader, 1, out abundance) || !(abundance > 0.0)
                        || !TryNumber(reader, 2, out seconds) || !(seconds >= PrimordialSeconds))
                    {
                        return null;
                    }

                    return new Primordial
                    {
                        Nucid = nucid,
                        Z = Convert.ToInt32(reader.GetValue(0), CultureInfo.InvariantCulture),
                        Abundance = abundance,
                        Seconds = seconds
                    };
                }
            }
        }

        /// <summary>
        /// Период полураспада в секундах из `nuclides.half_life_sec` — по
        /// самому нижнему уровню `l_seqno` (имя в таблице не уникально:
        /// `144TBm` — три строки). <c>false</c> — нуклида нет или он стабилен.
        /// </summary>
        static bool TryHalfLifeSeconds(string nucid, out double seconds)
        {
            seconds = 0.0;
            using (SqliteConnection connection = OpenRead(NuclideDatabasePath()))
            using (SqliteCommand command = connection.CreateCommand())
            {
                command.CommandText =
                    "select half_life_sec from nuclides where nucid = $n"
                    + " and half_life_sec is not null order by l_seqno limit 1";
                command.Parameters.AddWithValue("$n", nucid);
                using (SqliteDataReader reader = command.ExecuteReader())
                {
                    return reader.Read() && TryNumber(reader, 0, out seconds);
                }
            }
        }

        /// <summary>
        /// Члены ряда, С КОТОРЫМИ КОРЕНЬ МОЖЕТ БЫТЬ В РАВНОВЕСИИ (`T259`): обход
        /// `decay_chain` от корня вниз тем же ребром, что у
        /// <see cref="ChainBranches"/>, но дочерний открывается, только если его
        /// период КОРОЧЕ периода корня; член длиннее корня не входит сам и
        /// закрывает всё, что под ним (оно питается только через него).
        /// Стабильные концы (период пуст) пропускаются как есть — у них нет ни
        /// распада, ни линий, и <see cref="ChainBranches"/> их держит.
        ///
        /// Физика: переходное равновесие возможно лишь при T½(дочь) короче
        /// T½(родитель); Pb-210 (22.2 г) за часы съёмки радона (3.82 сут) не
        /// нарастает вовсе (A/A₀ ≈ λ·t ~ 10⁻⁵), и предъявлять его 46.5 кэВ одной
        /// амплитудой с Pb-214/Bi-214 значит навязать пробе то, чего в ней нет
        /// (П64 §6: со связкой на угле Ra-226 2 %, Pb-210 1.5 % — оба ложные).
        /// У голов рядов и Th-228 члена длиннее корня нет, множество равно всему
        /// обходу, и состав от правила не меняется — измерено побитово.
        /// </summary>
        internal static HashSet<string> EquilibriumMembers(string root, Report report)
        {
            lock (Gate)
            {
                HashSet<string> cached;
                if (EquilibriumCache.TryGetValue(root, out cached))
                {
                    return cached;
                }
            }

            var reachable = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { root };
            int failuresBefore = FsaDatabaseFailures.ThreadCount;
            try
            {
                double rootSeconds;
                if (!TryHalfLifeSeconds(root, out rootSeconds))
                {
                    // Периода у корня нет — обрывать не по чему: берётся весь обход,
                    // как до `T259`, и об этом сказано.
                    report.Notes.Add("ряд от " + root + ": периода корня в nuclides нет — подряд не обрывается");
                    foreach (string member in ChainBranches(root, report).Keys)
                    {
                        reachable.Add(member);
                    }
                }
                else
                {
                    var order = new List<string> { root };
                    using (SqliteConnection connection = OpenRead(NuclideDatabasePath()))
                    using (SqliteCommand edges = connection.CreateCommand())
                    using (SqliteCommand life = connection.CreateCommand())
                    {
                        edges.CommandText =
                            "select daughter_nucid," + DecayParentRule.ChainPercColumn + " from" + DecayParentRule.ChainTable + " d"
                            + " where nucid = $n and perc not null"
                            + DecayParentRule.ChainLevelClause;
                        edges.Parameters.AddWithValue("$n", root);
                        life.CommandText =
                            "select half_life_sec from nuclides where nucid = $n"
                            + " and half_life_sec is not null order by l_seqno limit 1";
                        life.Parameters.AddWithValue("$n", root);
                        for (int i = 0; i < order.Count && order.Count <= MaxChainNodes; i++)
                        {
                            string current = order[i];
                            edges.Parameters["$n"].Value = current;
                            var daughters = new List<string>();
                            using (SqliteDataReader reader = edges.ExecuteReader())
                            {
                                while (reader.Read())
                                {
                                    string daughter = reader.IsDBNull(0) ? null : reader.GetString(0);
                                    double percent;
                                    if (string.IsNullOrEmpty(daughter)
                                        || string.Equals(daughter, current, StringComparison.OrdinalIgnoreCase)
                                        || !TryNumber(reader, 1, out percent) || !(percent > 0.0)
                                        || reachable.Contains(daughter))
                                    {
                                        continue;
                                    }

                                    daughters.Add(daughter);
                                }
                            }

                            foreach (string daughter in daughters)
                            {
                                life.Parameters["$n"].Value = daughter;
                                double seconds = 0.0;
                                bool decays;
                                using (SqliteDataReader reader = life.ExecuteReader())
                                {
                                    decays = reader.Read() && TryNumber(reader, 0, out seconds);
                                }

                                if (decays && !(seconds < rootSeconds))
                                {
                                    // Длиннее корня (или равен ему): не в равновесии,
                                    // и всё под ним закрыто.
                                    continue;
                                }

                                if (reachable.Add(daughter) && decays)
                                {
                                    order.Add(daughter);
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception error)
            {
                report.Notes.Add("ряд от " + root + ": отказ базы при обходе равновесия — " + error.Message);
                FsaDatabaseFailures.Note("nucdb.sqlite", root, error);
                foreach (string member in ChainBranches(root, report).Keys)
                {
                    reachable.Add(member);
                }
            }

            // ⛔ (`AMBER199`) отказ — не в кэш: следующий разбор спросит базу снова
            if (FsaDatabaseFailures.ThreadCount == failuresBefore)
            {
                lock (Gate)
                {
                    EquilibriumCache[root] = reachable;
                }
            }

            return reachable;
        }

        /// <summary>
        /// {nucid → накопленная доля ветвления от корня}, только основные
        /// состояния родителя.
        ///
        /// Правило `l_seqno` — <see cref="DecayParentRule.ChainLevelClause"/>,
        /// одно на весь проект (`A218`); `tools/CORPUS/scripts/chains.py`
        /// читает ЕГО ЖЕ, прямо из исходника. Оно не косметическое: строки с
        /// `l_seqno` больше минимального описывают распад ВОЗБУЖДЁННОГО уровня
        /// и дублируют переход с другим ветвлением (у 212BI это 35.94 % при
        /// нуле и 67 % при пяти). Изомер при этом имеет собственный `nucid`
        /// (234PAm1), поэтому наименьший присутствующий уровень и есть
        /// физический распад.
        ///
        /// ⚠ Метод ОТКРЫТ ради проб, а не ради приложения: обходов ряда в
        /// дереве три (здесь, `NucBase.NucBaseFramework.GetChainBranches` и
        /// `tools/CORPUS/scripts/chains.py`), и разойтись они уже успели —
        /// `S62`. Сверять их между собой можно только имея доступ ко всем трём;
        /// читатель этой сверки — `ChainProbe`, раздел «два обхода ряда».
        /// </summary>
        public static Dictionary<string, double> ChainBranches(string root, Report report)
        {
            lock (Gate)
            {
                Dictionary<string, double> cached;
                if (ChainCache.TryGetValue(root, out cached))
                {
                    return cached;
                }
            }

            var branch = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
            int failuresBefore = FsaDatabaseFailures.ThreadCount;
            try
            {
                // Шаг 1: РЁБРА. Обход в ширину здесь только открывает узлы, а
                // доли не считает вовсе — см. шаг 2, почему это принципиально.
                var edges = new Dictionary<string, List<KeyValuePair<string, double>>>(
                    StringComparer.OrdinalIgnoreCase);
                var order = new List<string> { root };
                var known = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { root };
                using (SqliteConnection connection = OpenRead(NuclideDatabasePath()))
                using (SqliteCommand command = connection.CreateCommand())
                {
                    // (`A218`) Зажим по уровню — из `DecayParentRule`, как и у
                    // `parent_l_seqno`: второго соглашения о том, что считать
                    // ребром ряда, в проекте быть не должно.
                    command.CommandText =
                        "select daughter_nucid," + DecayParentRule.ChainPercColumn + " from" + DecayParentRule.ChainTable + " d"
                        + " where nucid = $n and perc not null"
                        + DecayParentRule.ChainLevelClause;
                    command.Parameters.AddWithValue("$n", root);
                    for (int i = 0; i < order.Count && order.Count <= MaxChainNodes; i++)
                    {
                        string current = order[i];
                        command.Parameters["$n"].Value = current;
                        var step = new List<KeyValuePair<string, double>>();
                        using (SqliteDataReader reader = command.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                string daughter = reader.IsDBNull(0) ? null : reader.GetString(0);
                                if (string.IsNullOrEmpty(daughter)
                                    || string.Equals(daughter, current, StringComparison.OrdinalIgnoreCase))
                                {
                                    // 238U несёт самопетлю на l_seqno-119.
                                    continue;
                                }

                                double percent;
                                if (!TryNumber(reader, 1, out percent) || !(percent > 0.0))
                                {
                                    continue;
                                }

                                step.Add(new KeyValuePair<string, double>(daughter, percent));
                                if (known.Add(daughter))
                                {
                                    order.Add(daughter);
                                }
                            }
                        }

                        edges[current] = step;
                    }
                }

                // Шаг 2: ДОЛИ РЕЛАКСАЦИЕЙ ДО НЕПОДВИЖНОЙ ТОЧКИ (`S62`).
                //
                // ⛔ Обход в ширину здесь давал ответ НА ПОРЯДКИ НЕВЕРНЫЙ, и
                // причина в том, что он раскрывает узел один раз — значением,
                // какое у того было В МОМЕНТ раскрытия. Вклад, пришедший к тому
                // же узлу позже, детям уже не передавался. В радиевом ряду
                // Pb-210 попадает в очередь раньше Po-214, который и даёт ему
                // почти всю долю: сам Pb-210 выходил верным (1.0), а его дети —
                // 3e-5 вместо 1.0, то есть ниже `MinChainBranch` = 1e-3, и из
                // библиотеки выпадали вовсе.
                //
                // Доля — это СУММА ПО ВСЕМ ПУТЯМ от корня, x = e_root + x*P,
                // и считается она повторением подстановки: за проход вклад
                // продвигается на одно ребро, значит сходимость наступает за
                // число проходов, равное длине самого длинного пути. Ряды
                // короткие (два десятка членов), но зажим по числу проходов
                // стоит на случай кольца в поставке.
                double drift = 0.0;
                for (int pass = 0; pass < MaxChainPasses; pass++)
                {
                    var next = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                    next[root] = 1.0;
                    foreach (string parent in order)
                    {
                        double have;
                        List<KeyValuePair<string, double>> outgoing;
                        if (!branch.TryGetValue(parent, out have) || !(have > 0.0)
                            || !edges.TryGetValue(parent, out outgoing))
                        {
                            continue;
                        }

                        foreach (KeyValuePair<string, double> edge in outgoing)
                        {
                            double add = have * edge.Value / 100.0;
                            double already;
                            next[edge.Key] = (next.TryGetValue(edge.Key, out already) ? already : 0.0) + add;
                        }
                    }

                    drift = 0.0;
                    foreach (KeyValuePair<string, double> row in next)
                    {
                        double was;
                        double gap = Math.Abs(row.Value - (branch.TryGetValue(row.Key, out was) ? was : 0.0));
                        if (gap > drift)
                        {
                            drift = gap;
                        }
                    }

                    branch = next;
                    if (drift <= ChainConverged)
                    {
                        break;
                    }
                }

                if (drift > ChainConverged)
                {
                    // Признак отказа без читателя — не признак. Ряд, не
                    // сошедшийся за отведённые проходы, означает кольцо в
                    // поставке, и молчать об этом нельзя.
                    report.Notes.Add("ряд " + root + ": доли не сошлись за "
                                     + MaxChainPasses.ToString(CultureInfo.InvariantCulture) + " проходов, остаток "
                                     + drift.ToString("E2", CultureInfo.InvariantCulture));
                }
            }
            catch (Exception error)
            {
                // Отказ базы не должен ронять разбор — но и молчать нельзя:
                // «ряд пуст» и «читатель сломан» с виду одно и то же.
                report.Notes.Add("ряд " + root + ": отказ базы — " + error.Message);
                FsaDatabaseFailures.Note("nucdb.sqlite", root, error);
            }

            // ⛔ (`AMBER199`) отказ — не в кэш
            if (FsaDatabaseFailures.ThreadCount == failuresBefore)
            {
                lock (Gate)
                {
                    ChainCache[root] = branch;
                }
            }

            return branch;
        }

        /// <summary>
        /// {nucid → ГЛУБИНА от корня по `decay_chain`}: сам корень 0, его
        /// дочерние 1, их дочерние 2 и так далее. Кратчайший путь, потому что
        /// обход в ширину, — а у ветвящегося ряда (212BI даёт и 208TL, и
        /// 212PO) путей до одного члена несколько.
        ///
        /// ⚠ Заведено ради `S65` и ТОЛЬКО ради порядка: доли ветвления обходом
        /// в ширину считать нельзя (`S62`, ответ выходил на порядки неверным),
        /// и здесь они не считаются вовсе. Здесь нужен ПОРЯДОК членов —
        /// «кто выше по ряду», — а он у обхода в ширину как раз верен.
        ///
        /// Рёбра берутся тем же запросом и тем же правилом `l_seqno`, что у
        /// <see cref="ChainBranches"/>: второе соглашение о том, что считать
        /// ребром ряда, развело бы порядок с составом.
        /// </summary>
        internal static Dictionary<string, int> ChainDepths(string root, Report report)
        {
            lock (Gate)
            {
                Dictionary<string, int> cached;
                if (DepthCache.TryGetValue(root, out cached))
                {
                    return cached;
                }
            }

            var depth = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            int failuresBefore = FsaDatabaseFailures.ThreadCount;
            try
            {
                var order = new List<string> { root };
                depth[root] = 0;
                using (SqliteConnection connection = OpenRead(NuclideDatabasePath()))
                using (SqliteCommand command = connection.CreateCommand())
                {
                    command.CommandText =
                        "select daughter_nucid," + DecayParentRule.ChainPercColumn + " from" + DecayParentRule.ChainTable + " d"
                        + " where nucid = $n and perc not null"
                        + DecayParentRule.ChainLevelClause;
                    command.Parameters.AddWithValue("$n", root);
                    for (int i = 0; i < order.Count && order.Count <= MaxChainNodes; i++)
                    {
                        string current = order[i];
                        command.Parameters["$n"].Value = current;
                        using (SqliteDataReader reader = command.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                string daughter = reader.IsDBNull(0) ? null : reader.GetString(0);
                                if (string.IsNullOrEmpty(daughter)
                                    || string.Equals(daughter, current, StringComparison.OrdinalIgnoreCase))
                                {
                                    // 238U несёт самопетлю на l_seqno-119.
                                    continue;
                                }

                                double percent;
                                if (!TryNumber(reader, 1, out percent) || !(percent > 0.0))
                                {
                                    continue;
                                }

                                if (!depth.ContainsKey(daughter))
                                {
                                    depth[daughter] = depth[current] + 1;
                                    order.Add(daughter);
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception error)
            {
                report.Notes.Add("ряд " + root + ": отказ базы при обходе глубин — " + error.Message);
                FsaDatabaseFailures.Note("nucdb.sqlite", root, error);
            }

            // ⛔ (`AMBER199`) отказ — не в кэш
            if (FsaDatabaseFailures.ThreadCount == failuresBefore)
            {
                lock (Gate)
                {
                    DepthCache[root] = depth;
                }
            }

            return depth;
        }

        /// <summary>
        /// (`AMBER236`) С какого периода член ряда может СТОЯТЬ ОБОРВАННЫМ: год.
        ///
        /// Химия рвёт ряд на любом члене, но короткоживущий дочерний нарастает
        /// снова за несколько своих периодов, и в пробе он через год уже в
        /// равновесии с ближайшим долгоживущим предком; долгоживущий — нет, его
        /// отсутствие держится годами. Поэтому места возможного обрыва — члены с
        /// периодом не короче этого числа.
        ///
        /// ⚠ Число не подбирается и не двигает ни одного природного ряда: по
        /// `nucdb` самый долгий из «коротких» членов трёх природных рядов — Po-210
        /// (138 сут, 0.379 г), самый короткий из «долгих» — Th-228 (1.91 г), и
        /// любой порог между ними даёт ОДНО И ТО ЖЕ разбиение: U-238 | U-234 |
        /// Th-230 | Ra-226 … Po-214 | Pb-210 … Po-210; U-235 + Th-231 | Pa-231 |
        /// Ac-227 …; Th-232 | Ra-228 + Ac-228 | Th-228 …. Год взят серединой этого
        /// окна на логарифмической шкале с запасом в обе стороны.
        /// </summary>
        internal const double ChainBreakSeconds = 365.25 * 86400.0;

        /// <summary>
        /// (`AMBER236`) Ряд, разрезанный на ОТРЕЗКИ по долгоживущим членам
        /// (<see cref="ChainBreakSeconds"/>): корень и каждый долгоживущий член
        /// открывают свой отрезок, короткоживущий дочерний идёт в отрезок своего
        /// родителя. Внутри отрезка равновесие наступает само за год; между
        /// отрезками его может не быть вовсе — урановое стекло (Th-230 и всё ниже
        /// вымыто химией), точечный Th-228 (нет Ra-228 и Ac-228), обеднённый уран.
        /// </summary>
        internal sealed class ChainSegmentation
        {
            /// <summary>{член → голова его отрезка}.</summary>
            public readonly Dictionary<string, string> SegmentOf =
                new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

            /// <summary>Головы отрезков в порядке обхода от корня (корень первым).</summary>
            public readonly List<string> Order = new List<string>();

            /// <summary>{голова отрезка → головы отрезков, которые он питает непосредственно}.</summary>
            public readonly Dictionary<string, HashSet<string>> Below =
                new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
        }

        /// <summary>
        /// (`AMBER236`) Разбиение ряда <paramref name="root"/> на отрезки — тем же
        /// обходом в ширину и тем же ребром, что <see cref="ChainDepths"/>, и с
        /// периодом из `nuclides.half_life_sec`, как у <see cref="EquilibriumMembers"/>.
        /// Член, достижимый из двух отрезков без долгоживущего члена на стыке,
        /// остаётся в том, через который обход пришёл первым (кратчайший путь);
        /// в природных рядах таких нет — ветви сходятся на Pb-210 и стабильных
        /// концах. Отказ базы — пустое разбиение (резать не по чему) и замечание.
        /// </summary>
        internal static ChainSegmentation ChainSegments(string root, Report report)
        {
            lock (Gate)
            {
                ChainSegmentation cached;
                if (SegmentCache.TryGetValue(root, out cached))
                {
                    return cached;
                }
            }

            var result = new ChainSegmentation();
            int failuresBefore = FsaDatabaseFailures.ThreadCount;
            try
            {
                var order = new List<string> { root };
                result.SegmentOf[root] = root;
                result.Order.Add(root);
                result.Below[root] = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                using (SqliteConnection connection = OpenRead(NuclideDatabasePath()))
                using (SqliteCommand edges = connection.CreateCommand())
                using (SqliteCommand life = connection.CreateCommand())
                {
                    edges.CommandText =
                        "select daughter_nucid," + DecayParentRule.ChainPercColumn + " from" + DecayParentRule.ChainTable + " d"
                        + " where nucid = $n and perc not null"
                        + DecayParentRule.ChainLevelClause;
                    edges.Parameters.AddWithValue("$n", root);
                    life.CommandText =
                        "select half_life_sec from nuclides where nucid = $n"
                        + " and half_life_sec is not null order by l_seqno limit 1";
                    life.Parameters.AddWithValue("$n", root);
                    for (int i = 0; i < order.Count && order.Count <= MaxChainNodes; i++)
                    {
                        string current = order[i];
                        string currentSegment = result.SegmentOf[current];
                        edges.Parameters["$n"].Value = current;
                        var daughters = new List<string>();
                        using (SqliteDataReader reader = edges.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                string daughter = reader.IsDBNull(0) ? null : reader.GetString(0);
                                double percent;
                                if (string.IsNullOrEmpty(daughter)
                                    || string.Equals(daughter, current, StringComparison.OrdinalIgnoreCase)
                                    || !TryNumber(reader, 1, out percent) || !(percent > 0.0))
                                {
                                    continue;
                                }

                                daughters.Add(daughter);
                            }
                        }

                        foreach (string daughter in daughters)
                        {
                            string known;
                            if (result.SegmentOf.TryGetValue(daughter, out known))
                            {
                                // Второй путь в уже пройденный член: стык отрезков —
                                // только если он открыл свой (долгоживущий).
                                if (!string.Equals(known, currentSegment, StringComparison.OrdinalIgnoreCase)
                                    && string.Equals(known, daughter, StringComparison.OrdinalIgnoreCase))
                                {
                                    result.Below[currentSegment].Add(daughter);
                                }

                                continue;
                            }

                            life.Parameters["$n"].Value = daughter;
                            double seconds = 0.0;
                            bool decays;
                            using (SqliteDataReader reader = life.ExecuteReader())
                            {
                                decays = reader.Read() && TryNumber(reader, 0, out seconds);
                            }

                            if (decays && seconds >= ChainBreakSeconds)
                            {
                                result.SegmentOf[daughter] = daughter;
                                result.Order.Add(daughter);
                                result.Below[daughter] = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                                result.Below[currentSegment].Add(daughter);
                            }
                            else
                            {
                                result.SegmentOf[daughter] = currentSegment;
                            }

                            order.Add(daughter);
                        }
                    }
                }
            }
            catch (Exception error)
            {
                report.Notes.Add("ряд " + root + ": отказ базы при разбиении на отрезки — " + error.Message);
                FsaDatabaseFailures.Note("nucdb.sqlite", root, error);
                result = new ChainSegmentation();
            }

            // ⛔ (`AMBER199`) отказ — не в кэш
            if (FsaDatabaseFailures.ThreadCount == failuresBefore)
            {
                lock (Gate)
                {
                    SegmentCache[root] = result;
                }
            }

            return result;
        }

        /// <summary>Сколько членов ряда открывать, зажим против поставки-кольца.</summary>
        const int MaxChainNodes = 128;

        /// <summary>
        /// Сколько проходов релаксации отводится ряду. За проход вклад
        /// продвигается на одно ребро; самый длинный из наших рядов (238U) —
        /// два десятка звеньев, так что запас здесь десятикратный.
        /// </summary>
        const int MaxChainPasses = 256;

        /// <summary>
        /// Порог сходимости долей. Он на три порядка ниже `MinChainBranch`
        /// (1e-3), то есть заведомо не влияет на то, кто в ряд попадёт.
        /// </summary>
        const double ChainConverged = 1.0e-12;

        /// <summary>Строка `type_c` — не L-серия.</summary>
        public const int LSeriesNone = 0;

        /// <summary>Сводная строка L-серии (`L`): центр тяжести и суммарный выход.</summary>
        public const int LSeriesLumped = 1;

        /// <summary>Итог подоболочки (`L1`, `L2`, `L3`).</summary>
        public const int LSeriesShell = 2;

        /// <summary>Линия подоболочечного перехода (`L3M5`, `L2N4`…).</summary>
        public const int LSeriesDetailed = 3;

        /// <summary>
        /// (`AMBER68`, `AMBER151`) Вид строки L-серии по СТРУКТУРЕ имени `type_c`:
        /// одна буква — сводная, буква и цифра — итог подоболочки, длиннее — линия.
        /// Чем больше число, тем подробнее строка; читатель берёт у родителя самый
        /// подробный вид, какой есть, и только его — <see cref="DecayLines"/> и
        /// редактор базы (`NucBaseFramework`) зовут ОДНО это правило. С 01.10.2026
        /// сводная `L` поставки лежит в базе рядом со своими подлиниями
        /// (`tools/nucdb/import_l_sublines.py`), и сложить их значило бы удвоить
        /// L-рентген.
        /// </summary>
        public static int LSeriesKind(string series)
        {
            series = (series ?? "").Trim();
            if (series.Length == 0 || series[0] != 'L')
            {
                return LSeriesNone;
            }

            if (series.Length == 1)
            {
                return LSeriesLumped;
            }

            if (series.Length == 2 && series[1] >= '0' && series[1] <= '9')
            {
                return LSeriesShell;
            }

            return LSeriesDetailed;
        }

        /// <summary>
        /// Линии распада нуклида: {энергия, выход % на распад ЭТОГО нуклида}.
        /// Типы `G` и `X`; K-серия по правилу <see cref="KSeriesRule"/> — ОДНО
        /// правило на весь проект, общее с <see cref="CascadeAtomicData"/>
        /// (двух соглашений о Kβ здесь быть не должно: разойдясь в них,
        /// библиотека и суммирователь совпадений разойдутся в составе пробы
        /// при одинаковых с виду числах, `T50`). L-серия — подробными
        /// строками, если они есть, иначе обобщённой.
        ///
        /// ⛔ АННИГИЛЯЦИОННАЯ ЛИНИЯ β⁺-ИЗЛУЧАТЕЛЯ — ЛИНИЯ ЕГО РАСПАДА (`AMBER54`,
        /// П124 22.09.2026): строки `B+` базы читаются тем же запросом, и на
        /// <see cref="FsaAnalyzer.AnnihilationKev"/> в образ ложится линия с
        /// выходом `2·ΣI(β⁺)` — два кванта на позитрон, ровно то число, что
        /// суммирователь совпадений уже считал партнёром
        /// (<see cref="CascadeAtomicData.AnnihilationQuanta"/>); второго
        /// соглашения о нём здесь нет. До П124 запрос брал только `G` и `X`:
        /// у 22NA сильнейшая линия (179.8 % на распад) в образ не входила и
        /// уходила свободному `Ann-511`, 18F (одни позитроны) образа не имел
        /// вовсе — «библиотека опустела». Настоящая гамма той же энергии, если
        /// она есть у нуклида, СКЛАДЫВАЕТСЯ с аннигиляционной — две линии
        /// одной энергии, как у `S161`. Имён нуклидов здесь нет: кто β⁺ —
        /// говорит база. (П127 22.09.2026) Строка аннигиляционной линии несёт
        /// ТРЕТЬЕ число — аннигиляционную часть выхода — и оно уезжает в
        /// <see cref="FsaLine.AnnihilationIntensity"/>: гейт `Ann-511`
        /// анализатора (`AMBER7` → `AMBER54`) различает по нему гамму состава
        /// у 511 и свою аннигиляцию нуклида.
        /// </summary>
        /// ⚠ Открыт наружу РАДИ ЧИТАТЕЛЯ (`S89`): два места в проекте читают
        /// `decay_radiations` с разными зажимами, и «оба обязаны давать один
        /// I_K» — утверждение, которое надо проверять прогоном, а не глазами.
        /// Проверяет `DecayReadersProbe`; внутри приложения зовут его только
        /// отсюда.
        public static List<double[]> DecayLines(string nucid, Report report)
        {
            lock (Gate)
            {
                List<double[]> cached;
                if (LineCache.TryGetValue(nucid, out cached))
                {
                    return cached;
                }
            }

            var gamma = new List<double[]>();

            // (`S161`) Канал каждой гамма-строки — ТОЛЬКО на время чтения, чтобы
            // отличить копию одной линии от двух линий разных каналов. Наружу
            // не уходит и вместе с `gamma` никуда не передаётся: список живёт
            // ровно до конца цикла чтения, где обе стороны видны в двух строках
            // кода. Дальше `lines` собирается как прежде, из одних чисел.
            var gammaChannel = new List<string>();
            var kAlpha = new List<double[]>();
            var kBetaSplit = new List<double[]>();
            var kBetaSplitSeries = new HashSet<string>(StringComparer.Ordinal);
            var kBetaTotal = new List<double[]>();
            var lLumped = new List<double[]>();
            var lShell = new List<double[]>();
            var lDetailed = new List<double[]>();

            // (`AMBER54`) Позитроны на распад, % — сумма ВСЕХ строк `B+` (каналов
            // и переходов): каждый позитрон аннигилирует, откуда бы ни пришёл.
            double betaPlus = 0.0;

            // (`AMBER199`) счётчик отказов до чтения: отказ этого чтения ИЛИ
            // вложенного (выход аннигиляции через `CascadeAtomicData`) — не в кэш
            int failuresBefore = FsaDatabaseFailures.ThreadCount;
            try
            {
                using (SqliteConnection connection = OpenRead(NuclideDatabasePath()))
                using (SqliteCommand command = connection.CreateCommand())
                {
                    // ⚠ Тот же зажим по `parent_l_seqno`, что и у ряда, и по той
                    // же причине: Pa-234m1 несёт линию 1001.03 кэВ на уровне 2, а
                    // не на нуле, поэтому «= 0» здесь потеряло бы её целиком.
                    // (`S89`) Само правило вынесено в `DecayParentRule` — двух
                    // соглашений о том, что такое «родитель», в проекте быть не
                    // должно, ровно как и о K-серии.
                    // (`AMBER54`) Строки `B+` — тем же запросом: у них
                    // `energy_num` — средняя энергия позитрона, и она здесь не
                    // нужна, поэтому зажим «энергия не пуста» к ним не относится.
                    // ⛔ (`AMBER274`, `f8diag`) Строка-предел (`LT`/`LE`) — не выход: ни
                    // гамма, ни рентген, ни позитроны β⁺ (`DecayParentRule.NotLimitClause`).
                    command.CommandText =
                        "select type_a, type_c, energy_num, intensity_num, dec_type"
                        + " from decay_radiations"
                        + " where parent_nucid = $n and type_a in ('G', 'X', 'B+')"
                        + " and (energy_num not null or type_a = 'B+') and intensity_num > 0"
                        + DecayParentRule.NotLimitClause
                        + DecayParentRule.LevelClause;
                    command.Parameters.AddWithValue("$n", nucid);
                    using (SqliteDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            string kind = reader.IsDBNull(0) ? "" : reader.GetString(0);
                            string series = reader.IsDBNull(1) ? "" : reader.GetString(1).Trim();
                            string channel = reader.IsDBNull(4) ? "" : reader.GetString(4).Trim();
                            double energy, intensity;
                            if (kind == "B+")
                            {
                                if (TryNumber(reader, 3, out intensity) && intensity > 0.0)
                                {
                                    betaPlus += intensity;
                                }

                                continue;
                            }

                            if (!TryNumber(reader, 2, out energy) || !TryNumber(reader, 3, out intensity)
                                || !(energy > 0.0) || !(intensity > 0.0))
                            {
                                continue;
                            }

                            var line = new[] { energy, intensity };
                            if (kind == "G")
                            {
                                // ⛔ ДВЕ СТРОКИ ОДНОЙ ЭНЕРГИИ ИЗ РАЗНЫХ КАНАЛОВ —
                                // ДВЕ НАСТОЯЩИЕ ЛИНИИ, И ВЫХОДЫ СКЛАДЫВАЮТСЯ
                                // (`S161`). Ниже по пути `AddLine` выбрасывает
                                // вторую линию той же энергии, и у `33NA` на
                                // 221 кэВ оставалось 1.914 % вместо
                                // 0.31 + 1.914 = 2.224 %.
                                //
                                // ⛔ НО «СКЛАДЫВАТЬ ВСЕГДА» НЕЛЬЗЯ, и это
                                // измерено: пар линий ближе 0.05 кэВ у одного
                                // родителя в поставке 190, из них 186 у 115
                                // родителей — С ОДНИМ И ТЕМ ЖЕ `dec_type`, то
                                // есть копии ОДНОЙ линии (своя строка и строка
                                // «в цепочке», либо копия с округлённой
                                // энергией). Их сложение удвоило бы вес — ровно
                                // тот дефект, против которого отсев в `AddLine`
                                // и заводился, — а четверо из этих 115 в
                                // КОРПУСЕ (`152EU`, `227TH`, `231PA`, `234PA`).
                                // С разными `dec_type` пар всего ЧЕТЫРЕ у трёх
                                // родителей, и корпусных среди них нет.
                                //
                                // ⚠ Канал живёт ТОЛЬКО здесь и наружу не
                                // уходит: слияние делается на месте чтения, а
                                // `AddLine` со своим правилом не меняется
                                // ни на волос.
                                int same = -1;
                                for (int k = 0; k < gamma.Count; k++)
                                {
                                    if (Math.Abs(gamma[k][0] - energy) < 0.05
                                        && !string.Equals(gammaChannel[k], channel,
                                                          StringComparison.Ordinal))
                                    {
                                        same = k;
                                        break;
                                    }
                                }

                                if (same >= 0)
                                {
                                    gamma[same][1] += intensity;
                                }
                                else
                                {
                                    gamma.Add(line);
                                    gammaChannel.Add(channel);
                                }
                            }
                            else if (series.Length == 0 || series[0] != 'K')
                            {
                                // ⛔ (`AMBER68`, П130 22.09.2026) ТРИ ВИДА СТРОК
                                // L-СЕРИИ, А НЕ ДВА. Рядом в поставке лежат
                                // сводная `L`, ИТОГИ ПОДОБОЛОЧЕК `L1`/`L2`/`L3`
                                // и отдельные линии `L1M2`, `L2N4`, `L3O1`… До
                                // П130 итоги и линии валились в один список
                                // «подробных» (длина имени > 1) и СКЛАДЫВАЛИСЬ:
                                // у `229TH` 56.390 + 61.060 = 117.450 % против
                                // сводной `L` 80.0 %, у `225RA` 22.171 + 23.329
                                // против 29.107, у `225RN` 19.436 + 19.764
                                // против 41.200 (замер 22.09.2026 по `nucdb`,
                                // чтение `ro`; таких родителей в поставке ТРИ).
                                // Вес L-рентгена в образе выходил завышен в
                                // полтора раза.
                                //
                                // Признак — СТРУКТУРА имени, как у K-серии
                                // (<see cref="KSeriesRule"/>): одна буква —
                                // сводная, буква и цифра — итог подоболочки,
                                // длиннее — линия (за цифрой стоит оболочка,
                                // откуда пришёл электрон). Порядок предпочтения
                                // тот же, что был: линии, если они есть, иначе
                                // итоги подоболочек, иначе сводная.
                                //
                                // (`AMBER151`, П202 01.10.2026) Признак вынесен в
                                // <see cref="LSeriesKind"/>: с этого дня сводную `L`
                                // поставки рядом с её подлиниями (`import_l_sublines.py`)
                                // вытесняет и редактор базы, и правило там ДОЛЖНО
                                // быть тем же самым, а не копией.
                                switch (LSeriesKind(series))
                                {
                                    case LSeriesLumped:
                                        lLumped.Add(line);
                                        break;
                                    case LSeriesShell:
                                        lShell.Add(line);
                                        break;
                                    case LSeriesDetailed:
                                        lDetailed.Add(line);
                                        break;
                                }
                            }
                            else if (KSeriesRule.IsBetaTotal(series))
                            {
                                kBetaTotal.Add(line);
                            }
                            else if (KSeriesRule.IsBetaSplit(series))
                            {
                                kBetaSplit.Add(line);
                                kBetaSplitSeries.Add(series);
                            }
                            else
                            {
                                kAlpha.Add(line);
                            }
                        }
                    }
                }
            }
            catch (Exception error)
            {
                report.Notes.Add("линии " + nucid + ": отказ базы — " + error.Message);
                FsaDatabaseFailures.Note("nucdb.sqlite", nucid, error);
            }

            // (`AMBER54`) Аннигиляционная линия: два кванта 511 кэВ на позитрон.
            // Настоящая гамма той же энергии (у 17 родителей поставки есть строка
            // `G` в 510.5…511.4) СКЛАДЫВАЕТСЯ, а не теряется: `AddLine` ниже по
            // пути выбросил бы вторую линию той же энергии того же нуклида, и
            // выход ушёл бы молча — тот же довод, что у `S161`. Допуск слияния —
            // тот же, что у `AddLine` и `S161` (0.05 кэВ).
            //
            // (П127 22.09.2026) Строка аннигиляционной линии — ТРЁХ чисел:
            // {энергия, выход, аннигиляционная часть выхода}; у гаммы и рентгена
            // строки по-прежнему из двух. Третье число едет в
            // <see cref="FsaLine.AnnihilationIntensity"/>: гейт `Ann-511`
            // анализатора обязан отличать «столкнулся с гаммой состава» от
            // «это своя аннигиляция нуклида», а по одной энергии слитой линии
            // этого не видно. Читатели `DecayLines` берут `[0]` и `[1]`, третьего
            // числа не замечают.
            //
            // (`AMBER69`, П130 22.09.2026) Выход берётся ЗАЖАТЫМ, и зажим не
            // свой, а сумматора совпадений — см. <see cref="AnnihilationYieldPercent"/>.
            if (betaPlus > 0.0)
            {
                double annihilation = AnnihilationYieldPercent(nucid, betaPlus, report);
                int same = -1;
                for (int k = 0; k < gamma.Count; k++)
                {
                    if (Math.Abs(gamma[k][0] - FsaAnalyzer.AnnihilationKev) < 0.05)
                    {
                        same = k;
                        break;
                    }
                }

                if (same >= 0)
                {
                    gamma[same] = new[] { gamma[same][0], gamma[same][1] + annihilation, annihilation };
                }
                else
                {
                    gamma.Add(new[] { FsaAnalyzer.AnnihilationKev, annihilation, annihilation });
                }
            }

            var lines = new List<double[]>();
            lines.AddRange(gamma);
            lines.AddRange(kAlpha);

            // Kβ: итог `KB`, если он есть, иначе разложение — но там, где
            // разложение ПОЛНОЕ, берётся именно оно: то же число двумя
            // энергиями вместо одной усреднённой. Правило и его измерение —
            // `KSeriesRule` (`T50`); прежнее «разложение, если оно есть»
            // занижало Kβ у 350 наборов.
            // (`AMBER120`) Строки группы K-M — на центре тяжести группы, а не на
            // середине текстового диапазона: см. <see cref="KSeriesRule.BetaAtGroupEnergy"/>.
            lines.AddRange(KSeriesRule.BetaAtGroupEnergy(kBetaSplit, kBetaTotal, kBetaSplitSeries.Count, kAlpha));

            // L-серия: та же развилка, но по ТРЁМ спискам (`AMBER68`) — линии
            // подоболочек, итоги подоболочек, сводная. Подробных строк в базе
            // всего у трёх нуклидов (225RA, 225RN, 229TH), и ни один в корпусе
            // не снят, — но правило дешевле проверки «а вдруг».
            //
            // ⚠ Линии НЕ ПОКРЫВАЮТ сводную целиком, и это измерено: у `229TH`
            // они дают 61.060 % против сводной `L` 80.0 % (у `225RA` 23.329
            // против 29.107, у `225RN` 19.764 против 41.200). Сложение итогов
            // с линиями этого не лечило, а делало вдвое хуже с другой стороны
            // (117.450 против 80.0). Что из двух представлений полнее —
            // вопрос ОТДЕЛЬНЫЙ от двойного счёта, и здесь он не решается:
            // порядок предпочтения оставлен прежним.
            lines.AddRange(lDetailed.Count > 0 ? lDetailed
                           : (lShell.Count > 0 ? lShell : lLumped));

            lines.Sort((a, b) => a[0].CompareTo(b[0]));
            if (FsaDatabaseFailures.ThreadCount == failuresBefore)
            {
                lock (Gate)
                {
                    LineCache[nucid] = lines;
                }
            }

            return lines;
        }

        /// <summary>
        /// (`AMBER69`, П130 22.09.2026) Выход аннигиляционной линии нуклида,
        /// % на распад: два кванта на позитрон, а ΣI(β⁺) поставки — ЗАЖАТЫЙ
        /// долей ветви и потолком в 100 % распадов.
        ///
        /// ⛔ ЧИСЛО ЗДЕСЬ НЕ СЧИТАЕТСЯ. Оно берётся у сумматора совпадений
        /// (<see cref="CascadeAtomicData.AnnihilationQuanta"/>, ~~`S153`~~),
        /// который читает те же строки `B+` тем же запросом с тем же зажимом
        /// уровня (<see cref="DecayParentRule.LevelClause"/>) и зажимает сумму
        /// долей ветвей своего канала. Двух редакций одной величины в проекте
        /// быть не должно — тот же довод, что у `KSeriesRule` про Kβ. До П130
        /// библиотека клала СЫРОЙ `2·ΣI(β⁺)`, и у 25 родителей поставки они
        /// расходились: `20NA` 393.694 % в образе против 200 % у партнёра
        /// совпадения, `128LAm` 450.0 против 200, `81Y` 268.6 против 200
        /// (замер 22.09.2026 по `nucdb`, чтение `ro`). «Поставка местами даёт
        /// позитронов больше, чем есть распадов» — довод, по которому зажим и
        /// заведён. Корпусные β⁺ (`22NA` 179.8, `18F` 193.46, `65ZN` 2.842,
        /// `88Y` 0.42, `152EU` 0.0512) сырьём равны зажатому — их числа
        /// правкой не двигаются.
        ///
        /// ⚠ Потолок 200 % повторён здесь, и это НЕ третья редакция правила: у
        /// сумматора есть ранний выход по неопределённому дочернему (`z &lt;= 0`),
        /// после которого <see cref="CascadeAtomicData.AnnihilationQuanta"/>
        /// остаётся сырым; на таком нуклиде без потолка вернулось бы ровно то,
        /// что было до правки. Сказать сумматору нечего вовсе (нуклид не
        /// разобран, отказ базы) — берётся сырое число с тем же потолком, и
        /// причина уходит в <see cref="Report.Notes"/>, а не теряется.
        /// </summary>
        static double AnnihilationYieldPercent(string nucid, double rawBetaPlusPercent, Report report)
        {
            const double Ceiling = 200.0;
            double raw = 2.0 * rawBetaPlusPercent;
            CascadeAtomicData atomic = CascadeAtomicData.Of(nucid);
            double clamped = atomic != null && !atomic.Failed
                ? 100.0 * atomic.AnnihilationQuanta : 0.0;
            if (!(clamped > 0.0))
            {
                if (report != null)
                {
                    report.Notes.Add("аннигиляция " + nucid
                                     + ": сумматору совпадений сказать нечего, выход только по потолку");
                }

                return raw > Ceiling ? Ceiling : raw;
            }

            if (clamped > Ceiling)
            {
                clamped = Ceiling;
            }

            if (report != null && clamped < raw - 1.0E-9 * Math.Max(1.0, raw))
            {
                report.Notes.Add(string.Format(CultureInfo.InvariantCulture,
                    "аннигиляция {0}: 2·ΣI(β⁺) поставки {1:F3} % зажато до {2:F3} %"
                    + " (доля ветви и 100 % распадов)", nucid, raw, clamped));
            }

            return clamped;
        }

        /// <summary>
        /// (`AMBER63`, П130 22.09.2026) Аннигиляционная линия нуклида ИЗ БАЗЫ:
        /// {энергия, выход %, аннигиляционная часть выхода %} — ровно та, что
        /// <see cref="DecayLines"/> кладёт в образ на пути «Из NucBase»; null —
        /// позитронов у нуклида база не знает.
        ///
        /// ⛔ (`AMBER306`) Образ по меткам собирает <see cref="Build"/>, и линия приходит
        /// туда сама; читают этот метод пробы. Второй редакции числа здесь нет: оно то
        /// же самое и из того же места, зажатое <see cref="AnnihilationYieldPercent"/>.
        ///
        /// ⚠ Возвращается КОПИЯ: строка кэша линий уходит в образы как есть, и
        /// читателю, который её поправит, достался бы весь проект.
        /// </summary>
        public static double[] AnnihilationLine(string nucid)
        {
            if (string.IsNullOrEmpty(nucid))
            {
                return null;
            }

            foreach (double[] line in DecayLines(nucid, new Report()))
            {
                if (line != null && line.Length > 2 && line[2] > 0.0
                    && Math.Abs(line[0] - FsaAnalyzer.AnnihilationKev) < 0.05)
                {
                    return new[] { line[0], line[1], line[2] };
                }
            }

            return null;
        }

        // ------------------------------------------------------------------
        // Атомные образы: рентген пробы, кристалла, защиты и пики вылета
        // ------------------------------------------------------------------

        /// <summary>
        /// Флуоресценция пробы, кристалла и защиты плюс вылет K-рентгена
        /// кристалла. Всё — мешающими образами со свободной амплитудой: за
        /// этими линиями нет активности, и в «пирог» долей они не входят.
        /// </summary>
        static void AddAtomic(FsaSampleSpec spec, List<FsaComponent> result,
                              HashSet<string> declared, Report report)
        {
            var seen = new HashSet<int>();

            // ⛔ КРИСТАЛЛ ПЕРВЫМ (`A30`, решение Amber 12.09.2026: «Снять заслон:
            // сводить кристалл ВСЕГДА»). Занятость элемента решает ПОРЯДОК:
            // кто построил образ раньше, тот элемент и держит (`seen`). До
            // 12.09.2026 первыми шли проба и защита, и элемент кристалла,
            // встреченный у них, ронял сведение вещества — заслон в
            // <see cref="AddCrystalFluorescence"/>. Теперь кристалл занимает
            // свои элементы до всех, а образ пробы или защиты на тот же элемент
            // не строится: второй колонки на те же отсчёты нет, и гейт
            // `AMBER4` снимает весь рентген кристалла одним флагом.
            //
            // Прежний порядок — ключом <see cref="FsaSampleSpec.CrystalShield"/>,
            // ради положительного контроля лестницы плеч.
            if (spec.CrystalShield)
            {
                AddFluorescence(spec, spec.SampleElements, "проба", result, report, seen);
                AddFluorescence(spec, spec.ShieldElements, "защита", result, report, seen);
                if (!AddCrystalFluorescence(spec, result, report, seen))
                {
                    AddFluorescence(spec, spec.CrystalElements, "кристалл", result, report, seen, true);
                }
            }
            else
            {
                if (!AddCrystalFluorescence(spec, result, report, seen))
                {
                    AddFluorescence(spec, spec.CrystalElements, "кристалл", result, report, seen, true);
                }

                AddFluorescence(spec, spec.SampleElements, "проба", result, report, seen);
                AddFluorescence(spec, spec.ShieldElements, "защита", result, report, seen);
            }

            AddEscape(spec, result, declared, report);
        }

        /// <summary>
        /// ⛔ СОБСТВЕННЫЙ РЕНТГЕН КРИСТАЛЛА — ОДИН ОБРАЗ НА ВЕЩЕСТВО (`A29`,
        /// решение Amber 01.09.2026), а не по образу на элемент.
        ///
        /// Довод тот же, по которому `S84` свёл в одно образы ВЫЛЕТА, и здесь он
        /// подтверждён замером на `Чароит в домике` (прибор ASN16, кристалл CsI):
        /// образ `Xray-I` собирался исправно, тремя линиями, а фит давал ему
        /// РОВНО НОЛЬ — `z = 0.00`, снят отсевом значимости, — и весь рентген
        /// кристалла забирал `Xray-Cs` (1.15 % доли). Разделить их данные не
        /// могут: Kα иода 28.612 и цезия 30.97 кэВ отстоят на 2.4 кэВ при ПШПВ
        /// прибора около девяти в этой полосе, то есть колонки почти
        /// коллинеарны, и выбор между ними физического смысла не несёт. Человеку
        /// же на легенде показывалась ПОЛОВИНА вещества, будто иода в кристалле
        /// нет.
        ///
        /// Соотношение членов задаёт ВЕЩЕСТВО: массовая доля элемента (из
        /// геометрии, через <see cref="CrystalMix"/>) на его выход флуоресценции
        /// ω_K (из `matdb`), а внутри K-серии — веса самой серии. Свободная
        /// амплитуда у образа одна.
        ///
        /// ⚠ ЭТО ПРИБЛИЖЕНИЕ, и называть его надо приближением: возбуждает
        /// K-дырки ВЕСЬ падающий спектр, а не одна линия, поэтому строгий вес
        /// члена — свёртка сечения фотопоглощения элемента со спектром. Взято
        /// отношение «массовая доля × ω_K», то есть предположение о равных
        /// сечениях; для CsI оно дёшево — Z 55 против 53, K-края 35.98 и 33.17
        /// кэВ, ω_K 0.894 против 0.884.
        ///
        /// Возвращает false, если вещества кристалла нет (тогда зовущий строит
        /// образы поэлементно, как раньше).
        ///
        /// ⛔ ЗАСЛОН ПО ЗАНЯТОМУ ЭЛЕМЕНТУ СНЯТ (`A30`, решение Amber 12.09.2026).
        /// Проверка «элемент кристалла уже занят образом пробы либо защиты →
        /// не сводить» ниже осталась, но при штатном порядке
        /// <see cref="AddAtomic"/> кристалл идёт ПЕРВЫМ и `seen` пуст — она не
        /// срабатывает никогда. Срабатывает она только под ключом
        /// <see cref="FsaSampleSpec.CrystalShield"/>, где порядок прежний; довод
        /// заслона («общий образ спорил бы за те же отсчёты со своей же
        /// половиной») перевешен измеренной ценой: пара колонок не доживает до
        /// разбора, а сведённый образ доживает (журнал П2 10.09.2026 §2.2).
        /// </summary>
        static bool AddCrystalFluorescence(FsaSampleSpec spec, List<FsaComponent> result,
                                           Report report, HashSet<int> seen)
        {
            foreach (int z in spec.CrystalElements)
            {
                if (z > 0 && seen.Contains(z))
                {
                    report.Notes.Add("рентген кристалла: Z="
                                     + z.ToString(CultureInfo.InvariantCulture)
                                     + " уже занят образом пробы или защиты, вещество не сводится");
                    return false;
                }
            }

            CrystalMix mix = CrystalMix.Of(spec, report);
            if (mix == null)
            {
                return false;
            }

            var component = new FsaComponent("Xray-" + mix.Name, FsaComponentKind.Nuisance);

            // (`AMBER4`) Это образ САМОГО прибора: при живой матрице отклика он
            // снимается гейтом, потому что матрица уже несёт K-вакансию и её
            // вылет отдельным каналом отклика (`ResponseChannel.EscapeXray`).
            component.FromCrystal = true;
            foreach (CrystalMix.Part part in mix.Parts)
            {
                MaterialDatabase.Fluorescence fluorescence = part.Fluorescence;
                double omega = fluorescence.Omega(true);

                // Метка линии — СВОЙ элемент, а не имя образа: отсев дубля в
                // `AddLine` сверяет пару «метка + энергия», а линии Kβ соседних
                // элементов кристалла сходятся близко (у CsI 32.68 иода и 34.99
                // цезия), и с общей меткой одна из них однажды пропала бы молча.
                string tag = "Xray-" + part.Tag.Substring(4);
                for (int i = 0; i < fluorescence.LineKev.Length; i++)
                {
                    double energy = fluorescence.LineKev[i];
                    double weight = fluorescence.LineWeight[i];

                    // S98: пол библиотеки тот же, что у остальных образов.
                    if (!(energy > 0.0) || !(weight > 0.0)
                        || energy < spec.LineFloorKev || energy > spec.MaxEnergyKev)
                    {
                        continue;
                    }

                    AddLine(component, tag, energy, 100.0 * weight * part.Fraction * omega);
                }
            }

            if (component.Lines.Count == 0)
            {
                return false;
            }

            foreach (int z in spec.CrystalElements)
            {
                if (z > 0)
                {
                    seen.Add(z);
                }
            }

            result.Add(component);
            report.Lines += component.Lines.Count;
            return true;
        }

        static void AddFluorescence(FsaSampleSpec spec, List<int> elements, string what,
                                    List<FsaComponent> result, Report report, HashSet<int> seen,
                                    bool fromCrystal = false)
        {
            foreach (int z in elements)
            {
                if (z <= 0)
                {
                    continue;
                }

                if (!seen.Add(z))
                {
                    // (`A30`) Элемент пробы или защиты, который уже держит
                    // образ кристалла, называется, а не пропадает молча: по
                    // этой заметке в `LibraryNote` прогона видно, у каких
                    // спектров случай вообще возник. Дубль пробы в защите
                    // (свинец там и там) — не находка, о нём молчим, как и
                    // прежде; под ключом заслона кристалл идёт последним, и
                    // заметка была бы ложью — там молчим тоже.
                    if (!fromCrystal && !spec.CrystalShield && spec.CrystalElements.Contains(z))
                    {
                        report.Notes.Add("рентген " + what + ": Z="
                                         + z.ToString(CultureInfo.InvariantCulture)
                                         + " — элемент кристалла, сведён в его образ, свой не строится");
                    }

                    continue;
                }

                // L-серия — ТОЛЬКО у элементов ВНЕ кристалла (`AMBER10`). У
                // самого кристалла её отсчёты приходят другим путём: L-вылет
                // считает перенос (`A60`, `EfficiencySimulator`), и второй образ
                // на те же события завёл бы спор двух счетоводств — ту самую
                // беду, ради которой заведён гейт `S47`.
                if (!fromCrystal)
                {
                    FsaComponent lseries = LFluorescenceComponent(z, spec.LineFloorKev,
                                                                  spec.MaxEnergyKev);
                    if (lseries != null)
                    {
                        result.Add(lseries);
                        report.Lines += lseries.Lines.Count;
                    }
                }

                FsaComponent component = FluorescenceComponent(z, spec.LineFloorKev, spec.MaxEnergyKev);
                if (component == null)
                {
                    report.Notes.Add("нет K-серии для Z=" + z.ToString(CultureInfo.InvariantCulture)
                                     + " (" + what + ")");
                    continue;
                }

                if (component.Lines.Count > 0)
                {
                    component.FromCrystal = fromCrystal;
                    result.Add(component);
                    report.Lines += component.Lines.Count;
                }
            }
        }

        /// <summary>
        /// Образ характеристического рентгена элемента — ОДНО место на проект.
        ///
        /// Вынесено 01.09.2026 по решению Amber (`S110`, пункты 2–3): у пути
        /// приложения лежала ВТОРАЯ копия того же знания — зашитые `Xray-W` и
        /// `Xray-Pb` по четыре строки, — и копии успели разойтись. Измерено на
        /// той же базе: Kα в обеих совпадали точно, а группа Kβ в коде стояла
        /// на других энергиях и была занижена в 1.4 раза (W: 30.0 против 42.2;
        /// Pb: 31.0 против 44.5 в нормировке на Kα1 = 100). Теперь обе стороны
        /// зовут это.
        ///
        /// ⛔ L-серия сюда НЕ идёт, и это не забывчивость: в
        /// `matdb.xray_fluorescence` её нет вовсе — таблица держит только
        /// K-край, Kα1, Kα2 и Kβ. Собрать L пришлось бы из `eadl_radiative`,
        /// считая веса внутри серии самому; решением Amber 18.08.2026 в `S56`
        /// это не входит.
        /// </summary>
        /// <returns>Образ либо null, если K-серии для этого Z в базе нет.</returns>
        public static FsaComponent FluorescenceComponent(int z, double floorKev, double maxKev)
        {
            MaterialDatabase.Fluorescence fluorescence = MaterialDatabase.FluorescenceOf(z);
            if (fluorescence == null || fluorescence.LineKev == null)
            {
                return null;
            }

            var component = new FsaComponent("Xray-" + MaterialDatabase.SymbolOf(z),
                                             FsaComponentKind.Nuisance);
            for (int i = 0; i < fluorescence.LineKev.Length; i++)
            {
                // S98: и здесь снизу режет пол библиотеки. Это НЕ мелочь:
                // при `Min_Range` = 30 кэВ у иода кристалла выбрасывались
                // ОБЕ линии Kα (28.317 и 28.612 кэВ, вместе 81.3 % веса
                // K-серии), и образ `Xray-I` состоял из одной Kβ 32.68.
                // Мерено 25.08.2026: так было во ВСЕХ 81 спектре понятной
                // части корпуса. Образ, у которого выброшена главная линия,
                // не «неполный» — он стоит не там, и амплитуду забирает
                // чужую.
                double energy = fluorescence.LineKev[i];
                double weight = fluorescence.LineWeight[i];
                if (!(energy > 0.0) || !(weight > 0.0)
                    || energy < floorKev || energy > maxKev)
                {
                    continue;
                }

                // Вес — доля ВНУТРИ K-серии, а не выход на распад: у
                // характеристического рентгена выхода на распад не
                // существует (атом светит, когда в K появилась дырка, а
                // сколько их — дело геометрии и спектра возбуждения). Ровно
                // поэтому образ и мешающий.
                AddLine(component, component.Name, energy, 100.0 * weight);
            }

            return component;
        }

        /// <summary>
        /// Образ характеристического L-рентгена элемента — ОТДЕЛЬНЫМ образом от
        /// K-серии, а не её линиями.
        ///
        /// ⛔ ОТДЕЛЬНАЯ АМПЛИТУДА — ЭТО ФИЗИКА, А НЕ УДОБСТВО. Отношение L/K
        /// задаёт не атом, а глубина выхода: у свинца квант 75 кэВ выходит из
        /// слоя ~0.4 мм, квант 11 кэВ — из ~10 мкм, то есть в сорок раз тоньше,
        /// и доля зависит от того, чем и с какой стороны свинец засвечен.
        /// Измерено 09.09.2026 по пяти сценам ASN16 (избыток над подложкой,
        /// L 7.5…15.5 кэВ против Pb K 68…92 кэВ): `Cs 137 в домике` 0.567,
        /// `Cs 137 28.11.2022` 0.748, `Фон в домике` 0.303. Одна общая
        /// амплитуда навязала бы им одно отношение — то есть заведомо неверное
        /// у двух сцен из трёх.
        ///
        /// Зачем вообще заведено (`AMBER10`, задача Amber 09.09.2026 «в начале
        /// спектра какая-то систематическая невязка»). На `Cs 137 в домике
        /// 24.11.2022` в полосе 9…17 кэВ модель лежит в 40…80 раз ниже
        /// измерения (при 14.3 кэВ: 145 634 против 1 866), и это не грубость
        /// континуума: у структуры ширина 4.8 кэВ при ПШПВ прибора 5.0 кэВ на
        /// 11 кэВ, то есть это ЛИНИЯ, а континуум-сплайн по построению уже́
        /// 4·ПШПВ брать не должен. Контроль отрицательный: у `Lu176`, где пика
        /// Pb K нет вовсе, нет и этой структуры (избыток над подложкой уходит в
        /// минус), — а у всех сцен, где Pb K виден, она есть.
        ///
        /// Веса подоболочек. Дырка в L рождается двумя путями — прямым
        /// фотоэффектом на L (ниже K-края это ЕДИНСТВЕННЫЙ путь) и каскадом
        /// после K-перехода. Здесь взят первый: вклад подоболочки ∝ (число
        /// электронов 2:2:4) · ω_L. ⚠ Цена выбора измерена, а не принята на
        /// веру: у свинца центр тяжести серии выходит 11.46 кэВ, а по
        /// K-каскаду (доли Kα1/Kα2 из `eadl_radiative`) — 11.41 кэВ, то есть
        /// разница 0.05 кэВ при ПШПВ 5.0 кэВ. Различить эти два распределения
        /// нашим разрешением нельзя, и спорить о них не о чем.
        ///
        /// Данные — те же, что у переноса (`A60`): `MaterialDatabase.
        /// Fluorescence.LineKevL`/`LineWeightL`/`OmegaL` из `eadl_radiative`.
        /// Второй копии знания не заводится.
        /// </summary>
        /// <returns>Образ либо null, если L-серии для этого Z в базе нет.</returns>
        public static FsaComponent LFluorescenceComponent(int z, double floorKev, double maxKev)
        {
            MaterialDatabase.Fluorescence fluorescence = MaterialDatabase.FluorescenceOf(z);
            if (fluorescence == null || !fluorescence.HasL)
            {
                return null;
            }

            // Заселённость подоболочек: L1 — 2 электрона, L2 — 2, L3 — 4.
            // Порядок массивов — L1, L2, L3, как в EADL (вакансии 3, 5, 6).
            double[] electrons = { 2.0, 2.0, 4.0 };
            var component = new FsaComponent("Xray-" + MaterialDatabase.SymbolOf(z) + "-L",
                                             FsaComponentKind.Nuisance);
            for (int li = 0; li < fluorescence.OmegaL.Length && li < electrons.Length; li++)
            {
                double[] kev = fluorescence.LineKevL[li];
                double[] weight = fluorescence.LineWeightL[li];
                if (kev == null || weight == null || !(fluorescence.OmegaL[li] > 0.0))
                {
                    continue;
                }

                double shell = electrons[li] * fluorescence.OmegaL[li];
                for (int i = 0; i < kev.Length && i < weight.Length; i++)
                {
                    double energy = kev[i];
                    if (!(energy > 0.0) || !(weight[i] > 0.0)
                        || energy < floorKev || energy > maxKev)
                    {
                        continue;
                    }

                    // Вес — доля ВНУТРИ L-серии, как и у K-образа: выхода на
                    // распад у характеристического рентгена не существует.
                    AddLine(component, component.Name, energy, 100.0 * shell * weight[i]);
                }
            }

            return component.Lines.Count > 0 ? component : null;
        }

        /// <summary>
        /// Пики вылета K-рентгена кристалла: линия E порождает вылет на
        /// E − E(Kα) того элемента кристалла, чей K-край она перешла.
        ///
        /// ⚠ ЭТО ПЕРВОЕ ПРИБЛИЖЕНИЕ, и называть его надо приближением. Честно
        /// вылет считает матрица отклика — розыгрышем переноса, с геометрией
        /// кристалла и глубиной поглощения. Здесь же вес линии берётся как
        ///
        ///     I(родителя) · f_фото(E) · доля K · ω_K,
        ///
        /// то есть без геометрической части («какая доля рождённых квантов
        /// вышла наружу»), которая от энергии почти не зависит и потому уходит
        /// в общую свободную амплитуду образа. Все три множителя — из `matdb`
        /// (`xcom_cross_sections`, `epics_photo_subshell`, `xray_fluorescence`),
        /// выдуманного в них нет.
        ///
        /// ⛔ На спектрах С МАТРИЦЕЙ этот образ спорит с ней за одни и те же
        /// отсчёты — то самое «второе счётоведение», ради прекращения которого
        /// заведён гейт `S47` (<see cref="FsaAnalyzer.EscapeGate"/>). Строится
        /// он ЗДЕСЬ всегда — библиотека не знает, пойдёт ли разбор через
        /// матрицу, — а снимает его при живой матрице анализатор, тем же
        /// гейтом и по флагу <see cref="FsaComponent.CrystalEscape"/> (`S172`,
        /// решение Amber 14.09.2026 «При матрице вылет не класть»). До того
        /// образ стоял при матрице решением 18.08.2026 «клади везде» как опора
        /// кросс-проверки (`S60`), и цена измерена П63: на радоновом фильтре
        /// ASN16 после снятия стоков-нуклидов `Esc-CsI` забрал 45.7 % экрана
        /// при z 32 — вылет не может равняться родителю. Без матрицы образ
        /// остаётся: там он единственное, чем вылет выражен. Цена самого
        /// приближения снимается ключом `AtomicXray`, а не догадкой.
        /// </summary>
        static void AddEscape(FsaSampleSpec spec, List<FsaComponent> result,
                              HashSet<string> declared, Report report)
        {
            if (spec.CrystalElements.Count == 0)
            {
                return;
            }

            // Родительские линии берутся из уже собранного состава распада: это
            // ровно те кванты, которые в кристалл прилетят.
            var parents = new List<double[]>();
            foreach (FsaComponent source in result)
            {
                // Мешающие образы отсекаются по виду, нуклидные — по имени.
                // Ряд, связанный равновесием, имеет вид `Chain`, и проверять
                // «ровно `Single`» нельзя: объявленный ториевый источник ушёл
                // бы из родителей целиком.
                if (source.Kind == FsaComponentKind.Nuisance
                    || !declared.Contains(source.Name))
                {
                    continue;
                }

                foreach (FsaLine line in source.Lines)
                {
                    if (line.Energy <= spec.EscapeParentMaxKev && line.Intensity > 0.0)
                    {
                        parents.Add(new[] { line.Energy, line.Intensity });
                    }
                }
            }

            if (parents.Count == 0)
            {
                return;
            }

            // ⛔ ОБРАЗ ВЫЛЕТА У КРИСТАЛЛА ОДИН (`S84`, решение Amber 19.08.2026),
            // а не по одному на элемент. Прежде их было столько, сколько
            // элементов, и каждому доставалась СВОЯ свободная амплитуда — а
            // различить их данные не могут: Kα цезия 30.97 и иода 28.612 кэВ
            // разводят гребёнки на 2.4 кэВ при ПШПВ прибора в десятки, и после
            // правки `S80` обе сжались в одну и ту же полосу 44…61 кэВ. Измерено
            // 19.08.2026: на одном и том же чароите выживал то `Esc-Cs`, то
            // `Esc-I`, смотря по мелочам обстановки, — то есть выбор между ними
            // не нёс физического смысла вовсе.
            //
            // Довод тот же, что у связки ряда: данные различают образ целиком, а
            // не его половину. Соотношение членов теперь задаёт ВЕЩЕСТВО —
            // массовые доли элементов кристалла, — и амплитуда у образа одна.
            CrystalMix mix = CrystalMix.Of(spec, report);
            if (mix == null)
            {
                return;
            }

            var component = new FsaComponent("Esc-" + mix.Name, FsaComponentKind.Nuisance);

            // (`S172`) Это образ САМОГО прибора — вылет из кристалла: при живой
            // матрице отклика его снимает гейт `EscapeGate`, потому что матрица
            // уже несёт K-вылет отдельным каналом (`ResponseChannel.EscapeXray`),
            // как SE/DE у `S47` и рентген кристалла у `AMBER4`.
            component.CrystalEscape = true;
            foreach (CrystalMix.Part part in mix.Parts)
            {
                MaterialDatabase.Fluorescence fluorescence = part.Fluorescence;
                MaterialDatabase.PhotoShellModel shells = part.Shells;
                MaterialDatabase.Element element = part.Element;
                double omega = fluorescence.Omega(true);
                double kAlpha = fluorescence.LineKev[0];

                // Ослабление СВОЕГО рентгена в веществе кристалла — одно на все
                // линии этого члена, поэтому считается здесь, а не в цикле.
                double muXray = mix.Attenuation(kAlpha);
                foreach (double[] parent in parents)
                {
                    // Ниже K-края дырки в K-оболочке не бывает, и вылета нет.
                    if (parent[0] <= fluorescence.KEdgeKev)
                    {
                        continue;
                    }

                    // S98: пол тот же, что у остальных образов. Одна граница на
                    // все — иначе вылет существовал бы там, где родительская
                    // линия уже нет, и наоборот.
                    double energy = parent[0] - kAlpha;
                    if (energy < spec.LineFloorKev || energy > spec.MaxEnergyKev)
                    {
                        continue;
                    }

                    // Числитель — K-поглощение ИМЕННО В ЭТОМ элементе, со своей
                    // массовой долей; знаменатель — полное ослабление ВЕЩЕСТВА
                    // кристалла. Отсюда и берётся закреплённое соотношение
                    // членов образа: у элемента, которого в кристалле вдвое
                    // меньше, вклад вдвое меньше, и фиту тут решать нечего.
                    double photo = part.Fraction
                                   * MaterialDatabase.Interpolate(element.EnergyKev,
                                                                  element.Channels[2], parent[0]);
                    double total = mix.Attenuation(parent[0]);
                    if (!(photo > 0.0) || !(total > 0.0))
                    {
                        continue;
                    }

                    double kShare = shells != null ? shells.KFraction(parent[0])
                                                   : fluorescence.KFraction;

                    // ⛔ ЧЕТВЁРТЫЙ множитель — вероятность рентгену ВЫЙТИ из
                    // кристалла (`S80`). Без него в весе стояла вероятность
                    // родить K-дырку и только она, а вылет тем самым считался
                    // одинаково возможным с любой глубины. Отсюда и брался
                    // перекос, найденный по печати линий 19.08.2026: на
                    // `Th232_29.07.2022.xml` сильнейшей линией образа выходила
                    // 210.020 кэВ (вылет из 238.632 кэВ Pb-212) с весом 18.05
                    // против 11.73 у 48.496 кэВ — то есть гребёнка была тяжелее
                    // ВВЕРХУ шкалы, где вылета быть не может вовсе.
                    double weight = parent[1] * (photo / total) * kShare * omega
                                    * EscapeFraction(muXray, total);
                    if (weight > 0.0)
                    {
                        // ⚠ Линия помечается СВОИМ членом, а не именем образа, и
                        // это не украшение. Отсев дубля в `AddLine` сверяет пару
                        // «метка + энергия», а вылеты разных элементов
                        // расходятся ровно на разницу их Kα (у CsI 2.36 кэВ) —
                        // значит две родительские линии, отстоящие на те же
                        // 2.36 кэВ, дают ОДНУ энергию вылета. У ториевого ряда
                        // такая пара есть прямо в середине: 238.632 Pb-212 и
                        // 240.986 Ra-224 дают через иод и цезий 210.020 и
                        // 210.013 кэВ. С общей меткой вторая пропала бы молча.
                        AddLine(component, part.Tag, energy, weight);
                    }
                }
            }

            Prune(component, spec.EscapeMinRelativeWeight);
            if (component.Lines.Count > 0)
            {
                result.Add(component);
                report.Lines += component.Lines.Count;
            }
        }

        /// <summary>
        /// Вещество кристалла для образа вылета: члены с их МАССОВЫМИ долями,
        /// полное ослабление смеси и короткое имя (`S84`, 19.08.2026).
        ///
        /// Заведено потому, что образ вылета у кристалла ОДИН, а соотношение его
        /// членов задаётся веществом, а не фитом. Всё, что для этого нужно, уже
        /// лежит в геометрии — <c>GeometryMaterial.Fractions</c>; раньше
        /// <see cref="HeavyElementsOf"/> оставляла от неё одни номера элементов.
        /// </summary>
        sealed class CrystalMix
        {
            internal sealed class Part
            {
                public string Tag;
                public double Fraction;
                public MaterialDatabase.Element Element;
                public MaterialDatabase.Fluorescence Fluorescence;
                public MaterialDatabase.PhotoShellModel Shells;
            }

            public readonly List<Part> Parts = new List<Part>();

            public string Name = "";

            /// <summary>
            /// Полное массовое ослабление СМЕСИ, см²/г: Σ w_i·(μ/ρ)_i. Плотность
            /// не нужна — в вес линии оно входит только отношением.
            ///
            /// ⚠ Считается по тем же членам, что и вылет, то есть по элементам,
            /// прошедшим отбор <see cref="HeavyElementsOf"/>. Лёгкая примесь
            /// (активатор, натрий ниже порога доли) в сумму не попадает, и на
            /// её долю ослабление занижено. Для CsI отбор берёт оба элемента и
            /// сумма полна.
            /// </summary>
            public double Attenuation(double kev)
            {
                // ⛔ (`AMBER80`, П149 24.09.2026) Ослабление элемента — СУММОЙ
                // КАНАЛОВ (<see cref="PartialCrossSections.MassTotal"/>,
                // ~~`AMBER74`~~), а не прямой по `Element.Total`: одно правило со
                // всеми слоями сцены и с матрицей. Прямая по сумме в узлах лежит
                // выше кривой — на CsI +0.05…+0.17 % у своего Kα и до +1.7 % на
                // 2614.5 кэВ, — и вес вылета выходил занижен на 0.02…0.25 %
                // (замер `FsaTotalReadersProbe`). Строка `AMBER74` этот
                // знаменатель называла, а до него правка не доехала.
                double mu = 0.0;
                double logKev = kev > 0.0 ? Math.Log(kev) : double.NaN;
                for (int k = 0; k < this.Parts.Count; k++)
                {
                    Part part = this.Parts[k];
                    int lo, hi;
                    if (!(kev > 0.0) || part.Element.EnergyKev == null
                        || !MaterialDatabase.Bracket(part.Element.EnergyKev, kev, out lo, out hi))
                    {
                        continue;
                    }

                    mu += part.Fraction * PartialCrossSections.MassTotal(
                        part.Element, lo, hi, kev, logKev);
                }

                return mu;
            }

            /// <summary>
            /// Собрать смесь по объявленным элементам кристалла. Доли берутся из
            /// <see cref="FsaSampleSpec.CrystalFractions"/> и нормируются на
            /// сумму ВОШЕДШИХ; доли нет — считаются равными, и об этом говорится
            /// в отчёте, а не молчится. null — строить нечего.
            /// </summary>
            public static CrystalMix Of(FsaSampleSpec spec, Report report)
            {
                var mix = new CrystalMix();
                var done = new HashSet<int>();
                double sum = 0.0;
                bool declared = spec.CrystalFractions.Count > 0;
                foreach (int z in spec.CrystalElements)
                {
                    if (z <= 0 || !done.Add(z))
                    {
                        continue;
                    }

                    MaterialDatabase.Fluorescence fluorescence = MaterialDatabase.FluorescenceOf(z);
                    MaterialDatabase.Element element;
                    if (fluorescence == null || !MaterialDatabase.TryGet(z, out element))
                    {
                        report.Notes.Add("вылет: нет данных для Z="
                                         + z.ToString(CultureInfo.InvariantCulture));
                        continue;
                    }

                    if (!(fluorescence.Omega(true) > 0.0)
                        || fluorescence.LineKev == null || fluorescence.LineKev.Length == 0
                        || !(fluorescence.LineKev[0] > 0.0))
                    {
                        continue;
                    }

                    // ⚠ Доли объявлены — значит объявлен и СОСТАВ: элемента, в
                    // них не названного, в кристалле нет, и брать его с долей
                    // «по умолчанию» нельзя. Так бывает, когда список элементов
                    // пополняется из второго источника (у пробы — `materials.csv`
                    // поверх геометрии), и незваный элемент с долей 1.0 забрал бы
                    // образ себе.
                    double fraction;
                    bool known = spec.CrystalFractions.TryGetValue(z, out fraction)
                                 && fraction > 0.0;
                    if (!known)
                    {
                        if (declared)
                        {
                            report.Notes.Add("вылет: Z="
                                             + z.ToString(CultureInfo.InvariantCulture)
                                             + " не назван в составе кристалла, пропущен");
                            continue;
                        }

                        fraction = 1.0;
                    }

                    sum += fraction;
                    mix.Parts.Add(new Part
                    {
                        Tag = "Esc-" + MaterialDatabase.SymbolOf(z),
                        Fraction = fraction,
                        Element = element,
                        Fluorescence = fluorescence,
                        Shells = MaterialDatabase.PhotoShellOf(z)
                    });
                }

                if (mix.Parts.Count == 0 || !(sum > 0.0))
                {
                    return null;
                }

                if (!declared)
                {
                    report.Notes.Add("вылет: долей кристалла нет, считаны равными");
                }

                var order = new List<Part>(mix.Parts);
                order.Sort((x, y) => y.Fraction != x.Fraction
                    ? y.Fraction.CompareTo(x.Fraction)
                    : string.CompareOrdinal(x.Tag, y.Tag));

                var name = new StringBuilder();
                foreach (Part part in order)
                {
                    part.Fraction /= sum;
                    name.Append(part.Tag.Substring(4));
                }

                mix.Name = string.IsNullOrEmpty(spec.CrystalName)
                    ? name.ToString() : spec.CrystalName;
                return mix;
            }
        }

        /// <summary>
        /// Доля K-рентгена, которая УСПЕВАЕТ ВЫЙТИ из кристалла, — четвёртый
        /// множитель веса линии вылета (`S80`, 19.08.2026).
        ///
        /// Считается точно, а не поправкой. Квант первый раз взаимодействует на
        /// глубине z с плотностью μ_E·exp(−μ_E·z); рождённый там рентген летит
        /// изотропно и уходит назад через переднюю грань, если пройдёт z/cosθ
        /// без поглощения. Интеграл по глубине и по задней полусфере берётся в
        /// замкнутом виде и зависит ТОЛЬКО от отношения ослаблений
        /// a = μ(рентгена) / μ(кванта):
        ///
        ///     f = ½ · [ 1 − a · ln(1 + 1/a) ]
        ///
        /// Отношение берётся от МАССОВЫХ коэффициентов, поэтому плотность в него
        /// не входит и знать её не нужно.
        ///
        /// Пределы читаются физикой. Сразу над K-краем μ_E огромно, квант
        /// садится в первые доли миллиметра, a → 0 и f → ½: наружу уходит
        /// ровно та половина рентгена, что полетела назад. Вверху шкалы μ_E
        /// мало, a велико, f → 1/(4a) → 0: квант поглощается в сантиметрах от
        /// поверхности, а пробег 28.6-кэВ рентгена иода в CsI ≈ 0.25 мм, и
        /// выйти оттуда он не может. На CsI это даёт f ≈ 0.10 при 78 кэВ и
        /// ≈ 0.011 при 238.6 кэВ — то самое подавление в десять раз, которого
        /// в весе не было.
        ///
        /// ⚠ **Кристалл считается полубесконечным, и вылет назад — весь вылет.**
        /// Там, где вылет вообще заметен, это верно с запасом: при 78 кэВ квант
        /// садится в первый миллиметр, до задней грани ему далеко. Наверху
        /// шкалы тонкий кристалл дал бы ещё и вылет вперёд, но там f и без того
        /// пренебрежимо мала. Толщины у <see cref="FsaSampleSpec"/> нет вовсе,
        /// и заводить её ради поправки к пренебрежимому не стоит.
        ///
        /// ⚠ Оба ослабления берутся у ВЕЩЕСТВА кристалла, а не у элемента
        /// (`S83`, снято 19.08.2026 вместе с `S84`): массовые доли лежат в
        /// геометрии, и смесь считается прямо по ним. Для CsI разница была
        /// невелика (Z 55 и 53 рядом), для NaI лёгкий натрий ослабление
        /// разбавляет, и элементное отношение было смещено.
        /// </summary>
        static double EscapeFraction(double totalAtXray, double totalAtParent)
        {
            if (!(totalAtXray > 0.0) || !(totalAtParent > 0.0))
            {
                return 0.0;
            }

            double a = totalAtXray / totalAtParent;

            // ⚠ При большом a разность 1 − a·ln(1+1/a) — вычитание близких
            // чисел, и на краю двойной точности от неё ничего не осталось бы.
            // Ряд там сходится быстро: a·ln(1+1/a) = 1 − 1/(2a) + 1/(3a²) − …
            double f = a > 1.0e4
                ? 0.5 * (1.0 / (2.0 * a) - 1.0 / (3.0 * a * a))
                : 0.5 * (1.0 - a * Math.Log(1.0 + 1.0 / a));
            return f > 0.0 ? f : 0.0;
        }

        /// <summary>
        /// Выбросить из образа линии слабее доли <paramref name="relative"/> от
        /// его же сильнейшей. Отношение берётся ВНУТРИ образа, а не по всей
        /// библиотеке: амплитуда у образа своя и свободная, так что абсолютный
        /// порог для него не определён вовсе.
        /// </summary>
        static void Prune(FsaComponent component, double relative)
        {
            if (!(relative > 0.0) || component.Lines.Count == 0)
            {
                return;
            }

            double top = 0.0;
            foreach (FsaLine line in component.Lines)
            {
                if (line.Intensity > top)
                {
                    top = line.Intensity;
                }
            }

            double floor = top * relative;
            var kept = new List<FsaLine>(component.Lines.Count);
            foreach (FsaLine line in component.Lines)
            {
                if (line.Intensity >= floor)
                {
                    kept.Add(line);
                }
            }

            component.Lines.Clear();
            component.Lines.AddRange(kept);
        }

        /// <summary>
        /// Пики ОДИНОЧНОГО и ДВОЙНОГО вылета — от линий состава выше порога
        /// рождения пар, тем же правилом, каким их строит путь по подписям
        /// пиков (<see cref="FsaLibrary.EscapeImages"/>).
        ///
        /// ⛔ Заведено 06.09.2026 (`S141`). До этого дня библиотека из баз —
        /// та, которой идёт ВЕСЬ корпус, — строила `Ann-511` и K-вылет
        /// кристалла `Esc-*`, а SE/DE не строила вовсе: на спектре без матрицы
        /// отсчёты пиков вылета выражать было нечем, и NNLS вешал их на
        /// ближайшую линию.
        ///
        /// Правило НЕ переписано, а спрошено: отбор родителей (порог пар, доля
        /// рождения пар в веществе кристалла, три сильнейших по ожидаемой
        /// площади) живёт одним местом на проект.
        ///
        /// ⚠ ОДНО отличие от пути по пикам, и оно намеренное: здесь образ
        /// обязан лечь в ПОЛОСУ БИБЛИОТЕКИ (`S98`), как всякий здешний образ.
        /// Двойной вылет стоит на E − 1022, и у родителя чуть выше порога он
        /// уходит под пол АЦП — а образ, чья единственная линия ниже первого
        /// узла матрицы, не «неполон», он забирает чужую эффективность
        /// (`A49`). У пути по пикам полосы библиотеки нет вовсе, и переносить
        /// сюда её отсутствие было бы не «тем же правилом», а отказом от
        /// здешнего.
        ///
        /// ⛔ Отбор родителей починен 06.09.2026 (`A271`, решение Amber). Именно
        /// ЗДЕСЬ правка `S141` и била: библиотекой из баз идёт весь корпус, а у
        /// спектра без геометрии массовых долей кристалла нет, и отсев по доле
        /// рождения пар молчал целиком — родителем становилась `Bi-214` 1120,
        /// чей образ `SE-1120` садился на 609.0 поверх настоящей `Bi-214`
        /// 609.3. Починка двойная и обе половины нужны:
        /// <see cref="CrystalFractionsOf"/> восстанавливает вещество по
        /// названным элементам кристалла, а
        /// <see cref="FsaLibrary.EscapeParentMarginKev"/> держит запас над
        /// порогом пар там, где вещества не опознать.
        /// </summary>
        static void AddEscapeImages(FsaSampleSpec spec, List<FsaComponent> result, Report report)
        {
            if (result.Count == 0)
            {
                return;
            }

            Dictionary<int, double> fractions = CrystalFractionsOf(spec);
            List<FsaComponent> images = FsaLibrary.EscapeImages(
                result, fractions.Count > 0 ? fractions : null);
            var names = new List<string>();
            int outOfBand = 0;
            foreach (FsaComponent image in images)
            {
                if (image.Lines.Count == 0)
                {
                    continue;
                }

                double energy = image.Lines[0].Energy;
                if (energy < spec.LineFloorKev || energy > spec.MaxEnergyKev)
                {
                    outOfBand++;
                    continue;
                }

                result.Add(image);
                report.Lines += image.Lines.Count;
                names.Add(image.Name);
            }

            if (names.Count > 0)
            {
                report.Notes.Add("вылет от линий состава: " + string.Join(", ", names));
            }

            if (outOfBand > 0)
            {
                report.Notes.Add("образов вылета вне полосы библиотеки "
                                 + outOfBand.ToString(CultureInfo.InvariantCulture));
            }
        }

        /// <summary>
        /// Аннигиляционная линия 511 кэВ ПРИБОРА: рождение пар жёсткими квантами
        /// в защите и обвязке. Нуклиду она не принадлежит, доля зависит от
        /// домика и геометрии — поэтому свободный мешающий образ. Правило то
        /// же, что у <see cref="FsaLibrary"/>: без образа NNLS вешает 511 на
        /// ближайшую линию соседа.
        ///
        /// ⚠ Аннигиляция β⁺-ИЗЛУЧАТЕЛЯ сюда с П124 (`AMBER54`, 22.09.2026) НЕ
        /// относится: она — линия распада и лежит в образе самого нуклида
        /// (<see cref="DecayLines"/>, `2·ΣI(β⁺)`). Здесь прежде стояло «плюс
        /// β⁺-примеси», и это было ровно тем местом, куда у 22NA уходили 70 %
        /// модели. Судьбу свободного образа решает гейт анализатора
        /// (`AMBER7` → `AMBER54`, `FsaAnalyzer.AnnihilationGate`, решение Amber
        /// 22.09.2026 «Линию оставить + починить гейт Ann-511»): он снимается
        /// при ГАММЕ состава у 511 (Tl-208 510.77 — один столбец с 511) и при
        /// β⁺-нуклиде без иных линий, способных его закрепить (F-18); рядом с
        /// аннигиляционной линией нуклида, у которого есть чем закрепиться
        /// (Na-22 1274, Zn-65 1115), он ОСТАЁТСЯ и берёт избыток 511 —
        /// позитроны, аннигилировавшие вне источника, и пары. Решение Amber
        /// 01.09.2026 о СВОБОДНОМ образе от пар этим не отменено — образ
        /// строится как прежде.
        /// </summary>
        static void AddAnnihilation(List<FsaComponent> result, Report report)
        {
            if (result.Count == 0)
            {
                return;
            }

            // ⛔ Не «всегда», а ПО ФИЗИКЕ (решение Amber 01.09.2026, `S110`
            // пункт 2): аннигиляционный квант рождается парой, а пары — только
            // от квантов выше 1022 кэВ. Состав без единой такой линии рождать
            // их нечем, и свободный образ на 511 стал бы там подгонкой.
            //
            // ⚠ Условие СПРАШИВАЕТСЯ у `FsaLibrary`, а не повторяется здесь
            // (`S141`, 06.09.2026): дословная копия того же порога стояла в
            // этом методе, и двум редакциям одного физического правила
            // расходиться незачем.
            if (!FsaLibrary.PairsPossible(result))
            {
                report.Notes.Add("аннигиляционный образ НЕ взят: в составе нет линии выше "
                                 + FsaLibrary.PairThresholdKev.ToString("0", CultureInfo.InvariantCulture)
                                 + " кэВ");
                return;
            }

            var annihilation = new FsaComponent(FsaResult.AnnihilationComponentName,
                                                FsaComponentKind.Nuisance);
            annihilation.Lines.Add(new FsaLine(FsaResult.AnnihilationComponentName, 511.0, 100.0));
            result.Add(annihilation);
            report.Lines++;
        }

        // ------------------------------------------------------------------
        // Мелочи
        // ------------------------------------------------------------------

        /// <summary>
        /// Та же база, но в виде, который понимает ПОИСК ПИКОВ
        /// (<see cref="PeakDetector.DetectPeak"/>).
        ///
        /// Постулат `S56` говорит «своя база ПИКОВ», и подпись — вторая его
        /// половина. Пока поиск подписывает из общего поставочного списка, на
        /// спектре лютеция получаются подписи «Pu-238», «Eu-152», «I-131» —
        /// измерено 18.08.2026 на `ASN16_Lu176`, где так подписаны четыре пика
        /// из девяти. В разложение они теперь не попадают (состав задаёт проба),
        /// но человек читает именно их, и кривая эффективности строится по
        /// площади ПОДПИСАННОГО пика.
        ///
        /// ⚠ Подавать вместе с <c>nuclideSet = null</c>: набор здесь ни при чём,
        /// список уже свой, а <see cref="NuclideSet.HideUnknownPeaks"/> у чужого
        /// набора вычеркнул бы неподписанные пики и увёл счёт.
        /// </summary>
        public static List<NuclideDefinition> AsDefinitions(List<FsaComponent> library)
        {
            var definitions = new List<NuclideDefinition>();
            if (library == null)
            {
                return definitions;
            }

            foreach (FsaComponent component in library)
            {
                foreach (FsaLine line in component.Lines)
                {
                    var definition = new NuclideDefinition();

                    // ⚠ У колонки ряда (равновесие, `S70`) имя компонента —
                    // корень, а линии принадлежат РАЗНЫМ его членам. Пик
                    // подписывается тем, кто эту линию излучил: подписать
                    // 583.19 кэВ «Th-232» вместо «Tl-208» значило бы отнять у
                    // таблицы пиков то единственное, чего связка не отменяет, —
                    // знание, кто в ряду светит. У всех прочих образов нуклид
                    // линии и имя компонента совпадают, и правило для них
                    // ничего не меняет.
                    definition.Name = component.Kind == FsaComponentKind.Chain
                                      && !string.IsNullOrEmpty(line.Nuclide)
                        ? line.Nuclide : component.Name;
                    definition.Energy = line.Energy;
                    definition.Intencity = line.Intensity;
                    definition.Visible = true;
                    definitions.Add(definition);
                }
            }

            return definitions;
        }

        /// <summary>
        /// Элементы вещества, чей K-рентген вообще способен дать линию в этом
        /// спектре: массовая доля не ниже <paramref name="minFraction"/>, а
        /// Kα1 — внутри рабочего диапазона.
        ///
        /// Оба отбора нужны, и оба дешёвые. Без порога по доле в состав пробы
        /// попадает всё, включая примеси; без порога по энергии — кальций
        /// оникса (Kα 3.69 кэВ) и калий KCl (3.31), которых ни один прибор
        /// корпуса не видит.
        ///
        /// ⛔ **Прежнее обоснование нижней границы было неверным и снято
        /// 25.08.2026 (`S98`):** «образ из линий вне окна ФИТА — вырожденный
        /// столбец в NNLS». Окна фита нет — фит идёт с нулевого канала
        /// (<see cref="FsaBandMode"/>), и линия ниже `Min_Range` вырожденной не
        /// была бы. Отбор остаётся нужным по другой причине — прибор таких
        /// энергий не регистрирует, — и границей ему служит
        /// <see cref="FsaSampleSpec.LineFloorKev"/>, а не диапазон поиска пиков.
        ///
        /// ⚠ Вещество из файла спектра приходит ОДНИМ ИМЕНЕМ, без состава:
        /// `GeometryMaterial.Fractions` в XML пуст, а «Cesium iodide» лежит
        /// строкой. Поэтому состав добирается из библиотеки веществ по имени, и
        /// молчаливого отказа здесь быть не должно — вещество, которого в
        /// библиотеке нет, возвращает пустой список, а не «ничего страшного».
        ///
        /// ⛔ **Звать надо ЭТУ перегрузку, со спеком.** Окно она берёт у полосы
        /// БИБЛИОТЕКИ, и разница считается: у кадмиевой пробы Kα 23.17 кэВ
        /// ниже `Min_Range` = 30, и вызов с диапазоном поиска пиков выбрасывал
        /// элемент ЦЕЛИКОМ — вместе с образом, который новый пол разрешает.
        /// </summary>
        public static List<int> HeavyElementsOf(GeometryMaterial material,
                                                double minFraction,
                                                FsaSampleSpec spec)
        {
            return spec == null
                ? new List<int>()
                : HeavyElementsOf(material, minFraction, spec.LineFloorKev, spec.MaxEnergyKev);
        }

        /// <summary>
        /// То же, границами явно. Оставлено ради вызывающих, у которых спека
        /// нет; у кого он есть — перегрузка выше.
        /// </summary>
        public static List<int> HeavyElementsOf(GeometryMaterial material,
                                                double minFraction,
                                                double minKAlphaKev,
                                                double maxKAlphaKev)
        {
            var elements = new List<int>();
            if (material == null)
            {
                return elements;
            }

            Dictionary<int, double> fractions = material.Fractions;
            if (fractions.Count == 0 && !string.IsNullOrEmpty(material.Name))
            {
                GeometryMaterialLibrary.Entry entry = GeometryMaterialLibrary.ByName(material.Name);
                if (entry != null)
                {
                    fractions = GeometryMaterialLibrary.Make(entry, material.Density).Fractions;
                }
            }

            foreach (KeyValuePair<int, double> pair in fractions)
            {
                if (pair.Value < minFraction)
                {
                    continue;
                }

                MaterialDatabase.Fluorescence fluorescence = MaterialDatabase.FluorescenceOf(pair.Key);
                if (fluorescence == null || fluorescence.LineKev == null
                    || fluorescence.LineKev.Length == 0)
                {
                    continue;
                }

                double kAlpha = fluorescence.LineKev[0];
                if (kAlpha >= minKAlphaKev && kAlpha <= maxKAlphaKev)
                {
                    elements.Add(pair.Key);
                }
            }

            elements.Sort();
            return elements;
        }

        /// <summary>
        /// Кристалл — в спецификацию целиком: элементы, их МАССОВЫЕ доли и
        /// короткое имя вещества (`S84`, 19.08.2026).
        ///
        /// Заведено взамен голого <see cref="HeavyElementsOf"/> у кристалла:
        /// образ вылета один на вещество, и соотношение его членов задают доли,
        /// которые лежали тут же и выбрасывались. Прочие вещества (проба,
        /// защита) долей не требуют — у них каждый элемент светит сам за себя и
        /// получает свой образ со своей амплитудой.
        ///
        /// ⚠ У КРИСТАЛЛА окна по Kα нет, и это не оплошность: элемент кристалла
        /// не только светит сам, но и уносит энергию вылетом, а пик вылета стоит
        /// на E − Kα, то есть внутри окна даже когда сама Kα ниже его низа
        /// (измерено 18.08.2026 на ASN16).
        /// </summary>
        public static void DescribeCrystal(FsaSampleSpec spec, GeometryMaterial crystal,
                                           double minFraction, string shortName)
        {
            spec.CrystalElements.AddRange(HeavyElementsOf(crystal, minFraction, 0.0, double.MaxValue));
            if (!string.IsNullOrEmpty(shortName))
            {
                // Активатор в имени вещества не нужен: «CsI:Tl» → «CsI».
                int mark = shortName.IndexOf(':');
                spec.CrystalName = mark > 0 ? shortName.Substring(0, mark) : shortName;
            }

            if (crystal == null)
            {
                return;
            }

            Dictionary<int, double> fractions = crystal.Fractions;
            if (fractions.Count == 0 && !string.IsNullOrEmpty(crystal.Name))
            {
                GeometryMaterialLibrary.Entry entry = GeometryMaterialLibrary.ByName(crystal.Name);
                if (entry != null)
                {
                    fractions = GeometryMaterialLibrary.Make(entry, crystal.Density).Fractions;
                }
            }

            foreach (KeyValuePair<int, double> pair in fractions)
            {
                spec.CrystalFractions[pair.Key] = pair.Value;
            }
        }

        /// <summary>
        /// Массовые доли элементов кристалла для физического отсева. Источников
        /// ТРИ, и они спрашиваются строго по старшинству (`A271` и `A276`,
        /// 06.09.2026):
        ///
        ///   1. ГЕОМЕТРИЯ — доли, уже лежащие в спецификации
        ///      (<see cref="DescribeCrystal"/>). Первичны всегда;
        ///   2. ВЕЩЕСТВО, НАЗВАННОЕ ЧЕЛОВЕКОМ у прибора
        ///      (<see cref="FsaSampleSpec.CrystalMaterialName"/> ←
        ///      <c>DeviceConfigInfo.CrystalMaterialName</c>, `A276`);
        ///   3. ВОССТАНОВЛЕНИЕ по названным элементам кристалла (`A271`).
        ///
        /// ⛔ Порядок держится ЗДЕСЬ И БОЛЬШЕ НИГДЕ. Второй источник заведён
        /// решением Amber ровно потому, что первый есть не у всех: у прибора без
        /// геометрии долей нет, а вещество кристалла человек знает всегда. Что
        /// геометрия при этом ничего не теряет, проверяется замером, а не
        /// рассуждением: у сцены с геометрией результат обязан не измениться ни
        /// в одной ячейке, даже когда поле прибора названо ДРУГИМ веществом
        /// (плечо «первенство геометрии» пробы `CrystalMaterialProbe`).
        ///
        /// Зачем. Доли кладёт <see cref="DescribeCrystal"/>, и кладёт только из
        /// ГЕОМЕТРИИ. У спектра без геометрии их нет — а отбор родителей
        /// образов вылета (<see cref="FsaLibrary.EscapeImages"/>) без них
        /// оставался без единого физического ограничителя и брал родителем
        /// линию в 98 кэВ над порогом рождения пар. При этом сам КРИСТАЛЛ
        /// известен и без геометрии: его элементы называет конфигурация прибора
        /// (в корпусном замере — колонка `crystal` таблицы `materials.csv`), и
        /// они лежат в <see cref="FsaSampleSpec.CrystalElements"/>.
        ///
        /// ⛔ Восстановление — ОДНОЗНАЧНОЕ СОВПАДЕНИЕ, а не догадка. Набор
        /// элементов сверяется с составом каждого вещества-кристалла библиотеки
        /// (<see cref="GeometryMaterialLibrary.MaterialKind.Crystal"/>); доли
        /// берутся только тогда, когда подходит РОВНО ОДНО вещество. Ни одного
        /// или больше одного — возвращается пусто, и дальше судит запас по
        /// энергии (<see cref="FsaLibrary.EscapeParentMarginKev"/>). Равными
        /// доли не считаются: у NaI натрий и иод дают по массе 0.153 и 0.847, и
        /// «поровну» ошиблось бы в долю пар в полтора раза.
        ///
        /// ⚠ Имён веществ в коде при этом не появляется (решение Amber
        /// 01.09.2026): вещество опознаётся СОСТАВОМ, а список составов — данные
        /// библиотеки, которую человек и правит.
        /// </summary>
        public static Dictionary<int, double> CrystalFractionsOf(FsaSampleSpec spec)
        {
            var fractions = new Dictionary<int, double>();
            if (spec == null)
            {
                return fractions;
            }

            if (spec.CrystalFractions.Count > 0)
            {
                foreach (KeyValuePair<int, double> pair in spec.CrystalFractions)
                {
                    fractions[pair.Key] = pair.Value;
                }

                return fractions;
            }

            // Второй источник — вещество, названное человеком у прибора
            // (`A276`). Спрашивается ПОСЛЕ геометрии и ДО восстановления по
            // элементам: названное прямо старше выведенного, но обоих старше
            // измеренная сцена.
            Dictionary<int, double> named = FractionsOfMaterial(spec.CrystalMaterialName);
            if (named.Count > 0)
            {
                return named;
            }

            if (spec.CrystalElements.Count == 0)
            {
                return fractions;
            }

            // Тот же порог доли, с каким элементы кристалла и отбирались
            // (`DescribeCrystal`, 1 %): ниже него элемент — примесь, и вещество
            // по нему не опознаётся.
            const double MinFraction = 0.01;
            var want = new HashSet<int>(spec.CrystalElements);
            Dictionary<int, double> found = null;
            foreach (GeometryMaterialLibrary.Entry entry in
                     GeometryMaterialLibrary.Of(GeometryMaterialLibrary.MaterialKind.Crystal))
            {
                GeometryMaterial material = GeometryMaterialLibrary.Make(entry, entry.Density);
                if (material == null)
                {
                    continue;
                }

                var have = new HashSet<int>();
                foreach (KeyValuePair<int, double> pair in material.Fractions)
                {
                    if (pair.Value >= MinFraction)
                    {
                        have.Add(pair.Key);
                    }
                }

                if (!have.SetEquals(want))
                {
                    continue;
                }

                if (found != null)
                {
                    return new Dictionary<int, double>();   // двое — значит не опознано
                }

                found = new Dictionary<int, double>(material.Fractions);
            }

            return found ?? fractions;
        }

        /// <summary>
        /// Массовые доли вещества библиотеки ПО ЕГО ИМЕНИ (`A276`). Пусто —
        /// имя не названо, такого имени в библиотеке нет или состав у него
        /// пуст; ни одно из трёх не отказ, а «источника нет», и дальше судит
        /// следующий источник или запас по энергии
        /// (<see cref="FsaLibrary.EscapeParentMarginKev"/>).
        ///
        /// ⛔ ИМЁН ВЕЩЕСТВ В КОДЕ НЕ ПОЯВЛЯЕТСЯ (решение Amber 01.09.2026):
        /// здесь только ОБРАЩЕНИЕ по имени, которое пришло из конфигурации
        /// прибора, а сам список веществ и их составы — данные библиотеки,
        /// которые правит человек (<c>GeometryMaterialStore</c>). Ни одного
        /// разбора имени, ни одной таблицы «CsI → цезий и иод».
        ///
        /// ⚠ Вид вещества (<c>MaterialKind.Crystal</c>) здесь НЕ требуется, и
        /// это решение. Вид — свойство СПИСКА ВЫБОРА, а не физики: он говорит,
        /// в каком месте сцены вещество предлагать. Прибор, у которого вещество
        /// названо, а человек потом сменил ему вид в редакторе, обязан считать
        /// по-прежнему, а не онеметь молча — состав от вида не зависит.
        /// Список же на форме прибора берёт именно кристаллы, и выбрать оттуда
        /// свинец нельзя.
        ///
        /// ⚠ Плотность спрашивается У САМОЙ ЗАПИСИ (<c>entry.Density</c>): доли
        /// МАССОВЫЕ и от плотности не зависят вовсе, а ноль вместо неё увёл бы
        /// <see cref="GeometryMaterialLibrary.Make"/> в ту же ветку окольным
        /// путём. Потребитель долей — доля рождения пар, отношение, и плотность
        /// в него не входит (`S122`).
        /// </summary>
        public static Dictionary<int, double> FractionsOfMaterial(string materialName)
        {
            var fractions = new Dictionary<int, double>();
            if (string.IsNullOrEmpty(materialName))
            {
                return fractions;
            }

            GeometryMaterialLibrary.Entry entry = GeometryMaterialLibrary.ByName(materialName);
            if (entry == null)
            {
                return fractions;
            }

            GeometryMaterial material = GeometryMaterialLibrary.Make(entry, entry.Density);
            if (material == null)
            {
                return fractions;
            }

            foreach (KeyValuePair<int, double> pair in material.Fractions)
            {
                fractions[pair.Key] = pair.Value;
            }

            return fractions;
        }

        /// <summary>
        /// Возбуждённое состояние: у `nucid` есть метка состояния строчными
        /// буквами («234PAm1», «108AGm», «105PDe»).
        ///
        /// ⚠ Признак — РЕГИСТР, а не буква. Символ элемента записан заглавными
        /// целиком, поэтому «241AM» (америций) изомером не является, а «108AGm»
        /// является. На этом уже поскользнулись 18.08.2026 — см.
        /// <see cref="PrettyName"/>.
        /// </summary>
        public static bool IsIsomer(string nucid)
        {
            int mass;
            string symbol, state;
            return CascadeAtomicData.SplitNucid(nucid, out mass, out symbol, out state)
                   && state.Length > 0;
        }

        /// <summary>
        /// Долю ветвления нуклида — в накопитель, БОЛЬШУЮ из встреченных.
        /// Вместе с долей запоминается и ХОЗЯИН — тот корень, от которого эта
        /// доля посчитана: по нему связываются члены при
        /// <see cref="FsaSampleSpec.Equilibrium"/>.
        ///
        /// ⚠ Тот же нуклид приходит из двух рядов сразу (Ra-226 объявлен сам по
        /// себе и лежит внутри U-238; Th-228 — сам по себе и внутри Th-232), и
        /// доли у него разные. Побеждает бо́льшая, и хозяином становится её
        /// корень: объявленный САМ нуклид держит долю 1.0, то есть отбирает
        /// себя и своих потомков у объемлющего ряда — ровно то, чего человек и
        /// хотел, объявив его отдельно. При равенстве побеждает ПЕРВЫЙ, поэтому
        /// объявленный ряд не отбирается вездесущим (<see cref="RoomChains"/>).
        /// </summary>
        static void Remember(Dictionary<string, double> branch, Dictionary<string, string> owner,
                             string nucid, double value, string root)
        {
            double have;
            if (branch.TryGetValue(nucid, out have) && have >= value)
            {
                return;
            }

            branch[nucid] = value;
            if (owner != null)
            {
                owner[nucid] = root;
            }
        }

        /// <summary>
        /// Хозяин нуклида: корень ряда, от которого посчитана его доля. Не
        /// записан — сам себе хозяин (так выходит у одиночных нуклидов и у
        /// читателей, которым хозяин не нужен).
        /// </summary>
        /// <summary>
        /// (`AMBER274`, Ф14) ПОЛ ФОТОННОГО ВЫХОДА ЧИСТОГО БЕТА-ИЗЛУЧАТЕЛЯ, % на собственный
        /// распад (Σ линий `G` и `X` нуклида, <see cref="FsaComponent.TotalYieldPercent"/>).
        /// Колонка, у которой выход каждого излучающего члена ниже пола, а бета есть, —
        /// строка ПО СПЛОШНОМУ СПЕКТРУ: её следовые линии амплитуду не держат, держит бета.
        ///
        /// ⛔ Своего соглашения о «заметном выходе» здесь не заводится: 0.01 % на распад —
        /// ПОЛ ПОЛНОТЫ САМОЙ БАЗЫ, решение Amber 01.10.2026 по добору слабых гамм
        /// (`AMBER151`, дословно: «≥ 0.01 % после ускорения сумматора»; `database/scheme.md`
        /// §2) — линий слабее база не добирала, и следовая линия ниже пола линией базы не
        /// является. Мерено по `nucdb` 01.11.2026: у чистых излучателей Σ фотонов —
        /// Sr-90, Bi-210, P-32, C-14, H-3 — 0; Y-90 0.0095 %, Sr-89 0.0096 %, Pm-147 0.006 %,
        /// Pu-241 0.004 %, Tc-99 0.0015 % (следовые гамма- и K-линии); ближайшие сверху — уже
        /// излучатели со своей гаммой: Cl-36 0.15 %, Y-91 0.26 %, Tl-207 0.27 %, Kr-85 0.44 %.
        /// </summary>
        public const double PureBetaPhotonFloorPercent = 0.01;

        /// <summary>(`AMBER274`, Ф14) Есть ли у нуклида сплошная бета (ветвь с выходом, не линия конверсии).</summary>
        public static bool HasContinuousBeta(string nucid)
        {
            return HasContinuousBeta(FsaBetaLibrary.Branches(nucid));
        }

        static bool HasContinuousBeta(List<FsaBeta> betas)
        {
            foreach (FsaBeta beta in betas)
            {
                if (!beta.IsLine && beta.Intensity > 0.0)
                {
                    return true;
                }
            }

            return false;
        }

        /// <summary>
        /// (`AMBER274`, Ф14) СТРОКИ ПО СПЛОШНОМУ СПЕКТРУ. Решение Amber 30.10.2026
        /// вопросником, дословно: «Строка без линий по набору (Рекомендую)» — чистый
        /// бета-излучатель входит в состав только объявленным составом (набором или
        /// пробой), строка с одним бета-образом, пределы как у прочих, пометка «по
        /// сплошному спектру».
        ///
        /// Кто идёт в такую строку: (а) член с бетой без линий, которому не нашлось
        /// хозяина (`Р3`): Sr-90 объявлен сам по себе, Bi-210 без Pb-210; (б) члены колонки,
        /// чей фотонный выход ниже <see cref="PureBetaPhotonFloorPercent"/>, — их следовые
        /// линии снимаются (Y-90: 2186 кэВ 1.4·10⁻⁶ %, K-линии 0.009 %; Po-210 в ряду
        /// Bi-210: 803 кэВ 0.001 %), колонка строится заново. Члены без сплошной беты
        /// (Po-210 — альфа) в строку не идут: им нечем в ней быть.
        ///
        /// Группировка — как у колонок с линиями: при равновесии члены одного ряда — одна
        /// колонка корня (ряд Sr-90: Sr-90 и Y-90 — колонка «Sr-90» вида ряда), без него —
        /// по колонке на член (происхождение — корень, если бета-членов в ряду больше
        /// одного, `A169`). Вес беты члена — его равновесное отношение к корню, как у линий
        /// (<see cref="AddBetas"/>). Выход <see cref="FsaComponent.TotalYieldPercent"/> у
        /// строки — NaN: правило `S69` («априори не может показать себя гаммой») её не
        /// сворачивает — она показывает себя бетой.
        ///
        /// ⛔ ТОЛЬКО РЯД БЕЗ НАСТОЯЩЕГО ИЗЛУЧАТЕЛЯ. И (а), и (б) берутся, лишь когда ни у одного
        /// члена того же ряда (корень — <see cref="OwnerOf"/>) фотонный выход не достигает пола:
        /// «Bi-210 без Pb-210» — слово решения. В ряду Ra-226 при выключенном равновесии Bi-210
        /// тоже остаётся без хозяина, но ряд излучает (Pb-210 46.5 кэВ, Bi-214…), и Bi-210 там не
        /// чистый излучатель пробы, а член ряда, у которого своей колонки нет, — заметка, как до
        /// 01.11.2026, без строки (витрина: радоновый фильтр, ряд Ra-226 без равновесия, —
        /// строка «сняты: Bi-210» на каждом разборе была бы шумом).
        ///
        /// Состав без таких членов не меняется ни на бит: колонки (б) у прочих составов нет
        /// по построению (выход не ниже пола либо беты нет), а (а) до 01.11.2026 давало
        /// только заметку «бета X без линий — колонки нет».
        /// </summary>
        static void BetaOnlyColumns(FsaSampleSpec spec, Dictionary<string, double> branch,
                                    Dictionary<string, string> owner, Dictionary<string, string> componentOf,
                                    Dictionary<string, string> hostOf, List<KeyValuePair<string, double>> orphans,
                                    Dictionary<string, FsaComponent> byName, List<string> order, Report report)
        {
            // Ряды, где есть настоящий излучатель: член с фотонным выходом не ниже пола.
            var emitting = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (KeyValuePair<string, double> member in branch)
            {
                double yield = 0.0;
                foreach (double[] line in DecayLines(member.Key, report))
                {
                    yield += line[1];
                }

                if (yield >= PureBetaPhotonFloorPercent)
                {
                    emitting.Add(OwnerOf(owner, member.Key));
                }
            }

            var converted = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string name in order)
            {
                FsaComponent c = byName[name];
                if (c.Kind == FsaComponentKind.Nuisance || !(c.TotalYieldPercent < PureBetaPhotonFloorPercent)
                    || !HasContinuousBeta(c.Betas))
                {
                    continue;
                }

                bool inEmitting = false;
                foreach (KeyValuePair<string, string> placed in componentOf)
                {
                    if (string.Equals(placed.Value, name, StringComparison.OrdinalIgnoreCase)
                        && emitting.Contains(OwnerOf(owner, placed.Key)))
                    {
                        inEmitting = true;
                    }
                }

                if (!inEmitting)
                {
                    converted.Add(name);
                }
            }

            var orphanSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (KeyValuePair<string, double> member in orphans)
            {
                if (emitting.Contains(OwnerOf(owner, member.Key)))
                {
                    // член излучающего ряда без своей колонки — заметка, как до 01.11.2026
                    report.Notes.Add("бета " + PrettyName(member.Key) + " без линий — колонки нет, образа беты нет");
                    continue;
                }

                orphanSet.Add(member.Key);
            }

            if (converted.Count == 0 && orphanSet.Count == 0)
            {
                return;
            }

            var members = new List<KeyValuePair<string, double>>();
            foreach (KeyValuePair<string, double> member in branch)
            {
                string placed;
                bool inConverted = (componentOf.TryGetValue(member.Key, out placed) && converted.Contains(placed))
                                   || (hostOf.TryGetValue(member.Key, out placed) && converted.Contains(placed));
                if ((inConverted || orphanSet.Contains(member.Key)) && HasContinuousBeta(member.Key))
                {
                    members.Add(member);
                }
            }

            foreach (string name in converted)
            {
                byName.Remove(name);
                order.Remove(name);
                report.Notes.Add("следовые линии колонки " + name + " ниже пола "
                                 + PureBetaPhotonFloorPercent.ToString("0.###", CultureInfo.InvariantCulture)
                                 + " % — колонка по сплошному спектру");
            }

            var stale = new List<string>();
            foreach (KeyValuePair<string, string> placed in componentOf)
            {
                if (converted.Contains(placed.Value))
                {
                    stale.Add(placed.Key);
                }
            }

            foreach (string key in stale)
            {
                componentOf.Remove(key);
            }

            // Ключ строки: корень ряда при равновесии, сам член без него; бета-членов на корень.
            var keys = new List<string>();
            var groups = new Dictionary<string, List<KeyValuePair<string, double>>>(StringComparer.OrdinalIgnoreCase);
            var perRoot = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (KeyValuePair<string, double> member in members)
            {
                string root = OwnerOf(owner, member.Key);
                int had;
                perRoot[root] = perRoot.TryGetValue(root, out had) ? had + 1 : 1;
                string key = spec.Equilibrium ? root : member.Key;
                List<KeyValuePair<string, double>> group;
                if (!groups.TryGetValue(key, out group))
                {
                    group = new List<KeyValuePair<string, double>>();
                    groups[key] = group;
                    keys.Add(key);
                }

                group.Add(member);
            }

            foreach (string key in keys)
            {
                List<KeyValuePair<string, double>> group = groups[key];
                bool chain = group.Count > 1;
                string name = PrettyName(chain ? key : group[0].Key);
                bool fresh = !byName.ContainsKey(name);
                FsaComponent component = Take(byName, order, name, chain ? FsaComponentKind.Chain : FsaComponentKind.Single);
                if (fresh)
                {
                    component.TotalYieldPercent = double.NaN;
                }

                var names = new List<string>();
                foreach (KeyValuePair<string, double> member in group)
                {
                    AddBetas(component, PrettyName(member.Key), member.Key, member.Value);
                    componentOf[member.Key] = name;
                    names.Add(PrettyName(member.Key));
                    string root = OwnerOf(owner, member.Key);
                    if (component.DecayChainRoot == null && GroupCount(perRoot, root) > 1)
                    {
                        component.DecayChainRoot = PrettyName(root);
                    }
                }

                // Колонка с линиями того же имени (столкновение имён) остаётся колонкой с
                // линиями: бета ложится в неё, как у хозяина `Р3`.
                component.BetaOnly = component.Lines.Count == 0;
                report.Notes.Add((component.BetaOnly ? "по сплошному спектру: " : "бета без линий в колонку с линиями: ")
                                 + name + " (бета " + string.Join(", ", names.ToArray()) + ")");
            }
        }

        static string OwnerOf(Dictionary<string, string> owner, string nucid)
        {
            string root;
            return owner != null && owner.TryGetValue(nucid, out root) ? root : nucid;
        }

        static int GroupCount(Dictionary<string, int> groupSize, string root)
        {
            int count;
            return groupSize.TryGetValue(root, out count) ? count : 1;
        }

        static FsaComponent Take(Dictionary<string, FsaComponent> byName, List<string> order,
                                 string name, FsaComponentKind kind)
        {
            FsaComponent component;
            if (!byName.TryGetValue(name, out component))
            {
                component = new FsaComponent(name, kind);
                byName[name] = component;
                order.Add(name);
            }

            return component;
        }

        /// <summary>
        /// (`AMBER274`, Э1) Бета-ветви нуклида <paramref name="nucid"/> — в компонент под
        /// именем <paramref name="self"/>, выход × <paramref name="weight"/>. Читает их
        /// только образ по матрице с разделом строк электрона; линии конверсии (`Ф4`) — тем же
        /// списком.
        /// </summary>
        static void AddBetas(FsaComponent component, string self, string nucid, double weight)
        {
            if (component == null || !(weight > 0.0))
            {
                return;
            }

            foreach (FsaBeta beta in FsaBetaLibrary.Branches(nucid))
            {
                component.Betas.Add(beta.Scaled(self, weight));
            }
        }

        /// <summary>
        /// Линия в образ с защитой от дубля. Порог 0.05 кэВ — тот же, что в
        /// <see cref="FsaLibrary"/>: реальных раздельных линий ближе не бывает,
        /// а запись той же линии с иной точностью удвоила бы её вес и уронила
        /// амплитуду образа вдвое.
        /// </summary>
        /// <summary>
        /// Линию — в образ, если такой у ЭТОГО ЖЕ нуклида ещё нет.
        ///
        /// ⚠ Совпадение проверяется по паре «нуклид + энергия», а не по одной
        /// энергии, и это существенно с приходом связки равновесия (`S70`): в
        /// колонке ряда лежат линии НЕСКОЛЬКИХ нуклидов, и две близкие линии
        /// разных членов — это две настоящие линии, обе в спектре есть. Отсев
        /// по одной энергии выбросил бы вторую молча. У всех прочих читателей
        /// (<see cref="AddFluorescence"/>, <see cref="AddEscape"/>, состав без
        /// равновесия) нуклид у линий образа один и тот же, поэтому для них
        /// правило не изменилось ни на волос.
        ///
        /// Отсев нужен затем, зачем и заводился: одна линия бывает записана в
        /// базе дважды — своей строкой и строкой «в цепочке», либо копией с
        /// округлённой энергией, — и в образе она удваивает вес. Порог 0.05 кэВ:
        /// раздельных линий ближе не бывает.
        /// </summary>
        static void AddLine(FsaComponent component, string nuclide, double energy, double intensity,
                            double annihilationIntensity = 0.0)
        {
            foreach (FsaLine line in component.Lines)
            {
                if (Math.Abs(line.Energy - energy) < 0.05
                    && string.Equals(line.Nuclide, nuclide, StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }
            }

            component.Lines.Add(new FsaLine(nuclide, energy, intensity, annihilationIntensity));
        }

        /// <summary>
        /// `nucid` → подпись: «212PB» → «Pb-212», «241AM» → «Am-241»,
        /// «234PAm1» → «Pa-234m», «108AGm» → «Ag-108m».
        ///
        /// ⚠ Хвост изомера пишется БЕЗ номера состояния, и это не небрежность:
        /// именно так изомер назван и в мерке корпуса (`score.py`,
        /// `CHAIN_MEMBERS`: «Pa-234m»), а имя компонента — ключ, по которому
        /// мерка сводит найденное с истиной. `chains.pretty` в питоне на этом
        /// имени спотыкается вовсе и отдаёт «234PAm1» как есть (регистр `m` не
        /// подходит под её шаблон) — здесь это учтено.
        /// </summary>
        public static string PrettyName(string nucid)
        {
            int mass;
            string symbol, state;
            if (!CascadeAtomicData.SplitNucid(nucid, out mass, out symbol, out state))
            {
                return nucid ?? "";
            }

            // Номер состояния в подпись НЕ идёт: «234PAm1» -> «Pa-234m». Так
            // изомер назван и в мерке корпуса (`score.py`, `CHAIN_MEMBERS`), а
            // имя компонента — ключ, по которому мерка сводит найденное с
            // истиной.
            string letters = "";
            foreach (char c in state)
            {
                if (!char.IsDigit(c))
                {
                    letters += char.ToLowerInvariant(c);
                }
            }

            // (`AMBER78`, П149 24.09.2026) Режется только номер ПЕРВОГО изомера:
            // «m1» и «m» — одно состояние в двух соглашениях базы, и
            // <see cref="NucidOf"/> сводит «Pa-234m» обратно к «234PAm1». Номер
            // второго и выше вырезать нельзя: «Rh-100m» из «100RHm2» обратным
            // разбором попадал бы в ДРУГОЕ состояние («100RHm»), молча.
            string number = state.Substring(letters.Length);
            if (letters.Length > 0 && number.Length > 0 && number != "1"
                && string.Equals(state, letters + number, StringComparison.OrdinalIgnoreCase))
            {
                letters += number;
            }

            return char.ToUpperInvariant(symbol[0]) + symbol.Substring(1).ToLowerInvariant()
                   + "-" + mass.ToString(CultureInfo.InvariantCulture) + letters;
        }
        /// <summary>
        /// Обратно: имя нуклида → `nucid` базы; пусто — разобрать не вышло.
        ///
        /// ⛔ (`AMBER78`, П149 24.09.2026) ВСЕ НАПИСАНИЯ, КОТОРЫЕ ПРОЕКТ ПИШЕТ
        /// САМ, а не одно «Cs-137». Набор нуклидов, из которого путь FSA по
        /// меткам (<see cref="FsaLibrary.BuildFromLabels"/>) берёт имена
        /// компонентов, пишет `NucBase` тремя форматами — «137CS, 234PAm1»,
        /// «Cs137, Pa234m1» (УМОЛЧАНИЕ формы) и «Cs-137, Pa-234m1», — запасной
        /// набор приложения пишет «K40», «Cs137», корпусная подпись
        /// (<see cref="PrettyName"/>) — «Pa-234m» без номера изомера. До П149
        /// здесь понималось одно написание через дефис, и остальные молча
        /// давали пусто: у имени «Na22» из `NucBase` с настройками по умолчанию
        /// линия 511 в образ не добавлялась (`AMBER63` не срабатывал), замер
        /// `FsaNucidNameProbe` по 708 β⁺-родителям базы — до базы доходили
        /// 0 / 0 / 570 имён трёх форматов и ни одного из 138 изомеров.
        ///
        /// Разбор — две формы: СИМВОЛ-МАССА-МЕТКА («Cs-137», «Cs137»,
        /// «Pa-234m1») и МАССА-СИМВОЛ-МЕТКА («137CS», «234PAm1», «241Am»).
        /// Где кончается символ и начинается метка изомера во второй форме,
        /// по буквам не сказать («241Am» — америций, «38Km» — изомер калия), и
        /// угадывать это правилом НЕ нужно: в базе нет двух `nucid`, которые
        /// различались бы только регистром букв (замер 24.09.2026: 4427
        /// `nuclides.nucid`, совпадений в верхнем регистре ноль), поэтому имя
        /// сводится к «массе + буквам в верхнем регистре» и ищется в базе.
        /// Метка «m» без номера и «m1» — один и тот же первый изомер в двух
        /// соглашениях (в базе 392 `nucid` с «m» и 222 с «m1»; корпусная
        /// подпись номер режет): не нашлось одно — берётся другое.
        ///
        /// Базы нет или нуклида в ней нет — ответ прежний: строка «масса +
        /// символ заглавными + метка строчными», как её давал разбор через
        /// дефис («SE-2615» → «2615SE»; такого `nucid` нет, и линий у него нет).
        /// Имён нуклидов здесь нет — только разбор и справочник базы.
        /// </summary>
        public static string NucidOf(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return "";
            }

            string mass, letters, state;
            bool symbolDashMass;
            if (!SplitName(name.Trim(), out mass, out letters, out state, out symbolDashMass))
            {
                return "";
            }

            Dictionary<string, string> known = KnownNucids();
            string key = mass + (letters + state).ToUpperInvariant();
            string found;
            if (known.TryGetValue(key, out found))
            {
                return found;
            }

            // Первый изомер в двух соглашениях: «m» и «m1».
            string upper = state.ToUpperInvariant();
            if (upper == "M" && known.TryGetValue(key + "1", out found))
            {
                return found;
            }

            if (upper == "M1" && known.TryGetValue(key.Substring(0, key.Length - 1), out found))
            {
                return found;
            }

            // Прежняя строка — только там, где её давал прежний разбор («символ-
            // масса» через дефис) или где спросить базу нечем. Новые написания
            // без базы нуклидом не становятся: «Sum 1022» остаётся ничем, а не
            // выдуманным `nucid` «1022SUM».
            return symbolDashMass || known.Count == 0
                ? mass + letters.ToUpperInvariant() + state.ToLowerInvariant()
                : "";
        }

        /// <summary>
        /// Разбор имени нуклида на массу, буквы символа и метку состояния
        /// (`AMBER78`). Форма «символ, масса, метка» однозначна: масса стоит
        /// между символом и меткой. Форма «масса, буквы» метку от символа не
        /// отделяет — тогда `letters` несёт всё, `state` пуст, и разводит их
        /// справочник базы (<see cref="NucidOf"/>). Разделитель между символом
        /// и массой — дефис, пробел или ничего.
        /// </summary>
        static bool SplitName(string text, out string mass, out string letters, out string state,
                              out bool symbolDashMass)
        {
            mass = letters = state = "";
            symbolDashMass = false;
            int i = 0;
            while (i < text.Length && IsLatin(text[i]))
            {
                i++;
            }

            if (i > 0)
            {
                // Символ, затем масса, затем метка.
                letters = text.Substring(0, i);
                if (i < text.Length && (text[i] == '-' || text[i] == ' '))
                {
                    symbolDashMass = text[i] == '-';
                    i++;
                }

                int start = i;
                while (i < text.Length && text[i] >= '0' && text[i] <= '9')
                {
                    i++;
                }

                if (i == start)
                {
                    return false;
                }

                mass = text.Substring(start, i - start);
                state = text.Substring(i);
                return IsState(state);
            }

            // Масса, затем буквы (и, быть может, номер изомера).
            while (i < text.Length && text[i] >= '0' && text[i] <= '9')
            {
                i++;
            }

            if (i == 0 || i >= text.Length)
            {
                return false;
            }

            mass = text.Substring(0, i);
            if (text[i] == '-' || text[i] == ' ')
            {
                i++;
            }

            int lettersStart = i;
            while (i < text.Length && IsLatin(text[i]))
            {
                i++;
            }

            if (i == lettersStart)
            {
                return false;
            }

            letters = text.Substring(lettersStart, i - lettersStart);
            while (i < text.Length && text[i] >= '0' && text[i] <= '9')
            {
                i++;
            }

            // Номер изомера держится при буквах: «234PAm1» — буквы «PAm», номер «1».
            letters += text.Substring(lettersStart + letters.Length, i - lettersStart - letters.Length);
            return i == text.Length;
        }

        /// <summary>Метка состояния: пусто либо буквы, за которыми цифры («m», «m1», «m2»).</summary>
        static bool IsState(string state)
        {
            int i = 0;
            while (i < state.Length && IsLatin(state[i]))
            {
                i++;
            }

            if (state.Length > 0 && i == 0)
            {
                return false;
            }

            while (i < state.Length && state[i] >= '0' && state[i] <= '9')
            {
                i++;
            }

            return i == state.Length;
        }

        static bool IsLatin(char c)
        {
            return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
        }

        /// <summary>
        /// Справочник `nucid` базы: ключ — «масса + буквы в верхнем регистре»,
        /// значение — `nucid` как он записан (`AMBER78`). Читается один раз
        /// (`nuclides`, только чтение); отказ базы — пустой справочник, и
        /// <see cref="NucidOf"/> отвечает прежней строкой.
        /// </summary>
        static Dictionary<string, string> KnownNucids()
        {
            lock (Gate)
            {
                if (knownNucids != null)
                {
                    return knownNucids;
                }

                var map = new Dictionary<string, string>(StringComparer.Ordinal);
                try
                {
                    using (SqliteConnection connection = OpenRead(NuclideDatabasePath()))
                    using (SqliteCommand command = connection.CreateCommand())
                    {
                        command.CommandText = "select nucid from nuclides where nucid is not null";
                        using (SqliteDataReader reader = command.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                string nucid = reader.GetString(0).Trim();
                                string upper = nucid.ToUpperInvariant();
                                if (nucid.Length > 0 && !map.ContainsKey(upper))
                                {
                                    map[upper] = nucid;
                                }
                            }
                        }
                    }
                }
                catch (Exception error)
                {
                    // Базы нет — разбор остаётся строковым, как до `AMBER78`.
                    // ⛔ (`AMBER199`) Но справочник НЕ запоминается: следующий
                    // вызов спросит базу снова.
                    FsaDatabaseFailures.Note("nucdb.sqlite", "nuclides", error);
                    return new Dictionary<string, string>(StringComparer.Ordinal);
                }

                knownNucids = map;
                return map;
            }
        }

        static Dictionary<string, string> knownNucids;

        static bool TryNumber(SqliteDataReader reader, int column, out double value)
        {
            value = 0.0;
            if (reader.IsDBNull(column))
            {
                return false;
            }

            // Колонки базы разнородны по типу: `perc` лежит текстом, `energy_num`
            // — числом. Читать текстовую как double бросает, числовую как
            // строку — тоже, поэтому пробуются оба.
            try
            {
                value = reader.GetDouble(column);
                return true;
            }
            catch (InvalidCastException)
            {
            }

            string text = reader.GetValue(column) as string;
            return text != null
                   && double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out value);
        }

        static SqliteConnection OpenRead(string path)
        {
            // (`AMBER201`) Строка подключения — построителем, не склейкой:
            // `;` в имени каталога программы разрезал строку, и база не открывалась.
            SqliteConnection connection = new SqliteConnection(
                EfficiencyMaker.MaterialDatabase.ReadOnlyConnection(path, true));
            connection.Open();
            return connection;
        }

        static string NuclideDatabasePath()
        {
            return Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "nucdb.sqlite");
        }
    }

    /// <summary>
    /// ⛔ (`AMBER199`, 05.10.2026) ОТКАЗЫ ЧТЕНИЯ БАЗ ДАННЫХ РАЗБОРА — одним
    /// местом и с читателем.
    ///
    /// Что чинит. Читатели `nucdb`/`schemedb`/`matdb` ядра FSA
    /// (<see cref="FsaSampleLibrary"/>, <see cref="FsaCascadeSummer"/>,
    /// <see cref="CascadeAtomicData"/>, <see cref="AngularCorrelation"/>,
    /// <see cref="KSeriesRule"/>) клали ответ ОТКАЗА в статический кэш как
    /// обычный ответ: база, занятая в миг первого разбора (внешний редактор,
    /// синхронизация, антивирус), оставляла нуклид без линий или без поправки
    /// на совпадения ДО ПЕРЕЗАПУСКА программы. А признаки отказа
    /// (<c>FsaCascadeSummer.Failure</c>, записки отчёта сборки) вне классов не
    /// читал никто — на экране ни слова.
    ///
    /// Правило теперь двойное:
    ///   1. отказ НЕ кэшируется: читатель, заметив отказ (свой или вложенного
    ///      вызова — по счётчику <see cref="ThreadCount"/> до и после), не кладёт
    ///      ответ в кэш, и следующий разбор пробует базу снова;
    ///   2. отказ ДОХОДИТ ДО ЧЕЛОВЕКА: <see cref="Note"/> кладёт строку в
    ///      собиратель потока, который открывает сеанс разбора
    ///      (<see cref="Begin"/>/<see cref="End"/>), а сеанс отдаёт её в
    ///      <see cref="FsaResult.DatabaseFailures"/> — окно отчёта печатает
    ///      строку-происшествие; без результата — приписка к причине отказа.
    ///
    /// Собиратель — на ПОТОК: разбор целиком идёт в одной фоновой задаче
    /// (параллельных циклов в ядре нет), а разборы разных документов идут в
    /// разных задачах и чужих отказов друг другу не подмешивают. Вне сеанса
    /// (пробы, корпус) собирателя нет — отказ уходит в журнал трассировки и в
    /// счётчик <see cref="ProcessCount"/>, кэш не пишется так же.
    ///
    /// Текст строки — без переводимых слов: имя файла базы, ключ запроса
    /// (`nucid`, Z/A) и сообщение платформы. Подпись строки окна переведена в
    /// обе культуры (`FSAReportDatabaseFailedRow`).
    /// </summary>
    public static class FsaDatabaseFailures
    {
        [ThreadStatic]
        static int threadCount;

        [ThreadStatic]
        static List<string> collected;

        static int processCount;

        /// <summary>Потолок строк одного разбора: дальше — только счёт.</summary>
        const int MaxCollected = 32;

        /// <summary>Отказов на этом потоке за всё время (счётчик «был ли отказ внутри»).</summary>
        public static int ThreadCount
        {
            get { return threadCount; }
        }

        /// <summary>Отказов во всём процессе — для проб.</summary>
        public static int ProcessCount
        {
            get { return System.Threading.Volatile.Read(ref processCount); }
        }

        /// <summary>
        /// Отказ чтения базы. <paramref name="database"/> — имя файла
        /// (`nucdb.sqlite`), <paramref name="key"/> — что читалось.
        /// </summary>
        public static void Note(string database, string key, Exception error)
        {
            threadCount++;
            System.Threading.Interlocked.Increment(ref processCount);
            string text = database + " (" + (key ?? string.Empty) + "): "
                          + (error != null ? error.Message : string.Empty);
            System.Diagnostics.Trace.WriteLine("FSA: отказ чтения базы — " + text);
            List<string> tap = capture;
            if (tap != null && tap.Count < MaxCollected && !tap.Contains(text))
            {
                tap.Add(text);
            }

            List<string> sink = collected;
            if (sink != null && sink.Count < MaxCollected && !sink.Contains(text))
            {
                sink.Add(text);
            }
        }

        /// <summary>Открыть собиратель этого потока (вложенность не поддерживается: прежний сбрасывается).</summary>
        public static void Begin()
        {
            collected = new List<string>();
        }

        [ThreadStatic]
        static List<string> capture;

        /// <summary>
        /// (`AMBER326`, a326p) Начать запись отказов этого потока рядом с собирателем — на время построения элемента
        /// общего кэша разбора (поправка суммирователя, гистограмма поглощения): строки потом хранятся при элементе и
        /// отдаются каждому заходу разбора, который элемент взял (<see cref="Replay"/>). Возвращает прежнюю запись
        /// (вложенность: гистограмма строится поверх поправок) — её и отдают в <see cref="EndCapture"/>.
        /// </summary>
        public static List<string> BeginCapture()
        {
            List<string> previous = capture;
            capture = new List<string>();
            return previous;
        }

        /// <summary>Кончить запись: записанное возвращается и дописывается в прежнюю (внешнюю) запись.</summary>
        public static List<string> EndCapture(List<string> previous)
        {
            List<string> taken = capture ?? new List<string>();
            capture = previous;
            if (previous != null)
            {
                foreach (string text in taken)
                {
                    if (previous.Count < MaxCollected && !previous.Contains(text))
                    {
                        previous.Add(text);
                    }
                }
            }

            return taken;
        }

        /// <summary>
        /// (`AMBER326`, a326p) Отказы, записанные при построении элемента общего кэша, — в собиратель и в запись ЭТОГО
        /// потока, как если бы он строил элемент сам. Счётчики отказов не трогаются: чтения базы здесь не было.
        /// </summary>
        public static void Replay(List<string> texts)
        {
            if (texts == null || texts.Count == 0)
            {
                return;
            }

            List<string> tap = capture;
            List<string> sink = collected;
            foreach (string text in texts)
            {
                if (tap != null && tap.Count < MaxCollected && !tap.Contains(text))
                {
                    tap.Add(text);
                }

                if (sink != null && sink.Count < MaxCollected && !sink.Contains(text))
                {
                    sink.Add(text);
                }
            }
        }

        /// <summary>(`AMBER326`, a326p) Открыт ли собиратель на этом потоке — чтобы заход разбора на другом потоке завёл свой.</summary>
        public static bool Collecting
        {
            get { return collected != null; }
        }

        /// <summary>
        /// (`AMBER326`, a326p) Отказы, собранные заходом разбора на ДРУГОМ потоке (заходы ядра идут параллельно на
        /// копиях анализатора), — в собиратель и счётчик этого потока, тем же порядком и с тем же потолком.
        /// </summary>
        public static void Absorb(List<string> texts)
        {
            if (texts == null || texts.Count == 0)
            {
                return;
            }

            threadCount += texts.Count;
            List<string> sink = collected;
            if (sink == null)
            {
                return;
            }

            foreach (string text in texts)
            {
                if (sink.Count < MaxCollected && !sink.Contains(text))
                {
                    sink.Add(text);
                }
            }
        }

        /// <summary>Закрыть собиратель и забрать собранное; не было отказов — пустой список.</summary>
        public static List<string> End()
        {
            List<string> sink = collected ?? new List<string>();
            collected = null;
            return sink;
        }
    }
    /// <summary>
    /// (`AMBER274`, Э1 29.10.2026) ЭЛЕКТРОНЫ РАСПАДА: БЕТА-ВЕТВИ И ЛИНИИ КОНВЕРСИИ — для
    /// образа «бета пробы» (слой «Бета» матрицы отклика). Решения Amber вопросником,
    /// дословно: 29.10.2026 «Код + BetaShape для кристалла (Рекомендую)»; 30.10.2026 —
    /// «Таблицы BetaShape/LNHB в nucdb (Рекомендую)» (`Ф1`/`Ф2`: формы неуникальных
    /// запретов и опытные факторы формы — таблицей `nucdb.beta_shapes`) и «Включить в Э1
    /// (Рекомендую)» (`Ф4`: электроны внутренней конверсии тем же слоем).
    ///
    /// Данные — только чтение: ветви `B-`/`B+` из `nucdb.decay_radiations` (граница,
    /// выход, средняя энергия; у `B+` поле `endpoint` — энергия ЗАХВАТА на уровень,
    /// граница позитрона — она минус 2mc²), заряд и Jπ родителя — `nucdb.nuclides`, Q и
    /// Jπ уровня дочернего ядра — `schemedb.ensdf_datasets`/`ensdf_levels` (уровень ветви
    /// — по энергии Q + E_уровня родителя − E₀ у β⁻ и Q_EC + E_родителя − E_захвата у β⁺;
    /// энергия изомерного уровня родителя — `schemedb.g4_level` по периоду, `Ф7`), форма
    /// — `nucdb.beta_shapes`/`beta_shape_points`, если ветвь там есть. Линии конверсии —
    /// из гамма-линий распада (`decay_radiations`, `G`): α — `schemedb.ensdf_gammas.conv_coef`
    /// (нет — `g4_gamma.icc_total`), доли K/L/M/внешних — `schemedb.g4_gamma`, энергии
    /// связи оболочек дочернего атома — `matdb.eadl_binding`.
    ///
    /// Форма ветви без таблицы: N(T) ∝ p·W·q²·F₀(Z, W)·Sₙ(p, q) — W, p, q в единицах mₑc
    /// (q = W₀ − W); F₀ — релятивистская функция Ферми точечного ядра R = 1.2·A^⅓ фм; Sₙ —
    /// фактор уникального n-го запрета Σₖ p²ᵏq²⁽ⁿ⁻ᵏ⁾/((2k+1)!(2n−2k+1)!), λₖ = 1 (кулоновские
    /// λₖ — ключом <see cref="FsaBetaLibrary.CoulombLambda"/>, `a274s`; умолчание ВКЛ с rev55 13.11.2026). Характер
    /// перехода — по ΔJ и ЧЕТНОСТИ (`Ф1`): разрешённый; первый неуникальный (ΔJ ≤ 1 со
    /// сменой чётности) — разрешённой формой (ξ-приближение); уникальный n-й (ΔJ = n + 1,
    /// Δπ = (−1)ⁿ) — Sₙ; неуникальный k-й (ΔJ = k, иная чётность) — формой уникального
    /// (k − 1)-го (ξ-приближение, так же считает BetaShape без опытного фактора). Где
    /// ξ-приближение заведомо не работает (Cs-137 на основное, Bi-210), форма — из таблицы.
    /// Экранирования, конечного размера ядра в L₀, радиационных поправок нет — сверка
    /// средней с LNHB печатается пробой `BetaSectionProbeA274 --shapes`.
    ///
    /// ⛔ Имён нуклидов в коде нет (правило «имён нуклидов в коде FSA быть не должно»):
    /// всё, что отличает нуклид, — из базы.
    /// </summary>
    public static class FsaBetaLibrary
    {
        const double ElectronMassKev = 510.99895;
        const double FineStructure = 1.0 / 137.035999084;
        const double ComptonFm = 386.15926796;   // ħ/(mₑc), фм

        /// <summary>(`Ф4`) Ниже этого выхода линия конверсии в образ не идёт, % на распад.</summary>
        public const double MinConversionPercent = 1.0e-3;

        /// <summary>(`Ф4`) Ниже этой энергии линия конверсии не берётся: ни одна обвязка её не пропустит, кэВ.</summary>
        public const double MinConversionKev = 20.0;

        static readonly object Gate = new object();
        static readonly Dictionary<string, List<FsaBeta>> Cache =
            new Dictionary<string, List<FsaBeta>>(StringComparer.OrdinalIgnoreCase);
        static readonly Dictionary<string, string> NoteCache =
            new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

        /// <summary>
        /// Электроны распада нуклида: бета-ветви (`B-`, `B+`) и линии конверсии
        /// (<see cref="FsaBeta.IsLine"/>), выход — % на распад ЭТОГО нуклида. Ветвь без
        /// границы в базе пропускается (форму строить не по чему) и называется в
        /// <see cref="Note"/>. Отказ чтения базы — запись в <see cref="FsaDatabaseFailures"/>
        /// С ИМЕНЕМ ТОЙ БАЗЫ, что отказала (`Р4`), и список без того, что не прочлось;
        /// ⛔ отказ НЕ кэшируется (`Р4`): следующий разбор читает базу заново, как и
        /// прочие читатели (`FsaDatabaseFailures` — «кэш не пишется»).
        /// </summary>
        public static List<FsaBeta> Branches(string nucid)
        {
            if (string.IsNullOrEmpty(nucid))
            {
                return new List<FsaBeta>();
            }

            lock (Gate)
            {
                List<FsaBeta> cached;
                if (Cache.TryGetValue(nucid, out cached))
                {
                    return cached;
                }
            }

            var note = new StringBuilder();
            bool failed = false;
            List<FsaBeta> list;
            var check = new BranchCheck();
            try
            {
                list = Read(nucid, note, ref failed, check);
            }
            catch (Exception error)
            {
                FsaDatabaseFailures.Note("nucdb.sqlite", nucid, error);
                list = new List<FsaBeta>();
                note.Append("отказ чтения nucdb: ").Append(error.Message);
                failed = true;
            }

            lock (Gate)
            {
                NoteCache[nucid] = note.ToString();
                if (!failed)
                {
                    Cache[nucid] = list;
                    CheckCache[nucid] = check;
                }
            }

            return list;
        }

        /// <summary>
        /// (`AMBER274`, К3 критика кода 30.10.2026) ЗАПАС СУММЫ ВЕТВЕЙ, %: Σ выходов β⁻ и β⁺
        /// нуклида выше 100 % на больше, чем этот запас, — либо дубли двух оценок, либо
        /// поставка противоречит сама себе, и об этом говорит отчёт. Запас — округление
        /// выходов поставки: у нуклидов без пределов и дублей сумма доходит до 101 %
        /// (`233PA` 101.7 %, `146PR` 101.46 %); 101 % — та же мерка, какой критик насчитал
        /// 179 нуклидов из 1617 с ветвями.
        /// </summary>
        public const double BranchSumTolerancePercent = 1.0;

        /// <summary>
        /// (`AMBER274`, К3) ДУБЛЬ ДВУХ ОЦЕНОК — пара строк одного вида (β⁻ или β⁺) с границей в
        /// допуске max(<see cref="DuplicateEndpointKev"/>, <see cref="DuplicateEndpointShare"/>·E₀)
        /// и выходами в <see cref="DuplicateIntensityRatio"/> раза. Ищется ТОЛЬКО у нуклида,
        /// чья сумма ветвей (без пределов `LT`) выше 100 % + <see cref="BranchSumTolerancePercent"/>:
        /// две близкие ветви на соседние уровни бывают и честно (`234PA` 472 кэВ: уровни
        /// 1722.9 и 1723.45 кэВ, 12.4 и 33 % по ENSDF), но у них выходы разные, а сумма в норме.
        /// Мерено на всей базе: `225RA` 316/356 кэВ (68.8 + 31.2 %) и 320/356 кэВ (69.5 + 30.5 %)
        /// — два набора одного распада, граница первой ветви расходится на 4 кэВ (Q наборов
        /// разные), отсюда допуск 2 %; у `20NA` — три пары β⁺ (3613/3612, 6464/6465,
        /// 12252/12253 кэВ). Из пары берётся строка, стоящая раньше в поставке (`dr_pk`).
        /// </summary>
        public const double DuplicateEndpointKev = 5.0;

        /// <summary>(`AMBER274`, К3) Доля границы в допуске дубля (см. <see cref="DuplicateEndpointKev"/>).</summary>
        public const double DuplicateEndpointShare = 0.02;

        /// <summary>(`AMBER274`, К3) Во сколько раз могут разниться выходы дублей (см. <see cref="DuplicateEndpointKev"/>).</summary>
        public const double DuplicateIntensityRatio = 1.25;

        /// <summary>
        /// (`AMBER274`, К3) Проверка суммы ветвей нуклида: что отброшено при чтении и какая
        /// сумма осталась. Заполняется <see cref="Branches"/> (кэш вместе с ветвями).
        /// </summary>
        public sealed class BranchCheck
        {
            /// <summary>Σ выходов β⁻ и β⁺ после отсева пределов и дублей, % на распад.</summary>
            public double SumPercent;

            /// <summary>Строк-пределов (`LT`, `LE` в `intensity_unc`), отброшенных, и их Σ, %.</summary>
            public int LimitRows;

            public double LimitPercent;

            /// <summary>Строк-дублей второй оценки, отброшенных, и их Σ, %.</summary>
            public int DuplicateRows;

            public double DuplicatePercent;

            /// <summary>Сумма и после отсева выше 100 % + <see cref="BranchSumTolerancePercent"/>.</summary>
            public bool Excess
            {
                get { return this.SumPercent > 100.0 + BranchSumTolerancePercent; }
            }
        }

        static readonly Dictionary<string, BranchCheck> CheckCache =
            new Dictionary<string, BranchCheck>(StringComparer.OrdinalIgnoreCase);

        /// <summary>(`AMBER274`, К3) Проверка суммы ветвей нуклида; null — база не прочлась.</summary>
        public static BranchCheck Check(string nucid)
        {
            Branches(nucid);
            lock (Gate)
            {
                BranchCheck check;
                return CheckCache.TryGetValue(nucid ?? "", out check) ? check : null;
            }
        }

        /// <summary>
        /// (`AMBER274`, К3) Отсев строк ветвей ДО построения форм: (1) строки-ВЕРХНИЕ ПРЕДЕЛЫ
        /// (`intensity_unc` = `LT` или `LE`) — выход у них не значение, а граница сверху, и
        /// сложенные как значения они дают у `234PA` 24.6 % лишних (Σ 129.47 → 104.87 %);
        /// (2) при сумме выше 100 % + <see cref="BranchSumTolerancePercent"/> — дубли второй
        /// оценки (<see cref="DuplicateEndpointKev"/>). Порядок прочих строк не меняется.
        /// </summary>
        static void Screen(List<object[]> rows, StringBuilder note, BranchCheck check)
        {
            for (int i = rows.Count - 1; i >= 0; i--)
            {
                string unc = ((string)rows[i][5] ?? "").Trim().ToUpperInvariant();
                // (`f8diag`) правило одно на проект — `DecayParentRule.IsUpperLimit`
                if (DecayParentRule.IsUpperLimit(unc))
                {
                    check.LimitRows++;
                    check.LimitPercent += (double)rows[i][3];
                    note.Append((string)rows[i][0] == "B+" ? "β⁺ " : "β⁻ ").Append((string)rows[i][2])
                        .Append(" кэВ — выход ").Append(((double)rows[i][3]).ToString("G4", CultureInfo.InvariantCulture))
                        .Append(" % ").Append(unc).Append(" (верхний предел) отброшен; ");
                    rows.RemoveAt(i);
                }
            }

            double sum = 0.0;
            foreach (object[] row in rows)
            {
                sum += (double)row[3];
            }

            if (sum > 100.0 + BranchSumTolerancePercent)
            {
                // Пары — по порядку поставки: строка с бо́льшим `dr_pk` ищет себе пару среди
                // взятых раньше; у каждой взятой — не больше одного дубля.
                var order = new List<int>();
                for (int i = 0; i < rows.Count; i++)
                {
                    order.Add(i);
                }

                order.Sort((a, b) =>
                {
                    int c = ((long)rows[a][6]).CompareTo((long)rows[b][6]);
                    return c != 0 ? c : a.CompareTo(b);
                });
                var kept = new List<int>();
                var paired = new HashSet<int>();
                var drop = new HashSet<int>();
                double logRatio = Math.Log(DuplicateIntensityRatio);
                foreach (int i in order)
                {
                    double e = Number((string)rows[i][2]);
                    double y = (double)rows[i][3];
                    int partner = -1;
                    foreach (int k in kept)
                    {
                        if (paired.Contains(k) || !string.Equals((string)rows[k][0], (string)rows[i][0], StringComparison.Ordinal))
                        {
                            continue;
                        }

                        double ek = Number((string)rows[k][2]);
                        double yk = (double)rows[k][3];
                        if (e > 0.0 && ek > 0.0 && y > 0.0 && yk > 0.0
                            && Math.Abs(e - ek) <= Math.Max(DuplicateEndpointKev, DuplicateEndpointShare * Math.Max(e, ek))
                            && Math.Abs(Math.Log(y / yk)) <= logRatio)
                        {
                            partner = k;
                            break;
                        }
                    }

                    if (partner >= 0)
                    {
                        paired.Add(partner);
                        drop.Add(i);
                        check.DuplicateRows++;
                        check.DuplicatePercent += y;
                        note.Append((string)rows[i][0] == "B+" ? "β⁺ " : "β⁻ ").Append((string)rows[i][2])
                            .Append(" кэВ ").Append(y.ToString("G4", CultureInfo.InvariantCulture))
                            .Append(" % — дубль ветви ").Append((string)rows[partner][2]).Append(" кэВ ")
                            .Append(((double)rows[partner][3]).ToString("G4", CultureInfo.InvariantCulture))
                            .Append(" % второй оценки, не сложен; ");
                    }
                    else
                    {
                        kept.Add(i);
                    }
                }

                for (int i = rows.Count - 1; i >= 0; i--)
                {
                    if (drop.Contains(i))
                    {
                        sum -= (double)rows[i][3];
                        rows.RemoveAt(i);
                    }
                }
            }

            check.SumPercent = sum;
            if (check.Excess)
            {
                note.Append("Σ ветвей β ").Append(sum.ToString("F2", CultureInfo.InvariantCulture))
                    .Append(" % > 100 % — поставка противоречит себе; ");
            }
        }

        /// <summary>Как разобраны электроны нуклида: уровень, Jπ, характер перехода, форма, конверсия, пропуски.</summary>
        public static string Note(string nucid)
        {
            Branches(nucid);
            lock (Gate)
            {
                string note;
                return NoteCache.TryGetValue(nucid, out note) ? note : "";
            }
        }

        /// <summary>(`Р4`, проба) Сбросить кэш — чтобы проба отказа базы видела повторное чтение.</summary>
        public static void ResetCache()
        {
            lock (Gate)
            {
                Cache.Clear();
                NoteCache.Clear();
                CheckCache.Clear();
                LevelCache.Clear();
                SchemeCache.Clear();
            }

            lock (WeightGate)
            {
                WeightCache.Clear();
            }
        }

        /// <summary>Путь базы рядом с приложением (тот же, что у прочих читателей).</summary>
        static string DatabasePath(string file)
        {
            return Path.Combine(AppDomain.CurrentDomain.BaseDirectory, file);
        }

        sealed class TableShape
        {
            public int Id;
            public string TypeA;
            public double EndpointKev;
            public string Transition;
            public string Kind;
            public double[] Factor;
            public string Source;
            public double[] T;
            public double[] Density;
        }

        static List<FsaBeta> Read(string nucid, StringBuilder note, ref bool failed, BranchCheck check)
        {
            var list = new List<FsaBeta>();
            int massNumber = 0, i0 = 0;
            while (i0 < nucid.Length && char.IsDigit(nucid[i0]))
            {
                massNumber = massNumber * 10 + (nucid[i0] - '0');
                i0++;
            }

            // Родитель в `schemedb` — без метки изомера (`234PAm1` → `234PA`).
            string scheme = nucid;
            int m = nucid.IndexOf('m', i0);
            bool isomer = m > 0;
            if (isomer)
            {
                scheme = nucid.Substring(0, m);
            }

            int parentZ = -1;
            string parentJp = null;
            double parentHalfLife = double.NaN;
            var rows = new List<object[]>();
            var gammas = new List<double[]>();
            var shapes = new List<TableShape>();
            using (SqliteConnection connection = OpenRead(DatabasePath("nucdb.sqlite")))
            {
                using (SqliteCommand command = connection.CreateCommand())
                {
                    command.CommandText = "select z, jp, half_life_sec from nuclides where nucid = $n order by l_seqno desc limit 1";
                    command.Parameters.AddWithValue("$n", nucid);
                    using (SqliteDataReader r = command.ExecuteReader())
                    {
                        if (r.Read())
                        {
                            parentZ = r.IsDBNull(0) ? -1 : Convert.ToInt32(r.GetValue(0), CultureInfo.InvariantCulture);
                            parentJp = r.IsDBNull(1) ? null : r.GetString(1);
                            double hl;
                            if (!r.IsDBNull(2) && double.TryParse(Convert.ToString(r.GetValue(2), CultureInfo.InvariantCulture),
                                                                  NumberStyles.Float, CultureInfo.InvariantCulture, out hl))
                            {
                                parentHalfLife = hl;
                            }
                        }
                    }
                }

                using (SqliteCommand command = connection.CreateCommand())
                {
                    // (`AMBER274`, К3) `intensity_unc` — пометка верхнего предела (`LT`), `dr_pk` —
                    // порядок строк поставки для дублей; порядок самих строк — прежний (без
                    // `order by`): по нему складываются ветви образа, и у нуклидов без пределов и
                    // дублей образ обязан остаться побитово тем же.
                    command.CommandText =
                        "select type_a, energy_num, endpoint, intensity_num, parent_l_seqno, dec_type, intensity_unc, dr_pk"
                        + " from decay_radiations"
                        + " where parent_nucid = $n and type_a in ('B-', 'B+', 'G') and intensity_num > 0"
                        + DecayParentRule.LevelClause;
                    command.Parameters.AddWithValue("$n", nucid);
                    using (SqliteDataReader r = command.ExecuteReader())
                    {
                        while (r.Read())
                        {
                            string type = r.IsDBNull(0) ? "" : r.GetString(0);
                            if (type == "G")
                            {
                                // (`AMBER274`, `f8diag`) Гамма-предел — не выход, и линий
                                // конверсии от неё нет (`DecayParentRule.IsUpperLimit`).
                                if (!r.IsDBNull(6) && DecayParentRule.IsUpperLimit(
                                        Convert.ToString(r.GetValue(6), CultureInfo.InvariantCulture)))
                                {
                                    continue;
                                }

                                int decType;
                                gammas.Add(new[]
                                {
                                    r.IsDBNull(1) ? double.NaN : r.GetDouble(1),
                                    r.IsDBNull(3) ? 0.0 : r.GetDouble(3),
                                    !r.IsDBNull(5) && int.TryParse(Convert.ToString(r.GetValue(5), CultureInfo.InvariantCulture),
                                                                   NumberStyles.Integer, CultureInfo.InvariantCulture, out decType)
                                        ? decType : -1,
                                });
                                continue;
                            }

                            rows.Add(new object[]
                            {
                                type,
                                r.IsDBNull(1) ? double.NaN : r.GetDouble(1),
                                r.IsDBNull(2) ? "" : r.GetString(2),
                                r.IsDBNull(3) ? 0.0 : r.GetDouble(3),
                                r.IsDBNull(4) ? 0 : Convert.ToInt32(r.GetValue(4), CultureInfo.InvariantCulture),
                                r.IsDBNull(6) ? "" : Convert.ToString(r.GetValue(6), CultureInfo.InvariantCulture),
                                r.IsDBNull(7) ? 0L : Convert.ToInt64(r.GetValue(7), CultureInfo.InvariantCulture),
                            });
                        }
                    }
                }

                // (`Ф1`/`Ф2`) Формы ветвей таблицей. У базы до 30.10.2026 таблиц нет — это не
                // отказ, а «форм таблицей нет»: ветви строятся кодом.
                if (rows.Count > 0 && HasTable(connection, "beta_shapes") && HasTable(connection, "beta_shape_points"))
                {
                    ReadShapes(connection, nucid, shapes);
                }
            }

            // (`AMBER274`, К3) Пределы `LT` и дубли второй оценки — до форм и схемы.
            Screen(rows, note, check);

            if (parentZ < 0)
            {
                if (rows.Count > 0 || gammas.Count > 0)
                {
                    note.Append("нет заряда родителя в nuclides; ");
                }

                return list;
            }

            // Схема: датасеты β⁻ и захвата/β⁺ родителя — с тем же уровнем родителя,
            // ближайшие по периоду (у 90Y два датасета β⁻ на основном уровне).
            DataSet minus = null, plus = null;
            var levels = new Dictionary<int, List<KeyValuePair<double, string>>>();
            var alphas = new List<double[]>();
            var g4 = new List<double[]>();
            double parentLevelKev = 0.0;
            bool schemeOk = false;
            string schemePath = DatabasePath("schemedb.sqlite");
            if (!File.Exists(schemePath))
            {
                // (`Р4`) Нет базы — отказ, видимый человеку, а не тихие разрешённые формы.
                FsaDatabaseFailures.Note("schemedb.sqlite", nucid, new FileNotFoundException("schemedb.sqlite not found", schemePath));
                note.Append("нет schemedb.sqlite — формы разрешённые, конверсии нет; ");
                failed = true;
            }
            else
            {
                try
                {
                    ReadScheme(schemePath, scheme, parentZ, massNumber, isomer, parentHalfLife, rows, gammas,
                               out minus, out plus, levels, alphas, g4, out parentLevelKev, note);
                    schemeOk = true;
                }
                catch (Exception error)
                {
                    // (`Р4`) Отказ `schemedb` — под СВОИМ именем, не `nucdb`.
                    FsaDatabaseFailures.Note("schemedb.sqlite", nucid, error);
                    note.Append("отказ чтения schemedb: ").Append(error.Message).Append("; ");
                    failed = true;
                    minus = plus = null;
                    levels.Clear();
                    alphas.Clear();
                    g4.Clear();
                }
            }

            double parentJ;
            int parentParity;
            bool parentKnown = TryJ(parentJp, out parentJ);
            bool parentParityKnown = TryParity(parentJp, out parentParity);
            foreach (object[] row in rows)
            {
                bool positron = (string)row[0] == "B+";
                double field = Number((string)row[2]);
                if (!(field > 0.0))
                {
                    note.Append(positron ? "β⁺" : "β⁻").Append(" без границы (выход ")
                        .Append(((double)row[3]).ToString("G4", CultureInfo.InvariantCulture)).Append(" %) пропущена; ");
                    continue;
                }

                double endpoint = positron ? field - 2.0 * ElectronMassKev : field;
                if (!(endpoint > 0.5))
                {
                    note.Append("β⁺ ниже порога пропущена; ");
                    continue;
                }

                DataSet set = positron ? plus : minus;
                int order = 0;
                string transition = "allowed";
                string levelText = "?";
                // (`AMBER274` Ф8, `f8cyl`) Уровень, который питает ветвь, — для строки «событие
                // целиком» (`EventSpec`): по балансу Q датасета, уточнённый уровнем схемы.
                double levelForEvent = set != null
                    ? (positron ? set.Q + parentLevelKev - field : set.Q + parentLevelKev - endpoint)
                    : double.NaN;
                if (set != null && parentKnown)
                {
                    // (`Ф7`) Энергия уровня родителя входит в баланс: у изомера Q датасета
                    // — от основного состояния.
                    double levelKev = positron ? set.Q + parentLevelKev - field : set.Q + parentLevelKev - endpoint;
                    double tolerance = Math.Max(5.0, 0.01 * set.Q);
                    double found = levelKev;
                    string jpi = ByEndpoint(levels[set.Id], endpoint, Math.Max(2.0, 0.01 * endpoint));
                    if (jpi == null)
                    {
                        jpi = levelKev < -tolerance
                            ? null      // (`Ф7`) отрицательный уровень — отказ, а не «ближайший»
                            : NearestLevel(levels[set.Id], Math.Max(0.0, levelKev), tolerance, out found);
                    }

                    double daughterJ;
                    if (jpi != null && TryJ(jpi, out daughterJ))
                    {
                        int daughterParity;
                        bool parityKnown = parentParityKnown & TryParity(jpi, out daughterParity);
                        bool parityChange = parityKnown && daughterParity != parentParity;
                        Classify((int)Math.Round(Math.Abs(daughterJ - parentJ)), parityKnown, parityChange,
                                 out order, out transition);
                        levelText = found.ToString("F1", CultureInfo.InvariantCulture) + " " + jpi;
                        levelForEvent = found;
                    }
                    else
                    {
                        levelText = "уровень " + levelKev.ToString("F1", CultureInfo.InvariantCulture)
                                    + (levelKev < -tolerance ? " < 0 — отвергнут" : " не найден");
                    }
                }

                int daughterZ = positron ? parentZ - 1 : parentZ + 1;
                var beta = new FsaBeta(nucid, endpoint, (double)row[3], daughterZ, massNumber, order, positron, (double)row[1])
                    .WithTransition(transition);
                TableShape table = MatchShape(shapes, positron ? "B+" : "B-", field);
                if (table != null)
                {
                    beta = beta.WithShape(table.Transition, table.Id, table.Source, table.T, table.Density,
                                          table.T != null && table.T.Length > 0 ? table.T[table.T.Length - 1] : 0.0,
                                          table.Factor);
                }

                list.Add(beta);
                lock (Gate)
                {
                    LevelCache[LevelKey(nucid, endpoint)] = levelForEvent;
                }

                note.Append(positron ? "β⁺ " : "β⁻ ").Append(endpoint.ToString("F1", CultureInfo.InvariantCulture))
                    .Append(" кэВ ").Append(((double)row[3]).ToString("G4", CultureInfo.InvariantCulture)).Append(" % → ")
                    .Append(levelText).Append(" (").Append(parentJp ?? "?").Append("), ").Append(beta.Transition)
                    .Append(", форма ")
                    .Append(table != null
                        ? "таблицей #" + table.Id.ToString(CultureInfo.InvariantCulture) + " (" + table.Kind + ")"
                        : order == 0 ? "разрешённая" : "уник. " + order.ToString(CultureInfo.InvariantCulture))
                    .Append("; ");
            }

            if (schemeOk && gammas.Count > 0)
            {
                try
                {
                    AddConversion(nucid, parentZ, massNumber, gammas, alphas, g4, list, note);
                }
                catch (Exception error)
                {
                    FsaDatabaseFailures.Note("matdb.sqlite", nucid, error);
                    note.Append("отказ чтения matdb (энергии связи): ").Append(error.Message).Append("; ");
                    failed = true;
                }
            }

            // (`AMBER274`, К3) Сумма ветвей — при каждой ветви: отчёт называет нуклид, чья бета
            // легла в образ с суммой выше 100 %.
            for (int i = 0; i < list.Count; i++)
            {
                list[i] = list[i].WithBranchSum(check.SumPercent);
            }

            return list;
        }

        static bool HasTable(SqliteConnection connection, string table)
        {
            using (SqliteCommand command = connection.CreateCommand())
            {
                command.CommandText = "select count(*) from sqlite_master where type = 'table' and name = $t";
                command.Parameters.AddWithValue("$t", table);
                return Convert.ToInt64(command.ExecuteScalar(), CultureInfo.InvariantCulture) > 0;
            }
        }

        static void ReadShapes(SqliteConnection connection, string nucid, List<TableShape> shapes)
        {
            using (SqliteCommand command = connection.CreateCommand())
            {
                command.CommandText = "select id, type_a, endpoint_kev, transition, kind, a0, a1, a2, a3, source"
                                      + " from beta_shapes where parent_nucid = $n order by id";
                command.Parameters.AddWithValue("$n", nucid);
                using (SqliteDataReader r = command.ExecuteReader())
                {
                    while (r.Read())
                    {
                        var shape = new TableShape
                        {
                            Id = Convert.ToInt32(r.GetValue(0), CultureInfo.InvariantCulture),
                            TypeA = r.GetString(1),
                            EndpointKev = r.GetDouble(2),
                            Transition = r.IsDBNull(3) ? "" : r.GetString(3),
                            Kind = r.IsDBNull(4) ? "" : r.GetString(4),
                            Source = r.IsDBNull(9) ? "" : r.GetString(9),
                        };
                        if (string.Equals(shape.Kind, "factor", StringComparison.OrdinalIgnoreCase))
                        {
                            shape.Factor = new[]
                            {
                                r.IsDBNull(5) ? 0.0 : r.GetDouble(5), r.IsDBNull(6) ? 0.0 : r.GetDouble(6),
                                r.IsDBNull(7) ? 0.0 : r.GetDouble(7), r.IsDBNull(8) ? 0.0 : r.GetDouble(8),
                            };
                        }

                        shapes.Add(shape);
                    }
                }
            }

            foreach (TableShape shape in shapes)
            {
                if (!string.Equals(shape.Kind, "points", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                var t = new List<double>();
                var d = new List<double>();
                using (SqliteCommand command = connection.CreateCommand())
                {
                    command.CommandText = "select t_kev, density from beta_shape_points where shape_id = $s order by t_kev";
                    command.Parameters.AddWithValue("$s", shape.Id);
                    using (SqliteDataReader r = command.ExecuteReader())
                    {
                        while (r.Read())
                        {
                            t.Add(r.GetDouble(0));
                            d.Add(r.GetDouble(1));
                        }
                    }
                }

                if (t.Count >= 2)
                {
                    shape.T = t.ToArray();
                    shape.Density = d.ToArray();
                }
            }
        }

        /// <summary>Строка таблицы форм для ветви базы: тот же вид и граница в допуске max(2 кэВ, 0.5 %).</summary>
        static TableShape MatchShape(List<TableShape> shapes, string typeA, double field)
        {
            TableShape best = null;
            double distance = Math.Max(2.0, 0.005 * field);
            foreach (TableShape shape in shapes)
            {
                if (!string.Equals(shape.TypeA, typeA, StringComparison.Ordinal)
                    || (shape.T == null && shape.Factor == null))
                {
                    continue;
                }

                double d = Math.Abs(shape.EndpointKev - field);
                if (d <= distance)
                {
                    distance = d;
                    best = shape;
                }
            }

            return best;
        }

        static void ReadScheme(string schemePath, string scheme, int parentZ, int massNumber, bool isomer,
                               double parentHalfLife, List<object[]> rows, List<double[]> gammas,
                               out DataSet minus, out DataSet plus,
                               Dictionary<int, List<KeyValuePair<double, string>>> levels,
                               List<double[]> alphas, List<double[]> g4, out double parentLevelKev,
                               StringBuilder note)
        {
            minus = plus = null;
            parentLevelKev = 0.0;
            using (SqliteConnection connection = OpenRead(schemePath))
            {
                var sets = new List<DataSet>();
                using (SqliteCommand command = connection.CreateCommand())
                {
                    command.CommandText = "select id, dsid, q_value_kev, parent_l_seqno, parent_hl_sec from ensdf_datasets"
                                          + " where upper(parent_nucid) = upper($p) and q_value_kev is not null";
                    command.Parameters.AddWithValue("$p", scheme);
                    using (SqliteDataReader r = command.ExecuteReader())
                    {
                        while (r.Read())
                        {
                            sets.Add(new DataSet
                            {
                                Id = Convert.ToInt32(r.GetValue(0), CultureInfo.InvariantCulture),
                                Dsid = r.IsDBNull(1) ? "" : r.GetString(1),
                                Q = Convert.ToDouble(r.GetValue(2), CultureInfo.InvariantCulture),
                                Level = r.IsDBNull(3) ? 0 : Convert.ToInt32(r.GetValue(3), CultureInfo.InvariantCulture),
                                HalfLife = r.IsDBNull(4) ? double.NaN : Convert.ToDouble(r.GetValue(4), CultureInfo.InvariantCulture),
                            });
                        }
                    }
                }

                // (`Ф7`) Энергия изомерного уровня родителя — уровень ядра (Z, A) с тем же
                // периодом (в полтора раза), `g4_level`. У основного состояния — ноль.
                if (isomer && parentHalfLife > 0.0)
                {
                    using (SqliteCommand command = connection.CreateCommand())
                    {
                        command.CommandText = "select energy_ev, half_life_sec from g4_level where z = $z and a = $a"
                                              + " and seq > 0 and half_life_sec > 0";
                        command.Parameters.AddWithValue("$z", parentZ);
                        command.Parameters.AddWithValue("$a", massNumber);
                        double best = Math.Log(1.5);
                        using (SqliteDataReader r = command.ExecuteReader())
                        {
                            while (r.Read())
                            {
                                double hl = Convert.ToDouble(r.GetValue(1), CultureInfo.InvariantCulture);
                                double d = Math.Abs(Math.Log(hl / parentHalfLife));
                                if (d < best)
                                {
                                    best = d;
                                    parentLevelKev = Convert.ToDouble(r.GetValue(0), CultureInfo.InvariantCulture) / 1000.0;
                                }
                            }
                        }
                    }

                    note.Append("уровень родителя ").Append(parentLevelKev.ToString("F2", CultureInfo.InvariantCulture))
                        .Append(" кэВ; ");
                }

                if (rows.Count > 0)
                {
                    int level = (int)rows[0][4];
                    minus = Pick(sets, " B- DECAY", null, level, parentHalfLife);
                    plus = Pick(sets, " EC DECAY", " B+ DECAY", level, parentHalfLife);
                    foreach (DataSet set in new[] { minus, plus })
                    {
                        if (set == null || levels.ContainsKey(set.Id))
                        {
                            continue;
                        }

                        levels[set.Id] = ReadLevels(connection, set.Id);
                    }
                }

                if (gammas.Count == 0)
                {
                    return;
                }

                // (`Ф4`) α конверсии по гамма-линиям датасетов родителя.
                using (SqliteCommand command = connection.CreateCommand())
                {
                    command.CommandText = "select g.energy_kev, g.conv_coef from ensdf_gammas g join ensdf_datasets d"
                                          + " on d.id = g.dataset_id where upper(d.parent_nucid) = upper($p)"
                                          + " and g.conv_coef > 0 and g.energy_kev is not null";
                    command.Parameters.AddWithValue("$p", scheme);
                    using (SqliteDataReader r = command.ExecuteReader())
                    {
                        while (r.Read())
                        {
                            alphas.Add(new[] { r.GetDouble(0), r.GetDouble(1) });
                        }
                    }
                }

                // Доли оболочек — `g4_gamma` дочерних ядер всех мод распада линий.
                var nuclei = new HashSet<long>();
                foreach (double[] gamma in gammas)
                {
                    int z, a;
                    if (Daughter((int)gamma[2], parentZ, massNumber, out z, out a))
                    {
                        nuclei.Add(z * 1000L + a);
                    }
                }

                foreach (long key in nuclei)
                {
                    using (SqliteCommand command = connection.CreateCommand())
                    {
                        command.CommandText = "select energy_ev, icc_total, icc_k_ppm, icc_l_ppm, icc_m_ppm, icc_outer_ppm"
                                              + " from g4_gamma where z = $z and a = $a and icc_total > 0";
                        command.Parameters.AddWithValue("$z", (int)(key / 1000));
                        command.Parameters.AddWithValue("$a", (int)(key % 1000));
                        using (SqliteDataReader r = command.ExecuteReader())
                        {
                            while (r.Read())
                            {
                                g4.Add(new[]
                                {
                                    key, Convert.ToDouble(r.GetValue(0), CultureInfo.InvariantCulture) / 1000.0, r.GetDouble(1),
                                    r.IsDBNull(2) ? -1.0 : Convert.ToDouble(r.GetValue(2), CultureInfo.InvariantCulture),
                                    r.IsDBNull(3) ? -1.0 : Convert.ToDouble(r.GetValue(3), CultureInfo.InvariantCulture),
                                    r.IsDBNull(4) ? -1.0 : Convert.ToDouble(r.GetValue(4), CultureInfo.InvariantCulture),
                                    r.IsDBNull(5) ? -1.0 : Convert.ToDouble(r.GetValue(5), CultureInfo.InvariantCulture),
                                });
                            }
                        }
                    }
                }
            }
        }

        static List<KeyValuePair<double, string>> ReadLevels(SqliteConnection connection, int datasetId)
        {
            var list = new List<KeyValuePair<double, string>>();
            using (SqliteCommand command = connection.CreateCommand())
            {
                // Уровни, у которых в датасете ЕСТЬ питание ветвью, — первыми
                // (у 234TH у 73.9 кэВ два уровня, питается изомер 0−): поиск
                // ближайшего идёт сперва среди них (<see cref="NearestLevel"/>).
                command.CommandText = "select l.energy_kev, l.jpi, exists(select 1 from ensdf_feedings f"
                                      + " where f.dataset_id = l.dataset_id and f.level_seq = l.seq) from ensdf_levels l"
                                      + " where l.dataset_id = $d order by 3 desc";
                command.Parameters.AddWithValue("$d", datasetId);
                using (SqliteDataReader r = command.ExecuteReader())
                {
                    while (r.Read())
                    {
                        if (!r.IsDBNull(0))
                        {
                            bool fed = !r.IsDBNull(2) && Convert.ToInt64(r.GetValue(2), CultureInfo.InvariantCulture) != 0;
                            list.Add(new KeyValuePair<double, string>(r.GetDouble(0),
                                                                      (fed ? "F" : "-") + (r.IsDBNull(1) ? "" : r.GetString(1))));
                        }
                    }
                }
            }

            // (`AMBER274`) Питание ветвью с ГРАНИЦЕЙ в записи ENSDF — сверка
            // прямо по границе (у 234TH уровень изомера 73.92+X без энергии).
            using (SqliteCommand command = connection.CreateCommand())
            {
                command.CommandText = "select f.energy_kev, l.jpi from ensdf_feedings f join ensdf_levels l"
                                      + " on l.dataset_id = f.dataset_id and l.seq = f.level_seq"
                                      + " where f.dataset_id = $d and f.energy_kev is not null";
                command.Parameters.AddWithValue("$d", datasetId);
                using (SqliteDataReader r = command.ExecuteReader())
                {
                    while (r.Read())
                    {
                        list.Add(new KeyValuePair<double, string>(-r.GetDouble(0), "E" + (r.IsDBNull(1) ? "" : r.GetString(1))));
                    }
                }
            }

            return list;
        }

        /// <summary>
        /// Дочернее ядро линии по коду моды распада `dec_type` (`database/scheme.md`):
        /// 0 — α, 1/7/15/50 — захват и β⁺, 2 — β⁻, 3 — изомерный переход; прочие — нет.
        /// </summary>
        static bool Daughter(int decType, int parentZ, int massNumber, out int z, out int a)
        {
            z = parentZ;
            a = massNumber;
            switch (decType)
            {
                case 0: z = parentZ - 2; a = massNumber - 4; return true;
                case 1:
                case 7:
                case 15:
                case 50: z = parentZ - 1; return true;
                case 2: z = parentZ + 1; return true;
                case 3: return true;
                default: return false;
            }
        }

        /// <summary>
        /// (`Ф4`) Линии электронов конверсии по гамма-линиям распада: выход оболочки —
        /// I_γ·α·f_оболочки (α — ENSDF датасета родителя, нет — Geant4; доли — Geant4
        /// дочернего ядра), энергия — E_γ − E_связи (K; средняя по L1–L3; средняя по
        /// M1–M5; внешние — E_γ) дочернего атома по EADL. Оже-электроны не берутся: их
        /// энергии ниже <see cref="MinConversionKev"/> у всех Z ниже 92 по K-серии — кроме
        /// тяжёлых, где выход оже по K мал (ω_K ≥ 0.95), — и ниже нижнего узла сетки раздела.
        /// </summary>
        static void AddConversion(string nucid, int parentZ, int massNumber, List<double[]> gammas,
                                  List<double[]> alphas, List<double[]> g4, List<FsaBeta> list, StringBuilder note)
        {
            if (g4.Count == 0)
            {
                return;
            }

            var binding = new Dictionary<int, double[]>();
            int added = 0;
            double total = 0.0;
            foreach (double[] gamma in gammas)
            {
                double energy = gamma[0], intensity = gamma[1];
                int z, a;
                if (!(energy > MinConversionKev) || !(intensity > 0.0) || !Daughter((int)gamma[2], parentZ, massNumber, out z, out a))
                {
                    continue;
                }

                double[] shells = null;
                double distance = 0.5;
                long key = z * 1000L + a;
                foreach (double[] row in g4)
                {
                    if ((long)row[0] != key)
                    {
                        continue;
                    }

                    double d = Math.Abs(row[1] - energy);
                    if (d <= distance)
                    {
                        distance = d;
                        shells = row;
                    }
                }

                if (shells == null || !(shells[3] >= 0.0))
                {
                    continue;
                }

                double alpha = shells[2];
                double best = 0.5;
                foreach (double[] row in alphas)
                {
                    double d = Math.Abs(row[0] - energy);
                    if (d <= best)
                    {
                        best = d;
                        alpha = row[1];
                    }
                }

                double[] bind;
                if (!binding.TryGetValue(z, out bind))
                {
                    bind = Binding(z);
                    binding[z] = bind;
                }

                string[] names = { "K", "L", "M", "N+" };
                for (int s = 0; s < 4; s++)
                {
                    double share = shells[3 + s];
                    if (!(share > 0.0))
                    {
                        continue;
                    }

                    double yield = intensity * alpha * share / 1.0e6;
                    double kev = energy - (s < 3 ? bind[s] : 0.0);
                    if (!(yield >= MinConversionPercent) || !(kev > MinConversionKev) || (s < 3 && !(bind[s] > 0.0)))
                    {
                        continue;
                    }

                    list.Add(FsaBeta.Line(nucid, kev, yield, names[s]));
                    added++;
                    total += yield;
                }
            }

            if (added > 0)
            {
                note.Append("конверсия: ").Append(added.ToString(CultureInfo.InvariantCulture)).Append(" линий, ")
                    .Append(total.ToString("G4", CultureInfo.InvariantCulture)).Append(" % на распад; ");
            }
        }

        /// <summary>(`Ф4`) Энергии связи K, средняя L1–L3, средняя M1–M5 атома Z, кэВ (`matdb.eadl_binding`).</summary>
        internal static double[] Binding(int z)
        {
            var result = new double[3];
            var sums = new double[3];
            var counts = new int[3];
            using (SqliteConnection connection = OpenRead(DatabasePath("matdb.sqlite")))
            using (SqliteCommand command = connection.CreateCommand())
            {
                command.CommandText = "select shell_id, binding_ev from eadl_binding where z = $z";
                command.Parameters.AddWithValue("$z", z);
                using (SqliteDataReader r = command.ExecuteReader())
                {
                    while (r.Read())
                    {
                        int id = Convert.ToInt32(r.GetValue(0), CultureInfo.InvariantCulture);
                        double kev = Convert.ToDouble(r.GetValue(1), CultureInfo.InvariantCulture) / 1000.0;
                        int group = id == 1 ? 0 : id == 3 || id == 5 || id == 6 ? 1 : id == 8 || id == 10 || id == 11 || id == 13 || id == 14 ? 2 : -1;
                        if (group >= 0)
                        {
                            sums[group] += kev;
                            counts[group]++;
                        }
                    }
                }
            }

            for (int g = 0; g < 3; g++)
            {
                result[g] = counts[g] > 0 ? sums[g] / counts[g] : 0.0;
            }

            return result;
        }

        /// <summary>
        /// (`Ф1`) Характер перехода по ΔJ и чётности. Порядок формы <paramref name="order"/>:
        /// 0 — разрешённая (и первый неуникальный, ξ-приближение); n — уникальный n-й; у
        /// неуникального k-го (k ≥ 2) — форма уникального (k − 1)-го (ξ-приближение).
        /// Чётность неизвестна — по одному ΔJ, как прежде.
        /// </summary>
        static void Classify(int dj, bool parityKnown, bool parityChange, out int order, out string transition)
        {
            if (dj <= 1)
            {
                order = 0;
                transition = parityKnown && parityChange ? "1st non-unique" : parityKnown ? "allowed" : "allowed (π?)";
                return;
            }

            order = dj - 1;
            int n = dj - 1;
            bool uniqueParity = n % 2 == 1;        // уникальный n-й: Δπ = (−1)ⁿ
            if (!parityKnown)
            {
                transition = "ΔJ=" + dj.ToString(CultureInfo.InvariantCulture) + " (π?)";
            }
            else if (parityChange == uniqueParity)
            {
                transition = Ordinal(n) + " unique";
            }
            else
            {
                transition = Ordinal(dj) + " non-unique";
            }
        }

        static string Ordinal(int n)
        {
            string s = n.ToString(CultureInfo.InvariantCulture);
            return n == 1 ? "1st" : n == 2 ? "2nd" : n == 3 ? "3rd" : s + "th";
        }

        sealed class DataSet
        {
            public int Id;
            public string Dsid;
            public double Q;
            public int Level;
            public double HalfLife;
        }

        static DataSet Pick(List<DataSet> sets, string kind, string altKind, int level, double halfLife)
        {
            DataSet best = null;
            double bestScore = double.MaxValue;
            foreach (DataSet s in sets)
            {
                bool kindOk = s.Dsid.IndexOf(kind, StringComparison.OrdinalIgnoreCase) >= 0
                              || (altKind != null && s.Dsid.IndexOf(altKind, StringComparison.OrdinalIgnoreCase) >= 0);
                if (!kindOk || s.Level != level)
                {
                    continue;
                }

                double score = halfLife > 0.0 && s.HalfLife > 0.0 ? Math.Abs(Math.Log(s.HalfLife / halfLife)) : 0.0;
                if (score < bestScore)
                {
                    bestScore = score;
                    best = s;
                }
            }

            return best;
        }

        /// <summary>
        /// Jπ уровня, чьё питание в ENSDF записано С ГРАНИЦЕЙ, равной границе ветви
        /// базы (записи с меткой `E`, ключ — минус граница); null — такой записи нет.
        /// </summary>
        static string ByEndpoint(List<KeyValuePair<double, string>> levels, double endpoint, double tolerance)
        {
            string best = null;
            double distance = tolerance;
            foreach (KeyValuePair<double, string> level in levels)
            {
                if (!level.Value.StartsWith("E", StringComparison.Ordinal))
                {
                    continue;
                }

                double d = Math.Abs(-level.Key - endpoint);
                if (d <= distance)
                {
                    distance = d;
                    best = level.Value.Substring(1);
                }
            }

            return string.IsNullOrEmpty(best) ? null : best;
        }

        /// <summary>
        /// Jπ ближайшего уровня в допуске: сперва среди уровней с питанием ветвью
        /// (метка `F` в начале записи), затем среди всех; null — нет в допуске.
        /// </summary>
        static string NearestLevel(List<KeyValuePair<double, string>> levels, double kev, double tolerance, out double found)
        {
            found = double.NaN;
            for (int pass = 0; pass < 2; pass++)
            {
                string best = null;
                double distance = tolerance;
                foreach (KeyValuePair<double, string> level in levels)
                {
                    if (level.Value.StartsWith("E", StringComparison.Ordinal)
                        || (pass == 0 && !level.Value.StartsWith("F", StringComparison.Ordinal)))
                    {
                        continue;
                    }

                    double d = Math.Abs(level.Key - kev);
                    if (d <= distance)
                    {
                        distance = d;
                        best = level.Value.Substring(1);
                        found = level.Key;
                    }
                }

                if (best != null)
                {
                    return best.Length > 0 ? best : null;
                }
            }

            return null;
        }

        /// <summary>Спин из записи Jπ ENSDF: «11/2-», «(4+)», «(4+,5+)» — первый вариант.</summary>
        static bool TryJ(string jpi, out double j)
        {
            j = double.NaN;
            if (string.IsNullOrEmpty(jpi))
            {
                return false;
            }

            var sb = new StringBuilder();
            foreach (char c in jpi)
            {
                if (c == ',' || c == ' ' && sb.Length > 0)
                {
                    break;
                }

                if (char.IsDigit(c) || c == '/')
                {
                    sb.Append(c);
                }
            }

            string text = sb.ToString();
            if (text.Length == 0)
            {
                return false;
            }

            int slash = text.IndexOf('/');
            double a, b = 1.0;
            if (slash > 0)
            {
                if (!double.TryParse(text.Substring(0, slash), NumberStyles.Integer, CultureInfo.InvariantCulture, out a)
                    || !double.TryParse(text.Substring(slash + 1), NumberStyles.Integer, CultureInfo.InvariantCulture, out b)
                    || !(b > 0.0))
                {
                    return false;
                }
            }
            else if (!double.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out a))
            {
                return false;
            }

            j = a / b;
            return true;
        }

        /// <summary>(`Ф1`) Чётность из записи Jπ: знак при первом варианте («7/2+», «(4-)», «(4+,5+)»).</summary>
        static bool TryParity(string jpi, out int parity)
        {
            parity = 0;
            if (string.IsNullOrEmpty(jpi))
            {
                return false;
            }

            foreach (char c in jpi)
            {
                if (c == ',')
                {
                    break;
                }

                if (c == '+' || c == '-')
                {
                    parity = c == '+' ? 1 : -1;
                    return true;
                }
            }

            return false;
        }

        static double Number(string text)
        {
            string t = (text ?? "").Trim().Trim('(', ')', ' ');
            double v;
            return double.TryParse(t, NumberStyles.Float, CultureInfo.InvariantCulture, out v) ? v : double.NaN;
        }

        static SqliteConnection OpenRead(string path)
        {
            SqliteConnection connection = new SqliteConnection(
                EfficiencyMaker.MaterialDatabase.ReadOnlyConnection(path, true));
            connection.Open();
            return connection;
        }

        // ------------------------------------------------------------------ форма

        /// <summary>
        /// Плотность спектра N(T) ветви, ненормированная (на кэВ). Таблица (`Ф1`/`Ф2`) —
        /// линейно по её узлам и до её границы; фактор — разрешённая форма × C(W); иначе —
        /// форма кодом.
        /// У линии конверсии — нуль (её образ — «шапочки» узла, <see cref="Weights"/>).
        /// </summary>
        public static double Density(FsaBeta beta, double t)
        {
            if (beta == null || beta.IsLine || !(t > 0.0) || !(t < beta.EndpointKev))
            {
                return 0.0;
            }

            if (beta.ShapeT != null && beta.ShapeDensity != null && beta.ShapeEndpointKev > 0.0)
            {
                // Узлы таблицы — как есть, без растяжки к границе базы: у Pa-234m граница
                // базы 2290 кэВ против 2269 у LNHB, и растяжка сдвигала среднюю на +1.4 %
                // (замер `BetaSectionProbeA274 --shapes`); форма и её граница — из одного
                // источника. Выше границы таблицы — нуль.
                return Interpolate(beta.ShapeT, beta.ShapeDensity, t);
            }

            double w = 1.0 + t / ElectronMassKev;
            double w0 = 1.0 + beta.EndpointKev / ElectronMassKev;
            double p = Math.Sqrt(w * w - 1.0);
            double q = w0 - w;
            double f = Fermi(beta.DaughterZ, beta.MassNumber, w, p, beta.Positron);
            if (FermiFiniteSize && beta.DaughterZ > 0)
            {
                // (`AMBER274`, полоса `a274L` 13.11.2026) F₀ → F₀L₀ заряженной сферы; λₖ ниже —
                // отношение амплитуд, L₀ в нём не сидит, двойного учёта нет.
                f *= CoulombSphere.FiniteSizeL0(beta.DaughterZ, beta.MassNumber, beta.Positron, p);
            }

            if (FermiScreening && beta.DaughterZ > 0)
            {
                // (`AMBER274`, полоса `a274s` 13.11.2026) экранирование атомными электронами —
                // общий множитель S(Z, W) (Бюринг, потенциал Салвата, X = 1; Hayen 2018, ур. 144);
                // с L₀ и λ не пересекается: S — от потенциала атома, L₀ и λ — от заряда ядра.
                f *= AtomicScreening.Correction(beta.DaughterZ, w, beta.Positron);
            }

            double s = beta.ShapeFactor != null
                ? Math.Max(0.0, beta.ShapeFactor[0] + beta.ShapeFactor[1] * w + beta.ShapeFactor[2] / w
                                + beta.ShapeFactor[3] * w * w)
                : (CoulombLambda && beta.DaughterZ > 0 && beta.UniqueOrder > 0 && (!beta.Positron || !CoulombLambdaPointNucleus)
                    ? UniqueShapeCoulomb(beta.UniqueOrder, p, q, beta.DaughterZ, beta.MassNumber, w, beta.Positron)
                    : UniqueShape(beta.UniqueOrder, p, q));
            double value = p * w * q * q * f * s;
            return value > 0.0 && !double.IsInfinity(value) ? value : 0.0;
        }

        static double Interpolate(double[] x, double[] y, double at)
        {
            int n = x.Length;
            if (!(at > x[0]) || !(at < x[n - 1]))
            {
                return at == x[0] ? Math.Max(0.0, y[0]) : 0.0;
            }

            int lo = 0, hi = n - 1;
            while (hi - lo > 1)
            {
                int mid = (lo + hi) / 2;
                if (x[mid] <= at)
                {
                    lo = mid;
                }
                else
                {
                    hi = mid;
                }
            }

            double span = x[hi] - x[lo];
            double v = span > 0.0 ? y[lo] + (y[hi] - y[lo]) * (at - x[lo]) / span : y[lo];
            return v > 0.0 ? v : 0.0;
        }

        /// <summary>∫ N(T) dT и средняя энергия формы, кэВ (Симпсон, 2048 отрезков); у линии — 1 и её энергия.</summary>
        public static double Integral(FsaBeta beta, out double meanKev)
        {
            meanKev = double.NaN;
            if (beta == null || !(beta.EndpointKev > 0.0))
            {
                return 0.0;
            }

            if (beta.IsLine)
            {
                meanKev = beta.EndpointKev;
                return 1.0;
            }

            const int Steps = 2048;
            double h = beta.EndpointKev / Steps, sum = 0.0, first = 0.0;
            for (int i = 0; i <= Steps; i++)
            {
                double t = i == 0 ? 1e-6 * beta.EndpointKev : (i == Steps ? beta.EndpointKev * (1.0 - 1e-9) : h * i);
                double f = Density(beta, t);
                double c = i == 0 || i == Steps ? 1.0 : (i % 2 == 1 ? 4.0 : 2.0);
                sum += c * f;
                first += c * f * t;
            }

            sum *= h / 3.0;
            first *= h / 3.0;
            meanKev = sum > 0.0 ? first / sum : double.NaN;
            return sum;
        }

        /// <summary>
        /// Фактор формы уникального n-го запрета: Σₖ p²ᵏq²⁽ⁿ⁻ᵏ⁾/((2k+1)!(2n−2k+1)!),
        /// нормированный на коэффициент при q²ⁿ; n = 0 — единица.
        /// </summary>
        static double UniqueShape(int n, double p, double q)
        {
            if (n <= 0)
            {
                return 1.0;
            }

            double lead = 1.0 / (Factorial(1) * Factorial(2 * n + 1));
            double s = 0.0;
            for (int k = 0; k <= n; k++)
            {
                s += Math.Pow(p, 2 * k) * Math.Pow(q, 2 * (n - k)) / (Factorial(2 * k + 1) * Factorial(2 * n - 2 * k + 1));
            }

            return s / lead;
        }

        /// <summary>
        /// (`AMBER274`, ревизия по статьям, полоса `a274s` 12.11.2026) КУЛОНОВСКИЕ λₖ В ФАКТОРЕ
        /// УНИКАЛЬНОГО ЗАПРЕТА — ключ, умолчание ВЫКЛ. Решение Amber 12.11.2026 вопросником,
        /// дословно: «λ ключом выкл, таблицу не писать (Рекомендую)».
        ///
        /// ВЫКЛ — λₖ = 1 (<see cref="UniqueShape"/>), форма побитно прежняя. ВКЛ — фактор
        /// Σₖ λₖ₊₁·p²ᵏq²⁽ⁿ⁻ᵏ⁾/((2k+1)!(2n−2k+1)!) с λₖ = F₍ₖ₋₁₎/F₀ точечного ядра
        /// (<see cref="CoulombAmplitudeRatio"/>), у ветвей β⁻ без таблицы и фактора базы. Замер
        /// (проба `CrystalOwnActivityProbeA274 --mode=clambda`): средняя формы к средней базы у
        /// Z ≤ 58 сходится до 0.2–0.4 %, у Z ≥ 81 точечное ядро перелетает на 3–6 % в другую сторону.
        ///
        /// ➕ (`a274t` 13.11.2026) Умолчание ВКЛ-формы — λₖ РАВНОМЕРНО ЗАРЯЖЕННОЙ СФЕРЫ
        /// (<see cref="CoulombSphere"/>, численно по уравнениям Дирака), у β⁻ и у β⁺ (знак заряда
        /// обратный); точечное ядро — рычагом <see cref="CoulombLambdaPointNucleus"/>. Замер
        /// (`--mode=sphere`): у Z ≥ 81 отклонение средней от базы −3…−6 % → −0.04…−2.2 %, у Z ≤ 58
        /// наибольшее 0.38 % → 0.23 %, у β⁺ (K-40, Al-26) ближе к базе, чем λ = 1.
        ///
        /// ⛔ Ключ меняет функцию распределения формы в строках ветвей раздела электрона склада
        /// (`ElectronBranchSpec.BetaCdf`, поле `br=` клейма) и веса узлов беты без строки
        /// (<see cref="Weights"/>, кэш — с ключом). Включать — после замера корпуса «до/после»,
        /// критиков и вместе с общим пересчётом склада; клеймо раздела при ВКЛ несёт `cl=` с версией
        /// формы (<see cref="CoulombLambdaVersion"/>), и разбор раздел другой формы не берёт
        /// (`ResponseMatrix.ElectronSectionFor`).
        ///
        /// ✅ (rev55, полоса `d55` 13.11.2026) УМОЛЧАНИЕ — ВКЛ, вместе с подменой склада корпуса на
        /// `uc_full` (полоса `a315u`, критик `crit55`). Решение Amber 13.11.2026 вопросником,
        /// дословно: «Да, одним пересчётом» (λ и L₀ — в общий пересчёт склада с `uc`). Склад
        /// посчитан с `cl=2;l0=1`, и при прежнем умолчании ВЫКЛ разбор такой раздел не берёт
        /// (код 68 «РАЗДЕЛ ЭЛЕКТРОНА НЕ ВЗЯТ»), поэтому умолчание и склад меняются только вместе.
        /// </summary>
        public static bool CoulombLambda = true;

        /// <summary>
        /// (`AMBER274`, полоса `a274t` 13.11.2026) РЫЧАГ ЗАМЕРА: λₖ точечного ядра (прежняя форма
        /// полосы `a274s`, только β⁻) вместо равномерно заряженной сферы. Умолчание — сфера
        /// (<see cref="CoulombSphere"/>): у Z ≥ 81 точечное ядро перелетало справочную среднюю на
        /// 3–6 %. Действует только при <see cref="CoulombLambda"/>; пробе — мутант и сравнение.
        /// </summary>
        public static bool CoulombLambdaPointNucleus = false;

        /// <summary>
        /// (`a274t`) Значение поля `cl=` в клеймах разделов при ВКЛ <see cref="CoulombLambda"/>:
        /// «1» — точечное ядро (`a274s`), «2» — заряженная сфера, β⁻ и β⁺. Раздел, посчитанный
        /// другой формой, разбор не берёт (`ResponseMatrix.ElectronSectionFor`).
        /// </summary>
        public static string CoulombLambdaVersion
        {
            get { return CoulombLambdaPointNucleus ? "1" : "2"; }
        }

        /// <summary>
        /// (`AMBER274`, полоса `a274L` 13.11.2026) ПОПРАВКА L₀ НА КОНЕЧНЫЙ РАЗМЕР ЯДРА В ФУНКЦИИ
        /// ФЕРМИ — ключ, умолчание ВЫКЛ. Решение Amber 13.11.2026 вопросником, дословно:
        /// «Выключенным ключом + замер (Рекомендую)»; находка критика `crit274t`: разрешённые
        /// ветви у Z ≈ 90 на 0.4–1.1 % выше средних ENSDF, F₀ точечного ядра.
        ///
        /// ВЫКЛ — F₀ точечного ядра (<see cref="Fermi"/>), форма побитно прежняя. ВКЛ — F₀·L₀, где
        /// L₀ = F₀L₀ равномерно заряженной сферы ((α₋₁² + α₁²)/(2p²), уравнения Дирака численно)
        /// к F₀ точечного ядра того же радиуса (<see cref="CoulombSphere.FiniteSizeL0"/>); у всех
        /// форм кодом (разрешённые, уникальные, фактор формы базы), у β⁻ и β⁺; таблицы
        /// `beta_shapes` — как есть. С ключом λ двойного учёта нет: λₖ = (α₋ₖ² + αₖ²)/(α₋₁² + α₁²)
        /// — отношение, а L₀ — в общем множителе F₀L₀ = (α₋₁² + α₁²)/(2p²).
        ///
        /// ⛔ Ключ меняет функцию распределения формы в строках ветвей раздела электрона склада
        /// (`ElectronBranchSpec.BetaCdf`, поле `br=`), бету слоя кристалла и веса узлов беты без
        /// строки (<see cref="Weights"/>, кэш — с ключом). Клеймо раздела при ВКЛ несёт `l0=1`
        /// (<see cref="FermiFiniteSizeVersion"/>), разбор раздел без поля при ВКЛ (и с полем при
        /// ВЫКЛ) не берёт (`ResponseMatrix.ElectronSectionFor`). Включать — вместе с общим
        /// пересчётом склада, после замера корпуса «до/после» и критиков.
        ///
        /// ✅ (rev55, полоса `d55` 13.11.2026) УМОЛЧАНИЕ — ВКЛ, вместе с <see cref="CoulombLambda"/> и
        /// подменой склада корпуса на `uc_full` (полоса `a315u`, критик `crit55`). Решение Amber
        /// 13.11.2026 вопросником, дословно: «Да, одним пересчётом». Склад посчитан с `l0=1`; при
        /// умолчании ВЫКЛ разбор его раздел не берёт (код 68).
        /// </summary>
        public static bool FermiFiniteSize = true;

        /// <summary>(`a274L`) Значение поля `l0=` в клеймах разделов при ВКЛ <see cref="FermiFiniteSize"/>.</summary>
        public const string FermiFiniteSizeVersion = "1";

        /// <summary>
        /// (`AMBER274`, полоса `a274s` 13.11.2026) ЭКРАНИРОВАНИЕ ЯДРА АТОМНЫМИ ЭЛЕКТРОНАМИ В ФУНКЦИИ
        /// ФЕРМИ — ключ, умолчание ВЫКЛ. Решение Amber 13.11.2026 вопросником, дословно: «Принять,
        /// экран полосой (Рекомендую)» — L₀ остаётся для обоих знаков, экранирование — отдельной
        /// полосой за выключенным ключом, судить корпусом. Повод — находка критика `crit274L`: L₀
        /// уводит средние разрешённых β⁺ от базы (+0.46 % у Z 41–58, +0.84 % у Z 81–88), а
        /// экранирования, которое у позитрона поднимает мягкую часть, в модели не было.
        ///
        /// ВЫКЛ — форма побитно прежняя. ВКЛ — F₀(L₀) умножается на S(Z, W) Бюринга с потенциалом
        /// Салвата (<see cref="AtomicScreening.Correction"/>; Hayen и др., Rev. Mod. Phys. 90 (2018)
        /// 015008, §VII.A, ур. 144, 146, 148, X = 1 — как в BSG) у всех форм кодом, β⁻ и β⁺;
        /// таблицы `beta_shapes` — как есть. Роуз (сдвиг энергии на V₀, ур. 139) не взят: ниже V₀
        /// он не определён (разрыв ниже ~10 кэВ), а на рис. 5 Hayen 2018 расходится с численным
        /// счётом сильнее Бюринга–Салвата.
        ///
        /// ⛔ Ключ меняет функцию распределения формы в строках ветвей раздела электрона склада
        /// (`ElectronBranchSpec.BetaCdf`, поле `br=`), бету слоя кристалла и веса узлов беты без
        /// строки (<see cref="Weights"/>, кэш — с ключом). Клеймо раздела при ВКЛ несёт `scr=1`
        /// (<see cref="FermiScreeningVersion"/>), разбор раздел без поля при ВКЛ (и с полем при
        /// ВЫКЛ) не берёт (`ResponseMatrix.ElectronSectionFor`). Включать — вместе с пересчётом
        /// склада, после замера корпуса «до/после» и критиков.
        /// </summary>
        public static bool FermiScreening = false;

        /// <summary>(`a274s`) Значение поля `scr=` в клеймах разделов при ВКЛ <see cref="FermiScreening"/>.</summary>
        public const string FermiScreeningVersion = "1";

        /// <summary>
        /// (`a274s`, `a274t`) Фактор уникального n-го запрета с кулоновскими λ (<see cref="CoulombLambda"/>),
        /// нормированный, как <see cref="UniqueShape"/>, на коэффициент при q²ⁿ (λ₁ = 1). λₖ —
        /// заряженной сферы (β⁻ и β⁺), при рычаге <see cref="CoulombLambdaPointNucleus"/> — точечного ядра.
        /// </summary>
        static double UniqueShapeCoulomb(int n, double p, double q, int z, int massNumber, double w, bool positron)
        {
            double lead = 1.0 / (Factorial(1) * Factorial(2 * n + 1));
            double s = 0.0;
            for (int k = 0; k <= n; k++)
            {
                double term = Math.Pow(p, 2 * k) * Math.Pow(q, 2 * (n - k)) / (Factorial(2 * k + 1) * Factorial(2 * n - 2 * k + 1));
                if (k > 0)
                {
                    term *= CoulombLambdaPointNucleus
                        ? CoulombAmplitudeRatio(k + 1, z, massNumber, w, p)
                        : CoulombSphere.Lambda(k + 1, z, massNumber, positron, p);
                }

                s += term;
            }

            return s / lead;
        }

        /// <summary>
        /// (`a274s`) Отношение кулоновских амплитуд λₖ = F₍ₖ₋₁₎/F₀ точечного ядра радиуса
        /// R = 1.2·A^⅓ фм (Behrens–Jänecke): F₍ₖ₋₁₎ = [k(2k−1)!!]²·4ᵏ·(2pR)^{2(γₖ−k)}·e^{πy}·
        /// |Γ(γₖ+iy)|²/Γ(1+2γₖ)², γₖ = √(k² − (αZ)²), y = αZW/p (β⁻). При Z → 0 λₖ → 1.
        /// Та же формула, что у пробы `CrystalOwnActivityProbeA274` (её средние сверены с
        /// независимым расчётом критика `crit274r`).
        /// </summary>
        internal static double CoulombAmplitudeRatio(int k, int z, int massNumber, double w, double p)
        {
            if (k <= 1 || z <= 0 || !(p > 0.0))
            {
                return 1.0;
            }

            double az = FineStructure * z;
            double y = az * w / p;
            double radius = 1.2 * Math.Pow(Math.Max(1, massNumber), 1.0 / 3.0) / ComptonFm;
            Func<int, double> lnF = m =>
            {
                double g = Math.Sqrt(m * m - az * az);
                double odd = 1.0;
                for (int j = 2 * m - 1; j > 1; j -= 2)
                {
                    odd *= j;
                }

                return 2.0 * Math.Log(m * odd) + m * Math.Log(4.0) + 2.0 * (g - m) * Math.Log(2.0 * p * radius)
                       + Math.PI * y + 2.0 * ReLnGamma(g, y) - 2.0 * ReLnGamma(1.0 + 2.0 * g, 0.0);
            };
            double ratio = Math.Exp(lnF(k) - lnF(1));
            return ratio > 0.0 && !double.IsInfinity(ratio) ? ratio : 1.0;
        }

        static double Factorial(int n)
        {
            double f = 1.0;
            for (int i = 2; i <= n; i++)
            {
                f *= i;
            }

            return f;
        }

        /// <summary>
        /// Релятивистская функция Ферми точечного ядра радиуса R:
        /// F₀ = 2(1+γ)(2pR)^{2(γ−1)} e^{πη} |Γ(γ+iη)|² / Γ(2γ+1)², γ = √(1 − (αZ)²),
        /// η = ±αZW/p (β⁻ +, β⁺ −).
        /// </summary>
        static double Fermi(int z, int massNumber, double w, double p, bool positron)
        {
            if (z <= 0 || !(p > 0.0))
            {
                return 1.0;
            }

            double az = FineStructure * z;
            if (az >= 0.99)
            {
                az = 0.99;
            }

            double gamma = Math.Sqrt(1.0 - az * az);
            double eta = (positron ? -1.0 : 1.0) * az * w / p;
            double radius = 1.2 * Math.Pow(Math.Max(1, massNumber), 1.0 / 3.0) / ComptonFm;
            double log = Math.Log(2.0 * (1.0 + gamma)) + 2.0 * (gamma - 1.0) * Math.Log(2.0 * p * radius)
                         + Math.PI * eta + 2.0 * ReLnGamma(gamma, eta) - 2.0 * ReLnGamma(2.0 * gamma + 1.0, 0.0);
            return Math.Exp(log);
        }

        /// <summary>Re ln Γ(x + iy) при x &gt; 0 — приближение Ланцоша (g = 7, 9 членов).</summary>
        internal static double ReLnGamma(double x, double y)
        {
            double[] c =
            {
                0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313,
                -176.61502916214059, 12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6,
                1.5056327351493116e-7,
            };
            double zr = x - 1.0, zi = y;
            double ar = c[0], ai = 0.0;
            for (int k = 1; k < c.Length; k++)
            {
                double dr = zr + k;
                double d = dr * dr + zi * zi;
                ar += c[k] * dr / d;
                ai -= c[k] * zi / d;
            }

            double tr = zr + 7.5, ti = zi;
            double lnr = 0.5 * Math.Log(tr * tr + ti * ti);
            double theta = Math.Atan2(ti, tr);
            return 0.5 * Math.Log(2.0 * Math.PI) + (zr + 0.5) * lnr - zi * theta - tr + 0.5 * Math.Log(ar * ar + ai * ai);
        }

        // ------------------------------------------------------------------
        // (`AMBER274` Ф8, полоса `f8cyl` 02.11.2026) ВЕТВЬ — СОБЫТИЕМ ЦЕЛИКОМ
        // ------------------------------------------------------------------

        /// <summary>(`Ф8`) Уровень дочки, который питает ветвь, кэВ, — по ключу «нуклид|граница» (заполняет `Read`).</summary>
        static readonly Dictionary<string, double> LevelCache = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);

        /// <summary>(`Ф8`) Схема уровней дочки (Z, A) из `schemedb.g4_level`/`g4_gamma` — кэш.</summary>
        static readonly Dictionary<long, G4Scheme> SchemeCache = new Dictionary<long, G4Scheme>();

        static string LevelKey(string nucid, double endpointKev)
        {
            return (nucid ?? "") + "|" + endpointKev.ToString("R", CultureInfo.InvariantCulture);
        }

        /// <summary>(`Ф8`) Ветвь на уровень ниже этого — на основное состояние: каскада нет, кэВ.</summary>
        public const double GroundLevelKev = 1.0;

        /// <summary>
        /// (`Ф8`) Уровень Geant4 ищется у энергии ветви в этом допуске: max(2 кэВ, 0.2 % уровня) —
        /// уровни ENSDF и PhotonEvaporation 6.1.2 одной оценки расходятся на доли кэВ.
        /// </summary>
        public const double SchemeLevelToleranceKev = 2.0;

        /// <summary>(`Ф8`) Коэффициент конверсии выше этого — переход «целиком конверсионный» (поставка пишет до 10²²): зажим.</summary>
        public const double ConversionAlphaCap = 1.0e4;

        sealed class G4Level
        {
            public int Seq;
            public double Kev;
            public double HalfLifeSec;
            public readonly List<double[]> Transitions = new List<double[]>();   // to, Eγ, Iγ, α, K, L, M, внешние
        }

        sealed class G4Scheme
        {
            public readonly SortedDictionary<int, G4Level> Levels = new SortedDictionary<int, G4Level>();
        }

        /// <summary>
        /// (`AMBER274` Ф8, полоса `f8cyl` 02.11.2026) ТАБЛИЦЫ СТРОКИ ВЕТВИ «событие целиком» для
        /// β⁻-ветви <paramref name="beta"/> (решение Amber 30.10.2026 вопросником, дословно: «В Э1
        /// событием целиком (Рекомендую)»): функция распределения формы — той же
        /// <see cref="Density"/>, что у образа FSA; каскад — схема Geant4 дочки
        /// (`schemedb.g4_level`/`g4_gamma`, PhotonEvaporation 6.1.2) от уровня, который питает
        /// ветвь (баланс Q датасета, уточнённый уровнем ENSDF, — `Read`), с вероятностями
        /// переходов ∝ Iγ·(1 + α) и долями конверсии K/L/M/внешних, как `G4LevelReader`; энергии
        /// связи — `matdb.eadl_binding` (<see cref="Binding"/>). null — строки нет, причина — в
        /// <paramref name="reason"/>: позитрон (строки позитрона разбор по умолчанию не читает,
        /// `SamplePositronAtStop` ВЫКЛ), ветвь на основное состояние (совпадать не с чем), уровня в
        /// схеме нет, каскад с уровня — отдельное событие (изомер дольше
        /// <see cref="EfficiencyMaker.ElectronBranchSpec.PromptHalfLifeSec"/>).
        /// </summary>
        public static EfficiencyMaker.ElectronBranchSpec EventSpec(FsaBeta beta, out string reason)
        {
            reason = null;
            if (beta == null || beta.IsLine || !(beta.EndpointKev > 0.0))
            {
                reason = "не ветвь";
                return null;
            }

            if (beta.Positron)
            {
                reason = "β⁺ — строкой ветви не считается";
                return null;
            }

            double level;
            lock (Gate)
            {
                if (!LevelCache.TryGetValue(LevelKey(beta.Nuclide, beta.EndpointKev), out level))
                {
                    level = double.NaN;
                }
            }

            if (double.IsNaN(level))
            {
                reason = "уровень ветви не найден (нет датасета распада)";
                return null;
            }

            if (level < GroundLevelKev)
            {
                reason = "ветвь на основное состояние — совпадать не с чем";
                return null;
            }

            G4Scheme scheme = SchemeOf(beta.DaughterZ, beta.MassNumber);
            if (scheme == null || scheme.Levels.Count == 0)
            {
                reason = "схемы уровней дочки в schemedb нет";
                return null;
            }

            // Допуск — и от погрешности ГРАНИЦЫ: уровень посчитан балансом Q − E₀, а граница в
            // поставке округлена (у 214PB 666 кэВ против 672 у ENSDF — уровень 357 вместо 351.93);
            // та же мерка max(2 кэВ, 1 % E₀), что у сверки ветви с питанием (`ByEndpoint`).
            G4Level start = null;
            double distance = Math.Max(Math.Max(SchemeLevelToleranceKev, 0.002 * level), 0.01 * beta.EndpointKev);
            foreach (G4Level l in scheme.Levels.Values)
            {
                double d = Math.Abs(l.Kev - level);
                if (d <= distance)
                {
                    distance = d;
                    start = l;
                }
            }

            if (start == null)
            {
                reason = "уровня " + level.ToString("F2", CultureInfo.InvariantCulture) + " кэВ в схеме Geant4 нет";
                return null;
            }

            if (start.Seq == 0)
            {
                reason = "ветвь на основное состояние — совпадать не с чем";
                return null;
            }

            // (`AMBER274` Э3, полоса `a274a` 14.11.2026) таблицы каскада — общий кусок с альфой (<see cref="CascadeTables"/>)
            EfficiencyMaker.ElectronBranchSpec spec = CascadeTables(scheme, start, beta.DaughterZ);
            spec.Nuclide = beta.Nuclide;
            spec.EndpointKev = beta.EndpointKev;
            spec.Intensity = beta.Intensity;
            double[] tGrid, cdf;
            BetaCdf(beta, out tGrid, out cdf);
            spec.BetaT = tGrid;
            spec.BetaCdf = cdf;
            if (!spec.HasCascade)
            {
                reason = "уровень " + start.Kev.ToString("F2", CultureInfo.InvariantCulture)
                         + " кэВ — изомер или без переходов: каскад — отдельное событие";
                return null;
            }

            reason = spec.Problem();
            return reason == null ? spec : null;
        }

        /// <summary>
        /// (`AMBER274` Э3, полоса `a274a` 14.11.2026) ТАБЛИЦЫ КАСКАДА от уровня <paramref name="start"/> схемы
        /// Geant4 дочки — общий кусок строки ветви беты (<see cref="EventSpec"/>) и события альфы
        /// (<see cref="AlphaEventSpec"/>): уровни, достижимые вниз, переходы ∝ Iγ·(1 + α), доли конверсии
        /// K/L/M/внешних, энергии связи дочки <paramref name="daughterZ"/>. Вынесено без правки счёта:
        /// строки ветвей беты побитно прежние. Поля ветви (нуклид, граница, выход, форма) ставит зовущий.
        /// </summary>
        static EfficiencyMaker.ElectronBranchSpec CascadeTables(G4Scheme scheme, G4Level start, int daughterZ)
        {
            // Достижимые с начального уровня — по возрастанию номера (энергии): переход ведёт только вниз.
            var reach = new SortedSet<int>();
            var stack = new Stack<int>();
            stack.Push(start.Seq);
            while (stack.Count > 0)
            {
                int seq = stack.Pop();
                G4Level l;
                if (!reach.Add(seq) || !scheme.Levels.TryGetValue(seq, out l) || Terminal(l, start))
                {
                    continue;
                }

                foreach (double[] t in l.Transitions)
                {
                    int to = (int)t[0];
                    if (to < seq && scheme.Levels.ContainsKey(to))
                    {
                        stack.Push(to);
                    }
                }
            }

            var index = new Dictionary<int, int>();
            foreach (int seq in reach)
            {
                index[seq] = index.Count;
            }

            int levels = index.Count;
            var first = new int[levels];
            var count = new int[levels];
            var energies = new double[levels];
            var trCdf = new List<double>();
            var trTo = new List<int>();
            var emitCdf = new List<double>();
            var emitKev = new List<double>();
            double[] bind = Binding(daughterZ);
            foreach (int seq in reach)
            {
                G4Level l = scheme.Levels[seq];
                int i = index[seq];
                energies[i] = l.Kev;
                first[i] = trTo.Count;
                if (Terminal(l, start))
                {
                    continue;
                }

                var weights = new List<double>();
                var rows = new List<double[]>();
                foreach (double[] t in l.Transitions)
                {
                    int to = (int)t[0];
                    if (!(to < seq) || !index.ContainsKey(to))
                    {
                        continue;
                    }

                    double alpha = Math.Min(Math.Max(t[3], 0.0), ConversionAlphaCap);
                    double w = Math.Max(t[2], 0.0) * (1.0 + alpha);
                    if (!(w > 0.0))
                    {
                        continue;
                    }

                    weights.Add(w);
                    rows.Add(t);
                }

                double total = 0.0;
                foreach (double w in weights)
                {
                    total += w;
                }

                double run = 0.0;
                for (int k = 0; k < rows.Count; k++)
                {
                    double[] t = rows[k];
                    run += weights[k] / total;
                    trCdf.Add(k == rows.Count - 1 ? 1.0 : run);
                    trTo.Add(index[(int)t[0]]);
                    double eg = t[1];
                    double alpha = Math.Min(Math.Max(t[3], 0.0), ConversionAlphaCap);
                    double shares = Math.Max(t[4], 0.0) + Math.Max(t[5], 0.0) + Math.Max(t[6], 0.0) + Math.Max(t[7], 0.0);
                    double pGamma = 1.0 / (1.0 + alpha);
                    double cum = pGamma;
                    emitCdf.Add(cum);
                    emitKev.Add(eg);
                    for (int s = 0; s < 4; s++)
                    {
                        double share = shares > 0.0 ? Math.Max(t[4 + s], 0.0) / shares : (s == 3 ? 1.0 : 0.0);
                        cum += (1.0 - pGamma) * share;
                        emitCdf.Add(s == 3 ? 1.0 : cum);
                        double b = s < 3 ? bind[s] : 0.0;
                        emitKev.Add(s < 3 && !(b > 0.0) ? 0.0 : eg - b);
                    }
                }

                count[i] = rows.Count;
            }

            return new EfficiencyMaker.ElectronBranchSpec
            {
                LevelKev = start.Kev,
                StartLevel = index[start.Seq],
                LevelFirst = first,
                LevelCount = count,
                LevelEnergy = energies,
                TransitionCdf = trCdf.ToArray(),
                TransitionTo = trTo.ToArray(),
                EmitCdf = emitCdf.ToArray(),
                EmitKev = emitKev.ToArray(),
            };
        }

        /// <summary>
        /// (`AMBER274`, Э2, 04.11.2026) СПЕЦИФИКАЦИЯ ОДНОЙ БЕТЫ, БЕЗ КАСКАДА: ветвь,
        /// которая идёт на основное состояние или на уровень, которого в схеме Geant4
        /// нет. Для пробы такая ветвь неотличима от «событие кончилось» и в
        /// `EventSpec` отказывает — а для СОБСТВЕННОЙ АКТИВНОСТИ КРИСТАЛЛА это
        /// законный распад: бета оседает в объёме и без каскада (так идут β⁻ 44.8 кэВ
        /// у Ac-227, 1367 кэВ у Pb-211, 1431 кэВ у Tl-207, 574 кэВ у Bi-211).
        /// Каскада нет — `LevelCount` пуст, `CrystalEventFrom` кладёт одну бету.
        /// </summary>
        public static EfficiencyMaker.ElectronBranchSpec BetaOnlySpec(FsaBeta beta)
        {
            if (beta == null || beta.IsLine || beta.Positron || !(beta.EndpointKev > 0.0))
            {
                return null;
            }

            double[] t, cdf;
            BetaCdf(beta, out t, out cdf);
            return new EfficiencyMaker.ElectronBranchSpec
            {
                Nuclide = beta.Nuclide,
                EndpointKev = beta.EndpointKev,
                Intensity = beta.Intensity,
                LevelKev = 0.0,
                StartLevel = -1,
                LevelFirst = new int[0],
                LevelCount = new int[0],
                LevelEnergy = new double[0],
                TransitionCdf = new double[0],
                TransitionTo = new int[0],
                EmitCdf = new double[0],
                EmitKev = new double[0],
                BetaT = t,
                BetaCdf = cdf,
            };
        }

        /// <summary>
        /// (`AMBER274` Э3, полоса `a274a` 14.11.2026) КАСКАД ПОСЛЕ АЛЬФЫ: таблицы строки события с
        /// уровня <paramref name="levelKev"/> ядра-дочки (<paramref name="daughterZ"/>,
        /// <paramref name="daughterA"/>) по схеме Geant4 — тем же куском, что у беты
        /// (<see cref="CascadeTables"/>), и тем же допуском поиска уровня
        /// (max(<see cref="SchemeLevelToleranceKev"/>, 0.2 % уровня)). Беты нет: форма — вырожденная
        /// пара узлов, и <c>CrystalEventFrom</c> зовётся с <c>withBeta = false</c>. null — каскада нет:
        /// альфа на основное состояние, уровня в схеме нет, изомер дольше
        /// <see cref="EfficiencyMaker.ElectronBranchSpec.PromptHalfLifeSec"/>; причина — в
        /// <paramref name="reason"/>, событие тогда — одна альфа.
        /// </summary>
        public static EfficiencyMaker.ElectronBranchSpec AlphaEventSpec(int daughterZ, int daughterA, double levelKev, out string reason)
        {
            reason = null;
            if (!(levelKev >= GroundLevelKev))
            {
                reason = "альфа на основное состояние";
                return null;
            }

            G4Scheme scheme = SchemeOf(daughterZ, daughterA);
            if (scheme == null || scheme.Levels.Count == 0)
            {
                reason = "схемы уровней дочки в schemedb нет";
                return null;
            }

            G4Level start = null;
            double distance = Math.Max(SchemeLevelToleranceKev, 0.002 * levelKev);
            foreach (G4Level l in scheme.Levels.Values)
            {
                double d = Math.Abs(l.Kev - levelKev);
                if (d <= distance)
                {
                    distance = d;
                    start = l;
                }
            }

            if (start == null)
            {
                reason = "уровня " + levelKev.ToString("F2", CultureInfo.InvariantCulture) + " кэВ в схеме Geant4 нет";
                return null;
            }

            if (start.Seq == 0)
            {
                reason = "альфа на основное состояние";
                return null;
            }

            EfficiencyMaker.ElectronBranchSpec spec = CascadeTables(scheme, start, daughterZ);
            spec.EndpointKev = 0.0;
            spec.BetaT = new[] { 0.0, 0.0 };
            spec.BetaCdf = new[] { 0.0, 1.0 };
            if (!spec.HasCascade)
            {
                reason = "уровень " + start.Kev.ToString("F2", CultureInfo.InvariantCulture)
                         + " кэВ — изомер или без переходов: каскад — отдельное событие";
                return null;
            }

            reason = spec.Problem();
            return reason == null ? spec : null;
        }

        /// <summary>(`Ф8`) Каскад кончается на уровне: основное состояние или изомер дольше порога (кроме начального — тот разбирает `HasCascade`).</summary>
        static bool Terminal(G4Level l, G4Level start)
        {
            return l.Seq == 0 || l.Transitions.Count == 0
                   || l.HalfLifeSec > EfficiencyMaker.ElectronBranchSpec.PromptHalfLifeSec;
        }

        /// <summary>
        /// (`Ф8`) Функция распределения формы ветви: узлы 0…E₀ с шагом не крупнее 1 кэВ (не меньше
        /// 200 и не больше 4000 узлов), плотность — <see cref="Density"/>, накопление — трапециями,
        /// нормировка на последний узел.
        /// </summary>
        static void BetaCdf(FsaBeta beta, out double[] t, out double[] cdf)
        {
            int n = (int)Math.Ceiling(beta.EndpointKev);
            n = Math.Max(200, Math.Min(4000, n));
            t = new double[n + 1];
            cdf = new double[n + 1];
            double prev = 0.0, sum = 0.0;
            for (int i = 0; i <= n; i++)
            {
                t[i] = i == n ? beta.EndpointKev : beta.EndpointKev * i / n;
                double f = i == 0 || i == n ? 0.0 : Density(beta, t[i]);
                if (i > 0)
                {
                    sum += 0.5 * (prev + f) * (t[i] - t[i - 1]);
                }

                cdf[i] = sum;
                prev = f;
            }

            for (int i = 0; i <= n; i++)
            {
                cdf[i] = sum > 0.0 ? cdf[i] / sum : (double)i / n;
            }

            cdf[n] = 1.0;
        }

        /// <summary>(`Ф8`) Схема уровней ядра (Z, A) из `schemedb` — кэш; отказ чтения — запись в <see cref="FsaDatabaseFailures"/>, null.</summary>
        static G4Scheme SchemeOf(int z, int a)
        {
            long key = z * 1000L + a;
            lock (Gate)
            {
                G4Scheme cached;
                if (SchemeCache.TryGetValue(key, out cached))
                {
                    return cached;
                }
            }

            string path = DatabasePath("schemedb.sqlite");
            if (!File.Exists(path))
            {
                FsaDatabaseFailures.Note("schemedb.sqlite", z.ToString(CultureInfo.InvariantCulture) + "/" + a.ToString(CultureInfo.InvariantCulture),
                                         new FileNotFoundException("schemedb.sqlite not found", path));
                return null;
            }

            var scheme = new G4Scheme();
            try
            {
                using (SqliteConnection connection = OpenRead(path))
                {
                    using (SqliteCommand command = connection.CreateCommand())
                    {
                        command.CommandText = "select seq, energy_ev, half_life_sec from g4_level where z = $z and a = $a";
                        command.Parameters.AddWithValue("$z", z);
                        command.Parameters.AddWithValue("$a", a);
                        using (SqliteDataReader r = command.ExecuteReader())
                        {
                            while (r.Read())
                            {
                                var l = new G4Level
                                {
                                    Seq = Convert.ToInt32(r.GetValue(0), CultureInfo.InvariantCulture),
                                    Kev = Convert.ToDouble(r.GetValue(1), CultureInfo.InvariantCulture) / 1000.0,
                                    HalfLifeSec = r.IsDBNull(2) ? 0.0 : Convert.ToDouble(r.GetValue(2), CultureInfo.InvariantCulture),
                                };
                                scheme.Levels[l.Seq] = l;
                            }
                        }
                    }

                    using (SqliteCommand command = connection.CreateCommand())
                    {
                        command.CommandText = "select from_seq, to_seq, energy_ev, intensity_ppm, icc_total, icc_k_ppm, icc_l_ppm,"
                                              + " icc_m_ppm, icc_outer_ppm from g4_gamma where z = $z and a = $a order by from_seq, idx";
                        command.Parameters.AddWithValue("$z", z);
                        command.Parameters.AddWithValue("$a", a);
                        using (SqliteDataReader r = command.ExecuteReader())
                        {
                            while (r.Read())
                            {
                                G4Level l;
                                int from = Convert.ToInt32(r.GetValue(0), CultureInfo.InvariantCulture);
                                if (!scheme.Levels.TryGetValue(from, out l))
                                {
                                    continue;
                                }

                                Func<int, double> num = i => r.IsDBNull(i) ? 0.0 : Convert.ToDouble(r.GetValue(i), CultureInfo.InvariantCulture);
                                l.Transitions.Add(new[]
                                {
                                    num(1), num(2) / 1000.0, num(3), num(4), num(5), num(6), num(7), num(8),
                                });
                            }
                        }
                    }
                }
            }
            catch (Exception error)
            {
                FsaDatabaseFailures.Note("schemedb.sqlite", z.ToString(CultureInfo.InvariantCulture) + "/" + a.ToString(CultureInfo.InvariantCulture), error);
                return null;
            }

            lock (Gate)
            {
                SchemeCache[key] = scheme;
            }

            return scheme;
        }

        static readonly Dictionary<string, double[]> WeightCache = new Dictionary<string, double[]>(StringComparer.Ordinal);
        static readonly object WeightGate = new object();

        /// <summary>
        /// (`AMBER274`, полоса a269fix5) Имя, которым раздел подписывает строку ветви
        /// (`nucid` библиотеки, `208TL`), для беты под именем компонента («Tl-208»);
        /// не разобралось — то же имя.
        /// </summary>
        static string BranchNucid(string nuclide)
        {
            string nucid = FsaSampleLibrary.NucidOf(nuclide);
            return string.IsNullOrEmpty(nucid) ? nuclide : nucid;
        }

        /// <summary>
        /// Веса узлов раздела для ветви (доля ЕДИНИЧНОГО спектра на «шапочку» узла) или
        /// для линии конверсии (строка на её энергии, нет — линейная доля двух соседей по
        /// объединённой сетке узлов и строк линий; ниже нижнего узла — нуль: ни одна обвязка
        /// склада её не пропускает); кэш по разделу и форме.
        /// </summary>
        public static double[] Weights(EfficiencyMaker.ResponseElectronSection section, FsaBeta beta)
        {
            if (section == null || beta == null)
            {
                return null;
            }

            // (`Ф8`, `f8cyl`) Ключ — и по нуклиду и рычагу шва: строка ветви своя у каждого нуклида.
            string key = section.Stamp + "|" + (beta.IsLine ? "L" : "B") + beta.EndpointKev.ToString("R", CultureInfo.InvariantCulture)
                         + "|" + beta.DaughterZ.ToString(CultureInfo.InvariantCulture) + "|" + beta.MassNumber.ToString(CultureInfo.InvariantCulture)
                         + "|" + beta.UniqueOrder.ToString(CultureInfo.InvariantCulture) + (beta.Positron ? "+" : "-")
                         + "|" + beta.ShapeId.ToString(CultureInfo.InvariantCulture)
                         + "|" + beta.Nuclide + (EfficiencyMaker.ResponseElectronSection.BranchEvents ? "|E" : "|-")
                         + (CoulombLambda ? "|cl" + CoulombLambdaVersion : "")    // (`a274s`, `a274t`) форма с λ — свой вес; ВЫКЛ — ключ прежний
                         + (FermiFiniteSize ? "|l0" + FermiFiniteSizeVersion : "")    // (`a274L`) F₀L₀ — свой вес; ВЫКЛ — ключ прежний
                         + (FermiScreening ? "|scr" + FermiScreeningVersion : "");    // (`a274s`) экранирование — свой вес; ВЫКЛ — ключ прежний
            lock (WeightGate)
            {
                double[] cached;
                if (WeightCache.TryGetValue(key, out cached))
                {
                    return cached;
                }
            }

            double[] w;
            if (beta.IsLine)
            {
                // (`AMBER274`, физика 28) Строка на ТОЧНОЙ энергии линии, если раздел её несёт;
                // иначе — линейная доля соседей по объединённой сетке узлов и строк линий
                // (`ResponseElectronSection.LineWeights`). Прежде — только соседние узлы, и у
                // RC103 конверсия 624/656 в полосе 300–400 кэВ выходила в 2.2 раза выше
                // точного счёта (критик несходимости 30.10.2026).
                w = section.LineWeights(beta.EndpointKev);
            }
            else if ((w = section.BranchWeights(beta.Nuclide, beta.EndpointKev)) != null
                     || (w = section.BranchWeights(BranchNucid(beta.Nuclide), beta.EndpointKev)) != null)
            {
                // (`AMBER274` Ф8, `f8cyl`) У ветви есть строка «событие целиком» — вес 1 у неё:
                // образ — разность «событие − каскад» той же строки (доля на распад ветвью).
                //
                // ⛔ (`AMBER274`, полоса a269fix5, 02.11.2026) СТРОКА ВЕТВИ ИЩЕТСЯ И ПО `nucid`.
                //    Раздел подписывает строку ветви именем библиотеки (`208TL`,
                //    `FsaBetaLibrary.Branches` → `EventSpec`), а компонент разбора несёт бету под
                //    своим именем (`FsaSampleLibrary.AddBetas` → `FsaBeta.Scaled(PrettyName)`,
                //    «Tl-208»). Прежде поиск шёл только по имени компонента и в приложении не
                //    находил ни одной строки: у ряда Th-232 на матрице RC103 с разделом из 116
                //    строк ветвей образ брал строку у 0 ветвей из 24 со строкой — бета ложилась
                //    весами узлов, без выноса из пиков и суммы с гаммой (слой «Бета пробы»
                //    положителен всюду и пуст выше 1.1 МэВ). Проба `--fsa-branch-control` этого не
                //    видела: она берёт ветви из `FsaBetaLibrary.Branches` прямо, с именем `nucid`.
            }
            else
            {
                double mean;
                double norm = Integral(beta, out mean);
                w = section.NodeWeights(t => Density(beta, t), beta.EndpointKev);
                if (norm > 0.0)
                {
                    for (int k = 0; k < w.Length; k++)
                    {
                        w[k] /= norm;
                    }
                }
            }

            lock (WeightGate)
            {
                WeightCache[key] = w;
            }

            return w;
        }
    }

    /// <summary>
    /// (`AMBER274`, полоса `a274t` 13.11.2026) КУЛОНОВСКИЕ АМПЛИТУДЫ РАВНОМЕРНО ЗАРЯЖЕННОЙ СФЕРЫ —
    /// λₖ фактора уникального запрета при ключе <see cref="FsaBetaLibrary.CoulombLambda"/>.
    ///
    /// Определение (Behrens–Bühring; Hayen и др., Rev. Mod. Phys. 90 (2018) 015008, ур. 12–13):
    /// радиальные функции электрона у начала координат раскладываются как
    /// g₋ₖ(r) = α₋ₖ·(pr)^(k−1)/(2k−1)!!·(1 + …), fₖ(r) = αₖ·(pr)^(k−1)/(2k−1)!!·(1 + …), и
    /// F₀L₀ = (α₋₁² + α₁²)/(2p²); λₖ = (α₋ₖ² + αₖ²)/(α₋₁² + α₁²) (BetaShape, Mougeot 2015).
    /// Ядро — равномерно заряженная сфера радиуса R = 1.2·A^⅓ фм (тот же R, что у точечной
    /// формулы `a274s`), потенциал внутри −αZ(3 − r²/R²)/(2R), снаружи −αZ/r; у β⁺ знак заряда
    /// обратный — та же формула закрывает и позитрон.
    ///
    /// Счёт численный: уравнения Дирака для u = r·g, v = r·f
    /// u′ = −(κ/r)·u + (W − V + 1)·v, v′ = (κ/r)·v − (W − V − 1)·u (ħ = mₑ = c = 1)
    /// от r₀ = 10⁻⁴R с ведущим членом ряда (α = 1) наружу адаптивным Дорманом–Принсом до
    /// r_end, где ВКБ-инвариант A² = P·[u²/(W−V+1) + v²/(W−V−1)], P = √((W−V)² − 1), усреднён
    /// по периоду; нормировка «на бесконечности» A² = p/W даёт α² = (p/W)/A² (при Z = 0
    /// α₋₁² + α₁² = 2p², то есть F₀L₀ = 1). Таблица λₖ по 160 узлам ln p считается один раз на
    /// (Z, A, знак, k) и читается кубической интерполяцией.
    ///
    /// Проверки (проба `CrystalOwnActivityProbeA274 --mode=sphere`): L₀ = (α₋₁² + α₁²)/(2p²F₀)
    /// против формулы Уилкинсона (Hayen 2018, ур. 16, табл. I) при Z ≤ 60; Z → 0 даёт λ = 1;
    /// сходимость по r_end; средние уникальных ветвей к средним `nucdb`.
    /// </summary>
    public static class CoulombSphere
    {
        const double FineStructure = 1.0 / 137.035999084;
        const double ComptonFm = 386.15926796;   // ħ/(mₑc), фм

        /// <summary>Узлы таблицы по ln p: p от 0.004 (4 эВ) до 40 (≈ 20 МэВ).</summary>
        const int Nodes = 160;
        static readonly double LnPMin = Math.Log(0.004);
        static readonly double LnPMax = Math.Log(40.0);

        static readonly object Gate = new object();
        static readonly Dictionary<string, double[]> Amplitudes = new Dictionary<string, double[]>(StringComparer.Ordinal);

        /// <summary>Радиус сферы, единицы ħ/(mₑc).</summary>
        public static double Radius(int massNumber)
        {
            return 1.2 * Math.Pow(Math.Max(1, massNumber), 1.0 / 3.0) / ComptonFm;
        }

        static readonly Dictionary<string, double[]> FiniteSizeTables = new Dictionary<string, double[]>(StringComparer.Ordinal);

        /// <summary>
        /// (`AMBER274`, полоса `a274L` 13.11.2026) L₀ — поправка на конечный размер ядра к F₀
        /// точечного ядра того же радиуса: L₀ = (α₋₁² + α₁²)/(2p²·F₀), F₀ = 4(2pR)^{2(γ−1)}e^{πy}
        /// |Γ(γ+iy)|²/Γ(2γ+1)², y = ±αZW/p (запись Hayen 2018, ур. 6; к ней относится L₀ Уилкинсона,
        /// ур. 16). Множитель F₀ ключа <see cref="FsaBetaLibrary.FermiFiniteSize"/>. Z ≤ 0 или
        /// p ≤ 0 — единица; при Z → 0 L₀ → 1. Таблица по тем же 160 узлам ln p, что у λₖ; ниже и
        /// выше таблицы — крайний узел. Узел, где решатель не сошёлся (медленный позитрон под
        /// барьером: плотность там нулевая) или L₀ вне 0.5…2, берёт ближайший годный узел сверху.
        /// </summary>
        public static double FiniteSizeL0(int z, int massNumber, bool positron, double p)
        {
            if (z <= 0 || !(p > 0.0))
            {
                return 1.0;
            }

            string key = z.ToString(CultureInfo.InvariantCulture) + "|" + massNumber.ToString(CultureInfo.InvariantCulture)
                         + "|" + (positron ? "+" : "-");
            double[] table;
            lock (Gate)
            {
                FiniteSizeTables.TryGetValue(key, out table);
            }

            if (table == null)
            {
                table = FiniteSizeTable(z, massNumber, positron);
                lock (Gate)
                {
                    FiniteSizeTables[key] = table;
                }
            }

            double x = (Math.Log(p) - LnPMin) / (LnPMax - LnPMin) * (Nodes - 1);
            if (x <= 0.0)
            {
                return table[0];
            }

            if (x >= Nodes - 1)
            {
                return table[Nodes - 1];
            }

            int i = (int)Math.Floor(x);
            double t = x - i;
            double y0 = table[Math.Max(0, i - 1)], y1 = table[i], y2 = table[Math.Min(Nodes - 1, i + 1)], y3 = table[Math.Min(Nodes - 1, i + 2)];
            double value = 0.5 * (2.0 * y1 + (-y0 + y2) * t + (2.0 * y0 - 5.0 * y1 + 4.0 * y2 - y3) * t * t
                                  + (-y0 + 3.0 * y1 - 3.0 * y2 + y3) * t * t * t);
            return value > 0.0 && !double.IsInfinity(value) ? value : y1;
        }

        /// <summary>(`a274L`) L₀ прямым счётом в точке (без таблицы) — пробе для сверки интерполяции; NaN — не сошёлся.</summary>
        public static double FiniteSizeL0Direct(int z, int massNumber, bool positron, double p, double reach)
        {
            double az = (positron ? -1.0 : 1.0) * FineStructure * z;
            double radius = Radius(massNumber);
            double w = Math.Sqrt(1.0 + p * p);
            double sum = AmplitudeSquared(-1, az, radius, w, reach) + AmplitudeSquared(1, az, radius, w, reach);
            return sum / (2.0 * p * p * PointF0(az, radius, w, p));
        }

        /// <summary>(`a274L`) Число узлов таблицы L₀, взятых у соседа (решатель не сошёлся или L₀ вне 0.5…2), — пробе.</summary>
        public static int FiniteSizeL0Patched(int z, int massNumber, bool positron)
        {
            int patched = 0;
            double[] minus1 = Table(-1, z, massNumber, positron), plus1 = Table(1, z, massNumber, positron);
            double az = (positron ? -1.0 : 1.0) * FineStructure * z, radius = Radius(massNumber);
            for (int i = 0; i < Nodes; i++)
            {
                double p = Math.Exp(LnPMin + (LnPMax - LnPMin) * i / (Nodes - 1));
                double l0 = (minus1[i] + plus1[i]) / (2.0 * p * p * PointF0(az, radius, Math.Sqrt(1.0 + p * p), p));
                if (!(l0 >= 0.5 && l0 <= 2.0))
                {
                    patched++;
                }
            }

            return patched;
        }

        static double[] FiniteSizeTable(int z, int massNumber, bool positron)
        {
            double[] minus1 = Table(-1, z, massNumber, positron);
            double[] plus1 = Table(1, z, massNumber, positron);
            double az = (positron ? -1.0 : 1.0) * FineStructure * z;
            double radius = Radius(massNumber);
            var table = new double[Nodes];
            for (int i = 0; i < Nodes; i++)
            {
                double p = Math.Exp(LnPMin + (LnPMax - LnPMin) * i / (Nodes - 1));
                table[i] = (minus1[i] + plus1[i]) / (2.0 * p * p * PointF0(az, radius, Math.Sqrt(1.0 + p * p), p));
            }

            // Негодные узлы — у медленного позитрона снизу: берут ближайший годный сверху.
            double next = 1.0;
            for (int i = Nodes - 1; i >= 0; i--)
            {
                if (table[i] >= 0.5 && table[i] <= 2.0)
                {
                    next = table[i];
                }
                else
                {
                    table[i] = next;
                }
            }

            return table;
        }

        /// <summary>F₀ точечного ядра радиуса R в записи Hayen 2018 (множитель 4); αZ со знаком (+ — β⁻).</summary>
        static double PointF0(double az, double radius, double w, double p)
        {
            double g = Math.Sqrt(1.0 - az * az);
            double y = az * w / p;
            return Math.Exp(Math.Log(4.0) + 2.0 * (g - 1.0) * Math.Log(2.0 * p * radius) + Math.PI * y
                            + 2.0 * FsaBetaLibrary.ReLnGamma(g, y) - 2.0 * FsaBetaLibrary.ReLnGamma(2.0 * g + 1.0, 0.0));
        }

        /// <summary>λₖ сферы при импульсе p (единицы mₑc); k ≤ 1, Z ≤ 0 или p ≤ 0 — единица.</summary>
        public static double Lambda(int k, int z, int massNumber, bool positron, double p)
        {
            if (k <= 1 || z <= 0 || !(p > 0.0))
            {
                return 1.0;
            }

            double[] lam = LambdaTable(k, z, massNumber, positron);
            double x = (Math.Log(p) - LnPMin) / (LnPMax - LnPMin) * (Nodes - 1);
            if (x <= 0.0)
            {
                return Finite(lam[0]);
            }

            if (x >= Nodes - 1)
            {
                return Finite(lam[Nodes - 1]);
            }

            int i = (int)Math.Floor(x);
            double t = x - i;
            double y0 = lam[Math.Max(0, i - 1)], y1 = lam[i], y2 = lam[Math.Min(Nodes - 1, i + 1)], y3 = lam[Math.Min(Nodes - 1, i + 2)];
            if (!(IsFinite(y0) && IsFinite(y1) && IsFinite(y2) && IsFinite(y3)))
            {
                return Finite(t < 0.5 ? y1 : y2);
            }

            // Катмулл–Ром: проходит через узлы, гладкая первая производная.
            double value = 0.5 * (2.0 * y1 + (-y0 + y2) * t + (2.0 * y0 - 5.0 * y1 + 4.0 * y2 - y3) * t * t
                                  + (-y0 + 3.0 * y1 - 3.0 * y2 + y3) * t * t * t);
            return Finite(value);
        }

        /// <summary>λₖ сферы прямым счётом в точке (без таблицы) — пробе для сверки интерполяции.</summary>
        public static double LambdaDirect(int k, int z, int massNumber, bool positron, double p, double reach)
        {
            double az = (positron ? -1.0 : 1.0) * FineStructure * z;
            double radius = Radius(massNumber);
            double w = Math.Sqrt(1.0 + p * p);
            double top = AmplitudeSquared(-k, az, radius, w, reach) + AmplitudeSquared(k, az, radius, w, reach);
            double bottom = AmplitudeSquared(-1, az, radius, w, reach) + AmplitudeSquared(1, az, radius, w, reach);
            return Finite(top / bottom);
        }

        static bool IsFinite(double v)
        {
            return !double.IsNaN(v) && !double.IsInfinity(v) && v > 0.0;
        }

        static double Finite(double v)
        {
            return IsFinite(v) ? v : 1.0;
        }

        static double[] LambdaTable(int k, int z, int massNumber, bool positron)
        {
            double[] minus1 = Table(-1, z, massNumber, positron);
            double[] plus1 = Table(1, z, massNumber, positron);
            double[] minusK = Table(-k, z, massNumber, positron);
            double[] plusK = Table(k, z, massNumber, positron);
            var lam = new double[Nodes];
            for (int i = 0; i < Nodes; i++)
            {
                lam[i] = (minusK[i] + plusK[i]) / (minus1[i] + plus1[i]);
            }

            return lam;
        }

        static double[] Table(int kappa, int z, int massNumber, bool positron)
        {
            string key = z.ToString(CultureInfo.InvariantCulture) + "|" + massNumber.ToString(CultureInfo.InvariantCulture)
                         + "|" + (positron ? "+" : "-") + "|" + kappa.ToString(CultureInfo.InvariantCulture);
            lock (Gate)
            {
                double[] cached;
                if (Amplitudes.TryGetValue(key, out cached))
                {
                    return cached;
                }
            }

            double az = (positron ? -1.0 : 1.0) * FineStructure * z;
            double radius = Radius(massNumber);
            var table = new double[Nodes];
            for (int i = 0; i < Nodes; i++)
            {
                double p = Math.Exp(LnPMin + (LnPMax - LnPMin) * i / (Nodes - 1));
                table[i] = AmplitudeSquared(kappa, az, radius, Math.Sqrt(1.0 + p * p), 1.0);
            }

            lock (Gate)
            {
                Amplitudes[key] = table;
            }

            return table;
        }

        /// <summary>
        /// α_κ² для полной энергии W (единицы mₑc²), заряда αZ со знаком (+ — притяжение, β⁻) и
        /// радиуса сферы R; нормировка — F₀L₀ = (α₋₁² + α₁²)/(2p²). <paramref name="reach"/> —
        /// множитель дальности r_end (1 — рабочий, больше — проверка сходимости). NaN — счёт не
        /// удался (переполнение под барьером у медленного позитрона: плотность там нулевая).
        /// </summary>
        public static double AmplitudeSquared(int kappa, double az, double radius, double w, double reach)
        {
            double p = Math.Sqrt(Math.Max(0.0, w * w - 1.0));
            if (kappa == 0 || !(p > 0.0) || !(radius > 0.0))
            {
                return double.NaN;
            }

            int k = Math.Abs(kappa);
            double v0 = -1.5 * az / radius;
            double odd = 1.0;
            for (int j = 2 * k - 1; j > 1; j -= 2)
            {
                odd *= j;
            }

            double c = Math.Pow(p, k - 1) / odd;
            double r0 = 1.0e-4 * radius;
            double u, v;
            if (kappa < 0)
            {
                u = c * Math.Pow(r0, k);
                v = -(w - v0 - 1.0) * c * Math.Pow(r0, k + 1) / (2 * k + 1);
            }
            else
            {
                v = c * Math.Pow(r0, k);
                u = (w - v0 + 1.0) * c * Math.Pow(r0, k + 1) / (2 * k + 1);
            }

            // Дальность: ≥ 400 длин 1/p и область, где ВКБ по кулоновскому хвосту точен (|dP/dr|/P² ≤ 10⁻⁵).
            double rEnd = reach * Math.Max(400.0 / p, Math.Sqrt(Math.Abs(az) * w / (1.0e-5 * p * p * p)));
            rEnd = Math.Max(rEnd, 50.0 * radius);
            if (!Integrate(kappa, az, radius, w, ref u, ref v, r0, radius) || !Integrate(kappa, az, radius, w, ref u, ref v, radius, rEnd))
            {
                return double.NaN;
            }

            // Среднее инварианта по периоду 2π/P (два периода квадрата синуса), шаг RK4 — 1/256 периода.
            double pEnd = LocalMomentum(az, radius, w, rEnd);
            double period = 2.0 * Math.PI / pEnd;
            const int Steps = 256;
            double h = period / Steps, r = rEnd, sum = 0.0;
            for (int s = 0; s <= Steps; s++)
            {
                double inv = Invariant(az, radius, w, r, u, v);
                sum += (s == 0 || s == Steps ? 0.5 : 1.0) * inv;
                if (s < Steps)
                {
                    Rk4(kappa, az, radius, w, r, h, ref u, ref v);
                    r += h;
                }
            }

            double a2 = sum / Steps;
            double alpha2 = (p / w) / a2;
            return alpha2 > 0.0 && !double.IsInfinity(alpha2) ? alpha2 : double.NaN;
        }

        static double Potential(double az, double radius, double r)
        {
            return r < radius ? -az / (2.0 * radius) * (3.0 - r * r / (radius * radius)) : -az / r;
        }

        static double LocalMomentum(double az, double radius, double w, double r)
        {
            double e = w - Potential(az, radius, r);
            return Math.Sqrt(Math.Max(1e-300, e * e - 1.0));
        }

        static double Invariant(double az, double radius, double w, double r, double u, double v)
        {
            double e = w - Potential(az, radius, r);
            return LocalMomentum(az, radius, w, r) * (u * u / (e + 1.0) + v * v / (e - 1.0));
        }

        static void Derivative(int kappa, double az, double radius, double w, double r, double u, double v,
                               out double du, out double dv)
        {
            double e = w - Potential(az, radius, r);
            du = -kappa / r * u + (e + 1.0) * v;
            dv = kappa / r * v - (e - 1.0) * u;
        }

        static void Rk4(int kappa, double az, double radius, double w, double r, double h, ref double u, ref double v)
        {
            double k1u, k1v, k2u, k2v, k3u, k3v, k4u, k4v;
            Derivative(kappa, az, radius, w, r, u, v, out k1u, out k1v);
            Derivative(kappa, az, radius, w, r + 0.5 * h, u + 0.5 * h * k1u, v + 0.5 * h * k1v, out k2u, out k2v);
            Derivative(kappa, az, radius, w, r + 0.5 * h, u + 0.5 * h * k2u, v + 0.5 * h * k2v, out k3u, out k3v);
            Derivative(kappa, az, radius, w, r + h, u + h * k3u, v + h * k3v, out k4u, out k4v);
            u += h / 6.0 * (k1u + 2.0 * k2u + 2.0 * k3u + k4u);
            v += h / 6.0 * (k1v + 2.0 * k2v + 2.0 * k3v + k4v);
        }

        /// <summary>Дорман–Принс 5(4) с выбором шага; ложь — переполнение или исчерпан счётчик шагов.</summary>
        static bool Integrate(int kappa, double az, double radius, double w, ref double u, ref double v, double from, double to)
        {
            const double Tol = 1.0e-10;
            double r = from;
            double h = Math.Max(1e-3 * (to - from), 1e-6 * from);
            for (int guard = 0; guard < 2000000 && r < to; guard++)
            {
                if (r + h > to)
                {
                    h = to - r;
                }

                double k1u, k1v, k2u, k2v, k3u, k3v, k4u, k4v, k5u, k5v, k6u, k6v, k7u, k7v;
                Derivative(kappa, az, radius, w, r, u, v, out k1u, out k1v);
                Derivative(kappa, az, radius, w, r + h / 5.0, u + h * (k1u / 5.0), v + h * (k1v / 5.0), out k2u, out k2v);
                Derivative(kappa, az, radius, w, r + 3.0 * h / 10.0,
                           u + h * (3.0 / 40.0 * k1u + 9.0 / 40.0 * k2u), v + h * (3.0 / 40.0 * k1v + 9.0 / 40.0 * k2v), out k3u, out k3v);
                Derivative(kappa, az, radius, w, r + 4.0 * h / 5.0,
                           u + h * (44.0 / 45.0 * k1u - 56.0 / 15.0 * k2u + 32.0 / 9.0 * k3u),
                           v + h * (44.0 / 45.0 * k1v - 56.0 / 15.0 * k2v + 32.0 / 9.0 * k3v), out k4u, out k4v);
                Derivative(kappa, az, radius, w, r + 8.0 * h / 9.0,
                           u + h * (19372.0 / 6561.0 * k1u - 25360.0 / 2187.0 * k2u + 64448.0 / 6561.0 * k3u - 212.0 / 729.0 * k4u),
                           v + h * (19372.0 / 6561.0 * k1v - 25360.0 / 2187.0 * k2v + 64448.0 / 6561.0 * k3v - 212.0 / 729.0 * k4v),
                           out k5u, out k5v);
                Derivative(kappa, az, radius, w, r + h,
                           u + h * (9017.0 / 3168.0 * k1u - 355.0 / 33.0 * k2u + 46732.0 / 5247.0 * k3u + 49.0 / 176.0 * k4u - 5103.0 / 18656.0 * k5u),
                           v + h * (9017.0 / 3168.0 * k1v - 355.0 / 33.0 * k2v + 46732.0 / 5247.0 * k3v + 49.0 / 176.0 * k4v - 5103.0 / 18656.0 * k5v),
                           out k6u, out k6v);
                double nu = u + h * (35.0 / 384.0 * k1u + 500.0 / 1113.0 * k3u + 125.0 / 192.0 * k4u - 2187.0 / 6784.0 * k5u + 11.0 / 84.0 * k6u);
                double nv = v + h * (35.0 / 384.0 * k1v + 500.0 / 1113.0 * k3v + 125.0 / 192.0 * k4v - 2187.0 / 6784.0 * k5v + 11.0 / 84.0 * k6v);
                Derivative(kappa, az, radius, w, r + h, nu, nv, out k7u, out k7v);
                double eu = h * (71.0 / 57600.0 * k1u - 71.0 / 16695.0 * k3u + 71.0 / 1920.0 * k4u - 17253.0 / 339200.0 * k5u + 22.0 / 525.0 * k6u - 1.0 / 40.0 * k7u);
                double ev = h * (71.0 / 57600.0 * k1v - 71.0 / 16695.0 * k3v + 71.0 / 1920.0 * k4v - 17253.0 / 339200.0 * k5v + 22.0 / 525.0 * k6v - 1.0 / 40.0 * k7v);
                double scale = Math.Max(Math.Sqrt(nu * nu + nv * nv), Math.Sqrt(u * u + v * v));
                if (!(scale > 0.0) || double.IsInfinity(scale) || double.IsNaN(scale))
                {
                    return false;
                }

                double err = Math.Sqrt(eu * eu + ev * ev) / (Tol * scale);
                if (err <= 1.0)
                {
                    r += h;
                    u = nu;
                    v = nv;
                }

                double factor = err > 0.0 ? 0.9 * Math.Pow(err, -0.2) : 5.0;
                h *= Math.Min(5.0, Math.Max(0.2, factor));
                if (!(h > 0.0))
                {
                    return false;
                }
            }

            return r >= to;
        }
    }

    /// <summary>
    /// (`AMBER274`, полоса `a274s` 13.11.2026) ЭКРАНИРОВАНИЕ ЯДРА АТОМНЫМИ ЭЛЕКТРОНАМИ — множитель
    /// S(Z, W) к функции Ферми при ключе <see cref="FsaBetaLibrary.FermiScreening"/>.
    ///
    /// Формула — Бюринг (1984) в записи Hayen и др., Rev. Mod. Phys. 90 (2018) 015008, §VII.A,
    /// ур. 144 и 146, с X = 1 (там же: «setting X equal to unity … gives better results»):
    ///   S = (W̃/W)·|Γ(γ+iỹ)/Γ(γ+iy)|²·|Γ(γ+2ip̃/λ)/Γ(1+2ip/λ)|²·e^{−πy}·(2p/λ)^{2(1−γ)},
    ///   W̃ = W ∓ ½αZₚλ, p̃ = ½p + ½√(p² ∓ 2αZW̃λ), y = ±αZW/p, ỹ = ±αZW̃/p̃
    /// (верхний знак — β⁻, нижний — β⁺; Z — дочь, Zₚ — родитель: электроны атома в мгновенном
    /// приближении остаются на орбитах родителя). λ = 2Σᵢ AᵢBᵢ — потенциал Салвата родителя
    /// V(r) = ∓(αZ/r)Σᵢ Aᵢe^{−Bᵢr} у начала координат (ур. 147–148; Salvat и др., Phys. Rev. A 36
    /// (1987) 467, Z = 1…92; выше 92 — Мольер, как в BSG). p̃ и ỹ комплексные (у медленного
    /// электрона корень мнимый), lnΓ — с отражением при Re &lt; ½. Запись и порядок множителей —
    /// по исходнику BSG (`SpectralFunctions::AtomicScreeningCorrection`, `screening::PotParam`);
    /// счёт ведётся в логарифмах (у тяжёлых ядер множители по отдельности переполняются).
    ///
    /// Выбор против Роуза (W̃ = W ∓ V₀, S = p̃W̃F(W̃)/(pWF(W)), ур. 139): Роуз не определён ниже V₀
    /// (разрыв у электрона ниже ~10 кэВ), и на рис. 5 Hayen 2018 (⁴⁵Ca) он дальше от численного
    /// счёта с потенциалом Салвата, чем ур. 144 со сдвигом ур. 148.
    ///
    /// Проверки — проба `FermiScreeningProbeA274 --mode=control`: Z → 0 даёт 1; предел больших W —
    /// первый порядок Роуза (ур. 141); сверка с независимым портом BSG критика `crit274L`
    /// (scipy) и с рис. 5 Hayen 2018; мутанты знака и потенциала пойманы.
    /// </summary>
    public static class AtomicScreening
    {
