            { 0.2448, 0.6298, 25.252, 3.6397, 0.9825 },   // 92
        };

        /// <summary>
        /// λ = 2Σᵢ AᵢBᵢ потенциала атома с зарядом ядра <paramref name="zAtom"/> в единицах mₑc/ħ
        /// (параметры Салвата при Z ≤ 92, Мольер выше; Z ≤ 0 — нуль).
        /// </summary>
        public static double Lambda(int zAtom)
        {
            if (zAtom < 0)
            {
                zAtom = -zAtom;
            }

            if (zAtom == 0)
            {
                return 0.0;
            }

            double s;
            if (zAtom > 92)
            {
                double b = 0.88534 * Math.Pow(zAtom, -1.0 / 3.0);
                s = 0.1 * 6.0 / b + 0.55 * 1.2 / b + 0.35 * 0.3 / b;
            }
            else
            {
                int i = zAtom - 1;
                double a1 = Salvat[i, 0], a2 = Salvat[i, 1], a3 = 1.0 - (a1 + a2);
                s = a1 * Salvat[i, 2] + a2 * Salvat[i, 3] + a3 * Salvat[i, 4];
            }

            return 2.0 * s * FineStructure;
        }

        /// <summary>
        /// S(Z, W) для ветви с дочерью заряда <paramref name="zDaughter"/>: β⁻ — родитель Z − 1,
        /// β⁺ — Z + 1. Z ≤ 0, родитель без электронов или W ≤ 1 — единица.
        /// </summary>
        public static double Correction(int zDaughter, double w, bool positron)
        {
            int betaType = positron ? -1 : 1;
            int zParent = zDaughter - betaType;
            if (zDaughter <= 0 || zParent <= 0 || !(w > 1.0))
            {
                return 1.0;
            }

            double s = CorrectionWith(zDaughter, zParent, Lambda(zParent), w, betaType);
            return s > 0.0 && !double.IsInfinity(s) && !double.IsNaN(s) ? s : 1.0;
        }

        /// <summary>
        /// Формула ур. 144 при заданных зарядах (дробных — для проверки предела Z → 0) и λ;
        /// <paramref name="betaType"/> = +1 (β⁻) или −1 (β⁺). Пробе — контроль и мутанты.
        /// </summary>
        public static double CorrectionWith(double zDaughter, double zParent, double lambda, double w, int betaType)
        {
            if (!(lambda > 0.0) || !(w > 1.0))
            {
                return 1.0;
            }

            double az = FineStructure * zDaughter;
            if (az >= 0.99)
            {
                az = 0.99;
            }

            double p = Math.Sqrt(w * w - 1.0);
            double gamma = Math.Sqrt(1.0 - az * az);
            double wt = w - betaType * 0.5 * FineStructure * zParent * lambda;

            // p̃ = ½p + ½√(p² − β·2αZW̃λ): под корнем бывает минус (медленный электрон) — корень мнимый.
            double radicand = p * p - betaType * 2.0 * az * wt * lambda;
            double ptRe = 0.5 * p, ptIm = 0.0;
            if (radicand >= 0.0)
            {
                ptRe += 0.5 * Math.Sqrt(radicand);
            }
            else
            {
                ptIm = 0.5 * Math.Sqrt(-radicand);
            }

            double y = betaType * az * w / p;

            // ỹ = β·αZW̃/p̃ (комплексное деление).
            double den = ptRe * ptRe + ptIm * ptIm;
            double ytRe = betaType * az * wt * ptRe / den;
            double ytIm = -betaType * az * wt * ptIm / den;

            double lnFirst = Math.Log(wt / w);
            double lnSecond = 2.0 * (ReLnGammaAny(gamma - ytIm, ytRe) - ReLnGammaAny(gamma, y));
            double lnThird = 2.0 * (ReLnGammaAny(gamma - 2.0 * ptIm / lambda, 2.0 * ptRe / lambda) - ReLnGammaAny(1.0, 2.0 * p / lambda));
            double lnFourth = -Math.PI * y;
            double lnFifth = 2.0 * (1.0 - gamma) * Math.Log(2.0 * p / lambda);
            return Math.Exp(lnFirst + lnSecond + lnThird + lnFourth + lnFifth);
        }

        /// <summary>Re ln Γ(x + iy) при любом x (не в полюсах): x ≥ ½ — Ланцош, иначе отражение Γ(z)Γ(1−z) = π/sin(πz).</summary>
        internal static double ReLnGammaAny(double x, double y)
        {
            if (x >= 0.5)
            {
                return FsaBetaLibrary.ReLnGamma(x, y);
            }

            double py = Math.PI * Math.Abs(y);
            double lnSin;
            if (py > 30.0)
            {
                lnSin = py - Math.Log(2.0);
            }
            else
            {
                double sx = Math.Sin(Math.PI * x), sh = Math.Sinh(py);
                lnSin = 0.5 * Math.Log(sx * sx + sh * sh);
            }

            return Math.Log(Math.PI) - lnSin - FsaBetaLibrary.ReLnGamma(1.0 - x, -y);
        }
    }
